    async function api(path, options = {}) {
      if (isStandaloneFile()) return null;
      const { throwOnError = false, ...fetchOptions } = options || {};
      const headers = { 'Content-Type': 'application/json', ...workspaceHeader(), ...(fetchOptions.headers || {}) };
      try {
        // headers 必须在 fetchOptions 之后展开，否则调用方传了 headers 就会把工作区标识整个顶掉。
        if (String(fetchOptions.method||'GET').toUpperCase()==='POST' && BILLABLE_API_PATHS.has(path)) await preflightGeneration(path,JSON.parse(fetchOptions.body||'{}'));
        const response = await fetch(path, { ...fetchOptions, headers });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) {
          if (response.status === 401 && payload.error === 'unauthenticated') expireAuthenticatedSession();
          const error = new Error(payload.message || payload.error || `HTTP ${response.status}`);
          error.status = response.status; error.payload = payload;
          throw error;
        }
        return payload;
      } catch (error) {
        if(error.status===402)void notifyCreditShortage(error.payload||{message:error.message});
        console.warn('[CanvasFlow API]', path, error.message);
        if (throwOnError) throw error;
        return null;
      }
    }

    // 大文件（视频等）上传：**发原始二进制**，不走 api() 的 JSON 通道。
    // 原因：read_json 有 8MB 上限且要过 JSON/base64（体积再涨 33%），视频必然爆。
    // 返回 {mediaId, url, kind, size}，url 形如 `/media/media-<uuid>.mp4`。
    async function uploadMediaFile(file) {
      if (!file) return null;
      try {
        const response = await fetch('/api/media', {
          method: 'POST',
          headers: {
            'Content-Type': file.type || 'application/octet-stream',
            'X-Media-Type': file.type || '',
            'X-Media-Name': encodeURIComponent(file.name || ''),
            ...workspaceHeader(),
          },
          body: file,
        });
        const payload = await response.json().catch(() => ({}));
        if (!response.ok) throw new Error(payload.message || payload.error || `HTTP ${response.status}`);
        return payload.media || null;
      } catch (error) {
        console.warn('[CanvasFlow Media]', error.message);
        showToast(`素材保存失败：${error.message}`, '×');
        return null;
      }
    }

    // The snapshot has to carry the editable text too. Rebuilding a node from the bare type would
    // reset a renamed title and a written prompt on every reload, undo or project switch.
    // 文本节点正文的 HTML 形态：只有真的带标签时才返回，纯文本继续走 copy 字段。
    function promptCopyHtml(node) {
      const el = node?.querySelector('.node-copy');
      if (!el) return '';
      const html = el.innerHTML.trim();
      return /<[a-z][\s\S]*>/i.test(html) ? html : '';
    }

    function nodeSnapshot() {
      return $$('.flow-node').map(node => ({
        id: node.dataset.nodeId,
        type: node.dataset.node,
        left: parseFloat(node.style.left) || 0,
        top: parseFloat(node.style.top) || 0,
        // 卡片层级（右键「置于顶层 / 置于底层」的结果），载入时用来还原叠放次序。
        layer: nodeLayerOf(node),
        title: nodeLabelEl(node)?.textContent?.trim() || '',
        copy: node.dataset.node === 'script' ? (node.querySelector('.script-source')?.value || '') : (node.querySelector('.node-copy')?.textContent?.trim() || ''),
        trackId: node.dataset.trackId || '',
        audioUrl: node.dataset.audioUrl || '',
        audioName: node.dataset.audioName || '',
        generationJobId: node.dataset.generationJobId || '',
        appliedGenerationJobId: node.dataset.appliedGenerationJobId || '',
        generated: node.dataset.generated === 'true',
        jobStatus: node.dataset.jobStatus || '',
        jobError: node.dataset.jobError || '',
        videoUrl: node.dataset.videoUrl || node.querySelector('.output-preview')?.dataset.videoUrl || '',
        sourceDirectorId: node.dataset.sourceDirectorId || '',
        jobId: node.dataset.jobId || '',
        previewData: node.querySelector('.media-preview')?.dataset.previewData || '',
        titleCustom: node.dataset.titleCustom === '1',
        previewAsset: node.dataset.previewAsset || '',
        previewName: node.dataset.previewName || '',
        // 落盘后的直链（r684）。带上它，分享快照才能直接引用图片 ——
        // 分享页没有登录态，够不到需要鉴权的 /api/assets/<id>。
        previewMedia: node.dataset.previewMedia || '',
        rating: Number(node.dataset.rating) || 0,

        imageProjection: node.dataset.imageProjection || '',
        aspectRatio: node.dataset.aspectRatio || '',
        resolution: node.dataset.resolution || '',
        dimension: node.querySelector('.media-dimension')?.textContent?.trim() || '',
        // ★★★ 节点级整体缩放（角色参考卡片 0.6 / 三视图按行宽算）与媒体真实比例（高/宽）。
        //   两个都必须持久化 + 进 server.py 的 clean_graph 白名单：
        //   它们过去只活在 dataset 上，刷新后归零 → 卡片按 1 倍渲染（比应用时大 1/0.6 倍），
        //   而 left/top 还是按 0.6 倍尺寸排的 → 四张参考卡互相压在一起（用户报的就是这个）。
        nodeScale: node.dataset.nodeScale || '',
        mediaRatio: node.dataset.mediaRatio || '',
        ...(node.dataset.node === 'sourcefile' ? {
          fileName: node.dataset.fileName || '',
          fileKind: node.dataset.fileKind || '',
          fileSize: node.dataset.fileSize || '',
          fileAsset: node.dataset.fileAsset || '',
        } : {}),
        ...(node.dataset.node === 'director' ? {
          directorProject: node.dataset.directorProject || '',
        } : {}),
        // 文本节点支持富文本：只有真的带标签时才写 copyHtml，纯文本继续走 copy 字段（旧数据零迁移）。
        ...(node.dataset.node === 'prompt' ? {
          copyHtml: promptCopyHtml(node),
          textInstruction: node.dataset.textInstruction || '',
        } : {}),
        imageHistory: node.dataset.imageHistory || '',
        groupId: node.dataset.groupId || '',


        presetScene: node.dataset.presetScene || '',
        presetEntry: node.dataset.presetEntry || '',
        // ★ 预设**指定**的节点标题（与预设名可能不同：九宫格下拉建的「人像调节」节点，
        //   预设 title 是「人像质感调节」）。底部输入框的预设胶囊用它做标题 ——
        //   不能直接用节点标题：文本/图片节点没被预设改过名，标题是「文本节点」这种类型名。
        presetTitle: node.dataset.presetTitle || '',


        shots: node.dataset.shots || '',
        scriptAssets: node.dataset.scriptAssets || '',
        scriptTheme: node.dataset.scriptTheme || '',
        scriptStyle: node.dataset.scriptStyle || '',
        autoLink: node.dataset.autoLink || '',
      }));
    }

    function graphSnapshot() {
      const edges = window.CanvasFlowConnections?.getEdges?.() || window.__canvasflowPendingEdges || [];
      return { nodes: nodeSnapshot(), edges: Array.isArray(edges) ? edges.slice() : [], groups: (state.groups || []).map(group => ({ ...group })) };
    }

    function historySnapshot() {
      return { ...graphSnapshot(), zoom: state.zoom, panX: state.panX, panY: state.panY, projectName: state.projectName };
    }

    function resetHistoryBaseline() {
      state.history = [historySnapshot()];
      state.future = [];
    }

    function setGraphEdges(edges) {
      const normalized = Array.isArray(edges) ? edges : [];
      window.__canvasflowPendingEdges = normalized.slice();
      if (window.CanvasFlowConnections?.setEdges) {
        window.CanvasFlowConnections.setEdges(normalized);
        delete window.__canvasflowPendingEdges;
      }
    }

    function resetGraphEdges() {
      if (window.CanvasFlowConnections?.reset) {
        window.CanvasFlowConnections.reset();
        delete window.__canvasflowPendingEdges;
      } else {
        window.__canvasflowPendingEdges = [
          { id: 'edge-prompt-model', source: 'prompt-1', target: 'model-1' },
          { id: 'edge-model-output', source: 'model-1', target: 'output-1' },
        ];
      }
    }




    function inverseCanvasZoom() {
      return 1 / Math.max(state.zoom || 1, 0.01);
    }
    function updateTransform() {
      stage.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
      grid.style.transform = `translate(${state.panX % 40}px, ${state.panY % 40}px)`;
      stage.style.setProperty('--cf-viewport-zoom', String(state.zoom));
      stage.style.setProperty('--cf-inverse-zoom', String(inverseCanvasZoom()));
      const label = $('#zoomLabel');
      if (label) label.textContent = `${Math.round(state.zoom * 100)}%`;
      syncNodeOverlays();   // 同步各节点浮动 UI 的位置（预设面板已停用，见 renderNodePresetPanel）
      renderMiniMap();
    }

    // ----- 视角补间：双击放大 / 适应画布 / 新增节点跟随都走这里 -----
    // 为什么不用 CSS transition：.canvas-stage 的 transform 由 updateTransform() 统一写入，
    // 拖拽平移、滚轮缩放、拖动节点全都经过它 —— 给 stage 挂 transition 会让这些操作整体发黏、失去跟手感。
    // 所以只在「程序化视角变化」时跑一段显式补间，用户一有输入立刻中断定格。
    let viewportRaf = 0;
    let viewportCleanup = null;

    function prefersReducedMotion() {
      try { return window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches === true; } catch { return false; }
    }

    function stopViewportAnimation() {
      if (viewportRaf) { cancelAnimationFrame(viewportRaf); viewportRaf = 0; }
      if (viewportCleanup) { const cleanup = viewportCleanup; viewportCleanup = null; cleanup(); }
    }

    function animateViewport(targetZoom, targetPanX, targetPanY, { duration = 320 } = {}) {
      stopViewportAnimation();
      const fromZoom = state.zoom || 1;
      const fromPanX = state.panX || 0;
      const fromPanY = state.panY || 0;
      const toZoom = Number.isFinite(targetZoom) && targetZoom > 0 ? targetZoom : fromZoom;
      const toPanX = Math.round(Number(targetPanX) || 0);
      const toPanY = Math.round(Number(targetPanY) || 0);
      const apply = (zoom, panX, panY) => { state.zoom = zoom; state.panX = panX; state.panY = panY; updateTransform(); };
      const settle = () => {
        apply(toZoom, toPanX, toPanY);
        window.CanvasFlowConnections?.draw?.();
        // ★★ r813：视角定格后**必须刷一次浮层**。上方工具栏 / 底部 Dock 都是 `position:fixed`
        //   并按「节点 flow 坐标 × zoom + pan」摆位 —— 视角动了而浮层不动，用户看到的就是
        //   「上下工具栏和节点对不上」（新建节点后尤其明显：建完会 revealNode 平移视角）。
        syncNodeOverlays();
        scheduleSave();
      };
      if (!duration || prefersReducedMotion() || (fromZoom === toZoom && fromPanX === toPanX && fromPanY === toPanY)) {
        settle();
        return;
      }
      const started = performance.now();
      const onAbort = () => {
        // 当前帧的值已经写进 state，停手即定格，绝不能被动画继续拖着走。
        stopViewportAnimation();
        window.CanvasFlowConnections?.draw?.();
        syncNodeOverlays();   // ★ r813：同上，定格后浮层要跟上
        scheduleSave();
      };
      document.addEventListener('pointerdown', onAbort, true);
      window.addEventListener('wheel', onAbort, true);
      viewportCleanup = () => {
        document.removeEventListener('pointerdown', onAbort, true);
        window.removeEventListener('wheel', onAbort, true);
      };
      const step = now => {
        viewportRaf = 0;
        const progress = Math.min(1, (now - started) / duration);
        const eased = 1 - Math.pow(1 - progress, 3);
        apply(
          fromZoom + (toZoom - fromZoom) * eased,
          fromPanX + (toPanX - fromPanX) * eased,
          fromPanY + (toPanY - fromPanY) * eased,
        );
        if (progress < 1) viewportRaf = requestAnimationFrame(step);
        else { viewportCleanup?.(); viewportCleanup = null; settle(); }
      };
      viewportRaf = requestAnimationFrame(step);
    }






    function positionDockToNode() {
      const dock = $('#promptDock');
      if (!dock || !dock.classList.contains('dock-attached')) return;
      // 放大编辑态由 CSS 居中定位（且已 portal 到 body），别再用节点坐标覆盖内联 left/top。
      if (dock.classList.contains('is-expanded')) return;
      // ★★★ 多角度 / 打光编辑器打开时底栏必须让位：两者都贴在选中节点下方同一位置，
      //   而两个编辑器挂在 #canvasStage 里（stage 因 pan/zoom transform 形成层叠上下文、
      //   z-index:auto），底栏是 stage 的**兄弟节点**（z-index:40）——编辑器内部的 z-index
      //   写多高都越不出 stage 的上下文，底栏必然绘制在上层，把面板上半截（标题 / 预设页签 /
      //   球体预览 / 滑杆）整块压死、点不到（用户实测反馈）。统一在底栏定位入口收起，
      //   关闭编辑器时由 closeMultiAngleEditor / closeRelightEditor 调这里恢复。
      if (multiAngleSession || relightSession) { dock.classList.remove('is-open'); return; }
      const node = singleSelectedNode();

      if (!node || !node.offsetParent || node.dataset.node === 'director') { dock.classList.remove('is-open'); return; }
      const wrap = $('#canvasWrap');
      if (!wrap) { dock.classList.remove('is-open'); return; }
      const wrapRect = wrap.getBoundingClientRect();
      const rect = node.getBoundingClientRect();
      dock.classList.add('is-open');
      // 贴卡下方、水平居中于卡片；间距屏幕恒定 14px。dock 的 offsetParent 就是 #canvasWrap
      // （position:relative），所以直接用 wrap 内坐标写 left/top。
      //
      // ★★★ r877：**水平方向也要夹**。r876 只夹了竖直方向，线上仍然溢出 —— 因为
      //   `.prompt-dock.dock-attached:not(.non-video-context){ width:min(880px,100vw-48px) }`
      //   在视频节点下把底栏撑到 **880px**，而 `#canvasWrap` 的宽度是 `视口 - 侧栏`，
      //   1080 窗口下只有 **840px** —— **底栏天生比画布宽 40px**，再叠加「居中于节点」
      //   （节点靠右/靠左时中心偏出去）→ 左或右单边能溢出到 200px+，
      //   症状就是用户截图里「底栏右半边（含 系统 胶囊、发送键、提醒条右端）被切掉」。
      //   实测（1080×726，选中靠右视频节点）：dock 880px，`l:459 r:1339`，画布 `l:240 r:1080`
      //   → **右缘溢出 259px**；竖直夹取已生效（`clamped:1`）却仍有残边，就是这一层。
      //
      // 夹取统一规则（三段，顺序不能换）：
      //   ① 先按「贴节点下方 + 居中于节点」赋 left/top 并**强制重排**，读到真实宽高
      //      （提醒条是 `[hidden]` 切换的，底栏高度会在 281↔321 之间变）；
      //   ② 水平：`transform:translateX(-50%)` 意味着 left 是**中心**，所以要把 `center ± w/2`
      //      收进 `[GAP, usableW-GAP]`。★ 底栏比画布宽时（上面的 880 vs 840）**改为左对齐**，
      //      即 `center = GAP + w/2`，让它在画布内尽量靠左铺开（比居中两边都裁要好）；
      //   ③ 竖直：下方空间不够 → 整体上移保住下缘；上移后顶到画布顶 → 反向下压保住上缘。
      //      ★ 极端情况（底栏比画布还高）下「上缘优先」：允许底部溢出，因为顶部被裁会让
      //        用户连输入框都看不到。
      const wantedLeft = rect.left - wrapRect.left + rect.width / 2;   // 期望中心（wrap 内坐标）
      const wantedTop = rect.bottom - wrapRect.top + 14;
      // ★★★ r877 关键一步：**先把底栏宽度上限压到画布宽度**，再摆位。
      //   否则「880px 的底栏放进 840px 的画布」无论怎么摆都会溢出 40px（数学上无解）——
      //   只夹位置不改宽度 = 白夹。（这是 r876 修不干净的最后一层根因。）
      //   用 maxWidth 而不是 width，这样窄画布时才生效、宽画布保持 CSS 的 880px 原样。
      // ★ dock 是 #canvasWrap 的直接子节点、在 #canvasStage 之外 → **不吃画布缩放**，
      //   所以它的 offsetWidth/Height 就是 wrap 坐标系里的真实尺寸，不需要任何缩放换算。
      const GAP = 8;                       // 与画布边缘保留的呼吸距离
      const usableW = wrapRect.width;
      const usableH = wrapRect.height;     // 画布可视高度（= dock 的定位坐标空间高度）
      // ★★★ 收敛测量：压宽度会让「一行装不下的」底栏内容**换行 → 高度变大**，
      //   而「高度变大」又会让竖直夹取的位置变化。所以不能在写完 maxWidth 的同一次读里
      //   就定稿 —— 要「写宽度 → 读尺寸 → 摆位」迭代到稳定（通常 2 轮，上限 5 轮兜底）。
      //   ★★ 踩过的坑：把 `dock.style.maxWidth=...` 写在循环**外面** → 第一次读到的还是
      //      「换行前」的旧高度（247），算出来的 top=405，但渲染后底栏已经变成 281 高 →
      //      下缘照样溢出 26px。**必须在每轮迭代里都重写一次 maxWidth 触发重排**，
      //      第二轮才读得到换行后的真实高度。
      const maxW = Math.max(usableW - GAP * 2, 160);
      let dockW = 0;
      let dockH = 0;
      let left = wantedLeft;
      let top = wantedTop;
      for (let iter = 0; iter < 5; iter += 1) {
        dock.style.maxWidth = `${maxW}px`;      // ★ 每轮都写 → 强制重排，读到当前真实尺寸
        dock.style.left = `${wantedLeft}px`;
        dock.style.top = `${wantedTop}px`;
        const w = dock.offsetWidth || 0;
        const h = dock.offsetHeight || 0;
        // ---- ② 水平夹取（`translateX(-50%)` ⇒ left 是中心，要保证 center±w/2 在界内）----
        let nextLeft = wantedLeft;
        if (w > usableW - GAP * 2) {
          nextLeft = GAP + w / 2;                                   // 仍比画布宽（极小视口）→ 左对齐
        } else {
          const minC = GAP + w / 2;
          const maxC = usableW - GAP - w / 2;
          if (nextLeft < minC) nextLeft = minC;                     // 左缘收进画布
          if (nextLeft > maxC) nextLeft = maxC;                     // 右缘收进画布
        }
        // ---- ③ 竖直夹取 ----
        let nextTop = wantedTop;
        if (nextTop + h > usableH - GAP) nextTop = usableH - GAP - h;   // 下缘收进画布
        if (nextTop < GAP) nextTop = GAP;                               // 上缘收进画布
        const settled = (w === dockW && h === dockH && nextLeft === left && nextTop === top);
        dockW = w; dockH = h; left = nextLeft; top = nextTop;
        dock.style.left = `${left}px`;
        dock.style.top = `${top}px`;
        if (settled) break;
      }
      // ★ 记住「贴节点」的原位，供其它地方（如展开收起）还原；纯信息，不参与布局。
      dock.dataset.dockWantedTop = String(Math.round(wantedTop));
      dock.dataset.dockWantedLeft = String(Math.round(wantedLeft));
      dock.dataset.dockClamped = (top !== wantedTop || left !== wantedLeft) ? '1' : '';
    }




    function syncNodeOverlays() {
      positionQuickToolbar();
      positionTransformToolbar();
      positionMultiAngleEditor();
      positionRelightEditor();
      positionGridSplitPopover();
      positionGroupToolbar();
      positionDockToNode();
      // ★ 预设面板已停用（绑定预设不再渲染节点下方面板，提示词落到底部输入框），
      //   所以这里不再需要 `syncNodePresetPanelPositions()`。
    }

    const createdDraftProjectIds = new Set();
    async function sendProjectSnapshot(id, payload) {
        if(!isStandaloneFile()&&payload.ownerId!==currentUser().id)throw Object.assign(new Error('账户已切换'),{status:403});
        const { createDraft, ...snapshot } = payload;
        if (createDraft && !createdDraftProjectIds.has(id)) {
          // Recover a successful POST whose response was lost, rather than create a duplicate on retry.
          let existing;
          try { existing = await api(`/api/projects/${encodeURIComponent(id)}`, {throwOnError:true}); }
          catch (error) { if (error.status !== 404) throw error; }
          if (existing?.project) {
            snapshot.revision = Number(existing.project.revision) || 0;
          } else {
            const result = await api('/api/projects', {method:'POST', body:JSON.stringify({...snapshot, id}), throwOnError:true});
            if (result?.project?.id !== id) throw new Error('新画布保存失败，请重试');
            createdDraftProjectIds.add(id);
            return result;
          }
        }
        const result = await api(`/api/projects/${encodeURIComponent(id)}`,{method:'PUT',body:JSON.stringify(snapshot),throwOnError:true});
        if (createDraft) createdDraftProjectIds.add(id);
        return result;
    }
    const projectSaveQueue=window.CanvasFlowProjectSaveQueue.create({
      send:sendProjectSnapshot,
      onSaved:(id,result,payload)=>{
        if(state.projectId!==id)return;
        if (state.projectIsDraft) {
          state.projectIsDraft = false; state.lastOpenedProjectId = id;
          updateProjectUrl(id); refreshProjectBadge();
          const name = $('#projectName'); if (name) name.textContent = state.projectName;
        }
        state.projectRevision=Math.max(state.projectRevision,Number(result.project.revision)||0);
        if(payload.references)state.lastRefsSig=JSON.stringify(payload.references);
        const status=$('#saveStatus');if(status)status.textContent='已自动保存';
      },
      onConflict:(id)=>{
        if(state.projectId!==id)return;
        const status=$('#saveStatus');if(status)status.textContent='版本冲突 · 本机副本已保留';
        showToast('项目已在其他位置修改。当前编辑保留在本机，请重新打开项目核对后继续。','⚠');
      }
    });

    function saveProject() {
      // ★★★ 数据安全闸门（r788）：带 `?project=` 打开时，**在项目数据真正加载成功之前，绝不写回**。
      //   否则页面会停在 HTML 里的默认三节点图上，而任何一次自动保存都会把这份"默认图"
      //   覆盖到用户的真实项目里 —— 用户看到的就是"我的项目被清空了"。
      //   ★ 这个事故**真实发生过两次**（一次是未登录的新 profile，一次是加载竞态），
      //     两次都把用户的项目节点从 5 个冲成 3 个默认节点。
      //   开闸的三条路径：加载成功 / 404 走兜底项目 / 用户主动新建项目。
      if (state.projectLoadPending || !state.projectId) return;
      const saveProjectId=state.projectId;
      const graph = graphSnapshot();
      state.nodeCount = graph.nodes.length;
      if (state.projectIsDraft && !graph.nodes.length && !state.draftPersistenceRequested) return true;
      if (state.projectIsDraft) state.draftPersistenceRequested = true;
      const user = currentUser();
      const owner = { id: state.projectOwnerId || user.id, name: state.projectOwnerName || user.name, avatar: state.projectOwnerAvatar || user.avatar };
      const payload = { projectId: state.projectId, projectName: state.projectName, description: state.projectDescription || '', nodeCount: state.nodeCount, zoom: state.zoom, panX: state.panX, panY: state.panY, advancedSettings: state.advancedSettings, generationSettings: state.generationSettings, imageGenerationSettings: state.imageGenerationSettings, modelPrompt: state.modelPrompt || '', references: state.references || [], ownerId: owner.id, ownerName: owner.name, ownerAvatar: owner.avatar, shared: Boolean(state.projectShared), jobBindings: state.jobBindings || [], ...graph };
      safeStorage.set(payload);
      writeLocalProject(payload);
      const status = $('#saveStatus');
      if (isStandaloneFile()) {
        if (state.projectIsDraft) { state.projectIsDraft=false; state.lastOpenedProjectId=saveProjectId; updateProjectUrl(saveProjectId); }
        if (status) status.textContent='已保存到本机';
        return true;
      }
      if (status&&state.projectId===saveProjectId) status.textContent = '保存中…';
      // The server payload stays lean: previewData is a localStorage-only cache (the server keeps
      // the uploaded asset itself), and references are only re-sent when they actually changed so
      // typing in the prompt does not ship megabytes of base64 on every autosave.
      const refsSig = JSON.stringify(state.references || []);
      const refsChanged = refsSig !== state.lastRefsSig;
      // 分镜格子的预览图与节点预览同理：base64 只进本机缓存，服务器只保留 previewAsset 引用。
      const serverPayload = { ...payload, createDraft:Boolean(state.projectIsDraft), revision: state.projectRevision, nodes: graph.nodes.map(({ previewData, ...rest }) => ({ ...rest, cells: Array.isArray(rest.cells) ? rest.cells.map(({ previewData: _cellPreview, ...cellRest }) => cellRest) : undefined })) };
      if (!refsChanged) delete serverPayload.references;
      return projectSaveQueue.enqueue(saveProjectId,serverPayload).then(result=>{
        if(!result&&state.projectId===saveProjectId&&!projectSaveQueue.blocked(saveProjectId)&&status)status.textContent='已保存到本机';
        return Boolean(result);
      });
    }

    function scheduleSave() {
      clearTimeout(state.saveTimer);
      state.saveTimer = setTimeout(saveProject, 200);
    }

    // The desktop host waits for the final save before stopping its local service.
    window.CanvasFlowDesktop?.onBeforeClose(async () => {
      clearTimeout(state.saveTimer);
      if (state.projectLoadPending || !state.projectId) return true;
      return await saveProject() !== false;
    });

    function loadProject() {
      const requestedProjectId = new URLSearchParams(location.search).get('project');
      if (!requestedProjectId) { beginDraftCanvas(); return; }
      state.projectIsDraft = false;
      // ★★ 带 ?project= 打开时**先关闸门**：项目数据没到位之前，任何自动保存都不许写回。
      //    否则页面会停在 HTML 的默认三节点图上，一保存就把用户项目冲掉。
      state.projectLoadPending = !isStandaloneFile() || Boolean(requestedProjectId);
      const cached = requestedProjectId ? null : safeStorage.get();
      const saved = cached && !seedOnlyGraph(cached) && (!authenticatedUser || !cached.ownerId || cached.ownerId===authenticatedUser.id) ? cached : null;
      if (!requestedProjectId && !saved) { clearCurrentProject(); openView('projects'); return; }
      if (requestedProjectId) { state.projectId = requestedProjectId; state.lastOpenedProjectId = requestedProjectId; }
      if (saved) {
        state.projectId = saved.projectId || state.projectId;
        state.lastOpenedProjectId = state.projectId;
        state.projectName = saved.projectName || state.projectName;
        state.zoom = Number(saved.zoom) || 1;
        state.panX = Number(saved.panX) || 0;
        state.panY = Number(saved.panY) || 0;
        if (saved.advancedSettings) state.advancedSettings = { ...state.advancedSettings, ...saved.advancedSettings };
        if (saved.generationSettings) state.generationSettings = { ...defaultGenerationSettings(), ...saved.generationSettings };
        if (saved.imageGenerationSettings) state.imageGenerationSettings = normalizeImageGenerationSettings(saved.imageGenerationSettings);
        if (Array.isArray(saved.references)) state.references = saved.references;
        state.projectShared = Boolean(saved.shared); state.projectDescription = saved.description || '';
        state.modelPrompt = typeof saved.modelPrompt === 'string' ? saved.modelPrompt : '';
        state.projectOwnerId = saved.ownerId || ''; state.projectOwnerName = saved.ownerName || ''; state.projectOwnerAvatar = saved.ownerAvatar || '';
        applyJobBindings(saved.jobBindings);
        state.lastRefsSig = null;
      }
      const name = $('#projectName');
      if (name) name.textContent = state.projectName;
      updateNodeCount();
      if (Array.isArray(saved?.nodes)) { applyGraph(saved); resetHistoryBaseline(); }
      renderDockRefs();
      syncAdvancedSettings();
      syncGenerationControls();
      syncInspectorToNode($('.flow-node.selected'));
      const requestedId = state.projectId;
      const requestId = state.projectNavigationRequest = (state.projectNavigationRequest || 0) + 1;
      const headers = { ...workspaceHeader() };
      const projectRequest = isStandaloneFile()
        ? Promise.resolve({ project: findLocalProject(requestedId) })
        : fetch(`/api/projects/${encodeURIComponent(requestedId)}`, { headers })
          .then(async response => {
            if (response.status === 404) return { missing: true };
            if (!response.ok) return null;
            return response.json().catch(() => null);
          })
          .catch(() => null);
      projectRequest.then(result => {
        // 用户可能在请求期间打开了别的项目；迟到的旧图会覆盖新画布并被下一次自动保存落盘。
        if (state.projectId !== requestedId || state.isRestoring || requestId !== state.projectNavigationRequest
            || JSON.stringify(headers) !== JSON.stringify(workspaceHeader())) return;
        if (result?.missing) {
          activateFallbackProject();
          return;
        }
        const project = result?.project;
        // 加载失败（401 / 网络错误）→ **闸门保持关闭**：宁可不保存，也绝不拿默认图覆盖用户项目
        if (!project) return;
        state.projectLoadPending = false;   // 数据真的到位了，开闸
        state.projectRevision = Number(project.revision) || 0;
      projectSaveQueue.reset(state.projectId,state.projectRevision);
        state.projectName = project.projectName || state.projectName;
        state.zoom = Number(project.zoom) || state.zoom;
        state.panX = Number(project.panX) || state.panX;
        state.panY = Number(project.panY) || state.panY;
        state.advancedSettings = project.advancedSettings ? { ...defaultAdvancedSettings(), ...project.advancedSettings } : defaultAdvancedSettings();
        state.generationSettings = project.generationSettings ? { ...defaultGenerationSettings(), ...project.generationSettings } : defaultGenerationSettings();
        if (project.imageGenerationSettings) state.imageGenerationSettings = normalizeImageGenerationSettings(project.imageGenerationSettings);
        state.projectShared = Boolean(project.shared); state.projectDescription = project.description || '';
        state.modelPrompt = typeof project.modelPrompt === 'string' ? project.modelPrompt : '';
        state.references = Array.isArray(project.references) ? project.references : [];
        state.linkedRefs = [];
        applyJobBindings(project.jobBindings);
        state.lastRefsSig = null;
        renderDockRefs();
        if (Array.isArray(project.nodes)) applyGraph(project);
        if (Array.isArray(project.edges)) setGraphEdges(project.edges);
        if (name) name.textContent = state.projectName;
        updateNodeCount(); updateTransform(); resetHistoryBaseline(); syncAdvancedSettings(); syncGenerationControls(); syncInspectorToNode($('.flow-node.selected'));
        resumeJobBindings();
        resumeGenerationJobs();
        window.CanvasFlowStartup?.ready();
      });
    }






    function syncCanvasEmptyState() {
      const el = document.getElementById('canvasEmptyState');
      if (el) el.hidden = $$('.flow-node').length > 0;
    }

    function updateNodeCount() {
      const legend = $('.canvas-legend');
      if (legend) legend.innerHTML = `<span class="live-dot"></span> 无限画布 <span class="legend-sep">·</span> ${state.nodeCount} 个节点`;
      renderMiniMap();
      // 节点数一变就顺手刷一次空状态 —— 所有增删节点的路径最后都会走到这里。
      syncCanvasEmptyState();
    }

    function beginDraftCanvas() {
      clearCurrentProject();
      state.isRestoring = true;
      state.projectId = `project-${crypto.randomUUID()}`;
      state.projectIsDraft = true;
      state.draftPersistenceRequested = false;
      state.projectLoadPending = false;
      state.projectName = '未命名创作项目';
      state.zoom = 1; state.panX = 0; state.panY = 0;
      state.advancedSettings = defaultAdvancedSettings();
      state.generationSettings = defaultGenerationSettings();
      state.imageGenerationSettings = { modelId: 'flux-1.1' };
      state.projectShared = false; state.projectDescription = '';
      state.jobBindings = [];
      state.lastRefsSig = null;
      // 新项目不应继承上一个项目写在 Dock 里的提示词。
      state.modelPrompt = '';
      if (promptInput) promptInput.value = '';
      const newOwner = currentUser(); state.projectOwnerId = newOwner.id; state.projectOwnerName = newOwner.name; state.projectOwnerAvatar = newOwner.avatar;
      state.references = [];
      state.linkedRefs = [];
      state.groups = []; state.activeGroupId = null; renderGroups();
      renderDockRefs();
      resetCanvasNodes();
      state.projectRevision = 0;
      projectSaveQueue.reset(state.projectId,state.projectRevision);
      state.isRestoring = false;
      const name = $('#projectName');
      if (name) name.textContent = '新建画布';
      const status = $('#saveStatus'); if (status) status.textContent = '添加节点后自动保存';
      updateNodeCount(); updateTransform();
      resetGraphEdges();
      resetHistoryBaseline();
      openCanvas();
    }
    async function newProject() {
      if (state.projectCreationPending) return;
      const requestId = state.projectNavigationRequest = (state.projectNavigationRequest || 0) + 1;
      const viewEpoch = navigationEpoch;
      const headers = JSON.stringify(workspaceHeader());
      state.projectCreationPending = true;
      clearTimeout(state.saveTimer);
      try {
        if (state.projectId && !state.projectLoadPending && await saveProject() === false) {
          return showToast('当前项目尚未保存成功，请先重试保存，再新建项目', 'ⓘ');
        }
        if (requestId !== state.projectNavigationRequest || viewEpoch !== navigationEpoch || headers !== JSON.stringify(workspaceHeader())) return;
        beginDraftCanvas();
        showToast('已打开新画布，添加节点后自动保存为项目', '＋');
      } finally { state.projectCreationPending = false; }
    }
    window.CanvasFlow = { newProject };

    function openModal() { if (requireCurrentProject()) $('#modalBackdrop')?.classList.add('open'); }
    function closeModal() { $('#modalBackdrop')?.classList.remove('open'); }

    function setZoom(next, center) {
      const previous = state.zoom;
      state.zoom = Math.min(8, Math.max(.1, next));
      if (center) {
        const rect = wrap.getBoundingClientRect();
        const x = center.clientX - rect.left;
        const y = center.clientY - rect.top;
        state.panX = x - (x - state.panX) * state.zoom / previous;
        state.panY = y - (y - state.panY) * state.zoom / previous;
      }
      updateTransform();
      scheduleSave();
    }

    // Hold the zoom percentage with the left mouse button, then scrub
    // horizontally for continuous zoom control without repeated button clicks.
    const zoomLabel = $('#zoomLabel');
    let zoomScrub = null;
    function endZoomScrub() {
      if (!zoomScrub) return;
      clearTimeout(zoomScrub.holdTimer);
      zoomScrub = null;
      zoomLabel?.classList.remove('is-scrubbing');
    }
    zoomLabel?.addEventListener('pointerdown', event => {
      if (event.button !== 0) return;
      event.preventDefault();
      event.stopPropagation();
      endZoomScrub();
      zoomScrub = { startX: event.clientX, startZoom: state.zoom, active: false, holdTimer: null };
      zoomScrub.holdTimer = window.setTimeout(() => {
        if (!zoomScrub) return;
        zoomScrub.active = true;
        zoomLabel.classList.add('is-scrubbing');
        showToast('已进入缩放拖动，左右滑动调整画布', '↔');
      }, 180);
      zoomLabel.setPointerCapture?.(event.pointerId);
    });
    zoomLabel?.addEventListener('pointermove', event => {
      if (!zoomScrub?.active) return;
      event.preventDefault();
      event.stopPropagation();
      const delta = event.clientX - zoomScrub.startX;
      setZoom(zoomScrub.startZoom + delta * 0.004);
    });
    zoomLabel?.addEventListener('pointerup', endZoomScrub);
    zoomLabel?.addEventListener('pointercancel', endZoomScrub);
    zoomLabel?.addEventListener('lostpointercapture', endZoomScrub);
    zoomLabel?.addEventListener('wheel', event => {
      const steps = window.CanvasFlowScrub?.wheelSteps(event, zoomLabel);
      if (steps) setZoom(state.zoom + steps * (event.shiftKey ? 0.001 : 0.01));
    }, { passive: false });
    if (zoomLabel) zoomLabel.title = '左右拖动或滚轮调整缩放；Shift + 滚轮精细调整';

    // The overview used to be three decorative dots and a fake viewport rectangle. Render the real
    // graph and the real visible region instead, and let a click jump the canvas there.
    let miniMapView = null;
    function renderMiniMap() {
      const board = $('.mini-map-canvas');
      if (!board) return;
      const zoom = state.zoom || 1;
      const viewW = wrap?.clientWidth || 0;
      const viewH = wrap?.clientHeight || 0;
      const view = { left: -state.panX / zoom, top: -state.panY / zoom, width: (viewW / zoom) || 1, height: (viewH / zoom) || 1 };
      const boxes = $$('.flow-node').map(node => ({
        node,
        left: parseFloat(node.style.left) || 0,
        top: parseFloat(node.style.top) || 0,
        width: node.offsetWidth || NODE_SLOT_W,
        height: node.offsetHeight || NODE_SLOT_H,
      }));
      const frames = boxes.concat([view]);
      const minX = Math.min(...frames.map(box => box.left));
      const minY = Math.min(...frames.map(box => box.top));
      const spanX = Math.max(1, Math.max(...frames.map(box => box.left + box.width)) - minX);
      const spanY = Math.max(1, Math.max(...frames.map(box => box.top + box.height)) - minY);
      const boardW = board.clientWidth || 1;
      const boardH = board.clientHeight || 1;
      const scale = Math.min(boardW / spanX, boardH / spanY);
      const offsetX = (boardW - spanX * scale) / 2;
      const offsetY = (boardH - spanY * scale) / 2;
      miniMapView = { minX, minY, scale, offsetX, offsetY };
      const toMini = box => ({
        left: offsetX + (box.left - minX) * scale,
        top: offsetY + (box.top - minY) * scale,
        width: Math.max(3, box.width * scale),
        height: Math.max(3, box.height * scale),
      });
      const style = box => `left:${box.left.toFixed(1)}px;top:${box.top.toFixed(1)}px;width:${box.width.toFixed(1)}px;height:${box.height.toFixed(1)}px`;
      const dots = boxes.map(box => {
        const kind = box.node.dataset.node === 'model' ? 'mini-b' : box.node.dataset.node === 'output' ? 'mini-c' : 'mini-a';
        const active = box.node.classList.contains('selected') ? ' mini-active' : '';
        return `<span class="mini-node ${kind}${active}" style="${style(toMini(box))}"></span>`;
      }).join('');
      board.innerHTML = `${dots}<span class="mini-viewport" style="${style(toMini(view))}"></span>`;
    }

    function focusMiniMapPoint(event) {
      const board = $('.mini-map-canvas');
      if (!board || !miniMapView?.scale) return;
      const rect = board.getBoundingClientRect();
      const stageX = miniMapView.minX + (event.clientX - rect.left - miniMapView.offsetX) / miniMapView.scale;
      const stageY = miniMapView.minY + (event.clientY - rect.top - miniMapView.offsetY) / miniMapView.scale;
      const zoom = state.zoom || 1;
      state.panX = Math.round((wrap?.clientWidth || 0) / 2 - stageX * zoom);
      state.panY = Math.round((wrap?.clientHeight || 0) / 2 - stageY * zoom);
      updateTransform();
      window.CanvasFlowConnections?.draw?.();
      scheduleSave();
    }

    // Real "fit to content": frame every node instead of only snapping back to 100%. On an infinite
    // canvas a node can easily sit outside the viewport, and an unreachable node cannot be wired up.
    function fitCanvas() {
      const nodes = $$('.flow-node');
      const viewW = wrap?.clientWidth || 0;
      const viewH = wrap?.clientHeight || 0;
      if (!nodes.length || !viewW || !viewH) {
        animateViewport(1, 0, 0); showToast('已回到默认视图', '⌗');
        return;
      }
      const bounds = nodes.reduce((box, node) => {
        const left = parseFloat(node.style.left) || 0;
        const top = parseFloat(node.style.top) || 0;
        return {
          minX: Math.min(box.minX, left),
          minY: Math.min(box.minY, top),
          maxX: Math.max(box.maxX, left + (node.offsetWidth || NODE_SLOT_W)),
          maxY: Math.max(box.maxY, top + (node.offsetHeight || NODE_SLOT_H)),
        };
      }, { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity });
      const padding = 44;
      const contentW = Math.max(1, bounds.maxX - bounds.minX);
      const contentH = Math.max(1, bounds.maxY - bounds.minY);
      const raw = Math.min((viewW - padding * 2) / contentW, (viewH - padding * 2) / contentH, 1);
      const zoom = Math.min(8, Math.max(0.1, Math.round(raw * 1000) / 1000));
      animateViewport(
        zoom,
        Math.round((viewW - contentW * zoom) / 2 - bounds.minX * zoom),
        Math.round((viewH - contentH * zoom) / 2 - bounds.minY * zoom),
      );
      showToast(`已适配 ${nodes.length} 个节点`, '⌗');
    }


    function zoomToNode(node) {
      if (!node || !node.offsetParent) return;
      const viewW = wrap?.clientWidth || 0;
      const viewH = wrap?.clientHeight || 0;
      if (!viewW || !viewH) return;
      const left = parseFloat(node.style.left) || 0;
      const top = parseFloat(node.style.top) || 0;
      const width = node.offsetWidth || NODE_SLOT_W;
      const height = node.offsetHeight || NODE_SLOT_H;
      // 视口留 12% 边距；上限 2.5 避免糊成一片，下限 0.2 避免缩成一点。
      const fit = Math.min((viewW * 0.88) / Math.max(1, width), (viewH * 0.88) / Math.max(1, height));
      const zoom = Math.max(0.2, Math.min(2.5, Math.round(fit * 1000) / 1000));
      // 走补间而不是直接赋值 —— 否则双击卡片是「硬切」跳变（用户反馈的问题）。
      animateViewport(
        zoom,
        Math.round(viewW / 2 - (left + width / 2) * zoom),
        Math.round(viewH / 2 - (top + height / 2) * zoom),
      );
      showToast(`已放大到 ${Math.round(zoom * 100)}%`, '⤢');
    }




    const PALETTE_ICONS = {
      text: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/></svg>',
      image: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8.5" cy="9.5" r="1.5"/><path d="m4 17 5-5 4 4 3-3 4 4"/></svg>',
      video: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="12" height="12" rx="2"/><path d="m15 10 6-3v10l-6-3z"/></svg>',
      audio: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18V6l10-2v12"/><circle cx="6.5" cy="18" r="2.5"/><circle cx="16.5" cy="16" r="2.5"/></svg>',
      script: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 3h9l4 4v14H6z"/><path d="M15 3v4h4"/><path d="M9 12h7M9 16h5"/></svg>',
      director: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 21 8v8l-9 5-9-5V8z"/><path d="m3 8 9 5 9-5M12 13v8"/></svg>',
      upload: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg>',
      history: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>',
    };
    const NODE_PALETTE_ITEMS = [
      { kind: 'prompt', title: '文本', icon: PALETTE_ICONS.text },
      { kind: 'image', title: '图片', icon: PALETTE_ICONS.image },
      { kind: 'model', title: '视频', icon: PALETTE_ICONS.video },
      { kind: 'audio', title: '音频', icon: PALETTE_ICONS.audio },
      { kind: 'script', title: '脚本', icon: PALETTE_ICONS.script },
      { kind: 'director', title: '导演台', icon: PALETTE_ICONS.director },
    ];
    let nodePaletteEl = null;
    let nodePaletteOrigin = { left: 0, top: 0 };
    // 屏幕坐标 → 画布 flow 坐标（stage 的 translate + scale 的逆变换）。
    function canvasPointFromClient(clientX, clientY) {
      const rect = wrap?.getBoundingClientRect();
      if (!rect) return { left: 0, top: 0 };
      const zoom = state.zoom || 1;
      return {
        left: Math.round((clientX - rect.left - state.panX) / zoom),
        top: Math.round((clientY - rect.top - state.panY) / zoom),
      };
    }
    function onPaletteOutside(event) {
      if (nodePaletteEl && !nodePaletteEl.contains(event.target)) closeNodePalette();
    }
    function onPaletteKey(event) {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      event.stopPropagation();
      closeNodePalette();
    }
    function closeNodePalette() {
      document.removeEventListener('pointerdown', onPaletteOutside, true);
      document.removeEventListener('keydown', onPaletteKey, true);
      nodePaletteEl?.remove();
      nodePaletteEl = null;
    }
    function openNodePalette(clientX, clientY) {
      closeNodePalette();
      const el = document.createElement('div');
      el.className = 'ftv-palette';
      el.setAttribute('role', 'menu');
      el.setAttribute('aria-label', '添加节点与资源');
      el.innerHTML = `<div class="ftv-palette__group-title">添加节点</div>
        <div class="ftv-palette__list">${NODE_PALETTE_ITEMS.map(item => `<button class="ftv-palette__menu-item" type="button" role="menuitem" data-palette-node="${item.kind}"><span class="ftv-palette__menu-item-icon">${item.icon}</span><span class="ftv-palette__menu-item-title">${item.title}</span></button>`).join('')}</div>
        <div class="ftv-palette__divider"></div>
        <div class="ftv-palette__group-title">添加资源</div>
        <div class="ftv-palette__list">
          <button class="ftv-palette__menu-item" type="button" role="menuitem" data-palette-action="upload"><span class="ftv-palette__menu-item-icon">${PALETTE_ICONS.upload}</span><span class="ftv-palette__menu-item-title">上传</span></button>
          <button class="ftv-palette__menu-item" type="button" role="menuitem" data-palette-action="history"><span class="ftv-palette__menu-item-icon">${PALETTE_ICONS.history}</span><span class="ftv-palette__menu-item-title">从生成历史选择</span></button>
        </div>`;
      document.body.appendChild(el);
      // 夹在视口内，避免贴边时被裁掉。
      const w = el.offsetWidth, h = el.offsetHeight;
      el.style.left = `${Math.max(8, Math.min(window.innerWidth - w - 8, clientX))}px`;
      el.style.top = `${Math.max(8, Math.min(window.innerHeight - h - 8, clientY))}px`;
      nodePaletteEl = el;
      nodePaletteOrigin = canvasPointFromClient(clientX, clientY);
      el.addEventListener('click', event => {
        const nodeBtn = event.target.closest('[data-palette-node]');
        if (nodeBtn) {
          event.preventDefault();
          const kind = nodeBtn.dataset.paletteNode;
          closeNodePalette();
          return void addNode(kind, { near: nodePaletteOrigin, exact: true });
        }
        const actionBtn = event.target.closest('[data-palette-action]');
        if (!actionBtn) return;
        event.preventDefault();
        const action = actionBtn.dataset.paletteAction;
        const origin = nodePaletteOrigin;
        closeNodePalette();
        if (action === 'upload') {
          pendingUploadMode = 'node';
          state.pendingMediaNodeId = null;
          $('#fileInput')?.click();
          return;
        }
        if (action === 'history') return void openGenerationHistoryPicker(origin);
      });
      // 延后一拍再挂外部点击监听，否则当前这次 dblclick 会立刻把菜单关掉。
      setTimeout(() => document.addEventListener('pointerdown', onPaletteOutside, true), 0);
      document.addEventListener('keydown', onPaletteKey, true);
    }
    // 「从生成历史选择」：列出素材库里的图片资产，点一张落成图片节点。
    async function openGenerationHistoryPicker(origin) {
      const backdrop = document.createElement('div');
      backdrop.className = 'modal-backdrop app-dialog open ftv-history-picker';
      backdrop.innerHTML = `<div class="modal dialog-box ftv-history-picker__box"><button class="modal-close" type="button" data-history-picker-close>×</button><div class="modal-icon">⏱</div><h3>从生成历史选择</h3><p>选一条历史画面，作为图片节点放到画布上。</p><div class="ftv-history-picker__grid"><div class="editor-loading">正在读取历史资产…</div></div></div>`;
      document.body.appendChild(backdrop);
      const close = () => backdrop.remove();
      backdrop.addEventListener('click', event => {
        if (event.target === backdrop || event.target.closest('[data-history-picker-close]')) close();
      });
      const grid = backdrop.querySelector('.ftv-history-picker__grid');
      const result = await api('/api/assets').catch(() => null);
      // 带 mediaId 的素材内容不在列表里（列表只返回引用），得逐条单取；先按「有没有内容」筛，
      // 但**不能只看 asset.data** —— 落盘后的素材 data 是空的，那样会把新图全漏掉（r684）。
      const candidates = (result?.assets || []).filter(asset => asset.kind === 'image' && (asset.data || asset.mediaId)).slice(0, 30);
      const items = (await Promise.all(candidates.map(async asset => {
        if (asset.data) return asset;
        const detail = await api(`/api/assets/${encodeURIComponent(asset.id)}`).catch(() => null);
        return detail?.asset?.data ? { ...asset, data: detail.asset.data } : null;
      }))).filter(Boolean);
      if (!items.length) {
        grid.innerHTML = '<div class="editor-loading">还没有历史画面，先生成或上传一张图片。</div>';
        return;
      }
      grid.innerHTML = items.map(asset => `<button class="ftv-history-picker__item" type="button" data-history-picker-pick="${escapeHtml(asset.id)}" title="${escapeHtml(asset.name || '历史画面')}"><img src="${asset.data}" alt="" /><small>${escapeHtml(asset.name || '历史画面')}</small></button>`).join('');
      grid.addEventListener('click', event => {
        const pick = event.target.closest('[data-history-picker-pick]');
        if (!pick) return;
        const asset = items.find(item => item.id === pick.dataset.historyPickerPick);
        if (!asset) return;
        close();
        const node = addNode('image', { near: origin, exact: true, silent: true });
        if (!node) return showToast('画布放不下新节点', '×');
        setMediaNodeImage(node, asset.data, asset.name || '历史画面', asset.id, '历史资产');
        scheduleSave();
        showToast(`已从历史添加：${asset.name || '历史画面'}`, '⏱');
      });
    }


    function updateScriptShotCount(node) {
      const label = node?.querySelector('.script-shot-count');
      if (!label) return;
      const source = node?.querySelector('.script-source');
      const count = source
        ? source.value.split('\n').map(line => line.trim()).filter(Boolean).length
        : scriptShots(node).length;
      label.textContent = `${count} 个镜头`;
    }




    const SCRIPT_NODE_ART = '<svg viewBox="0 0 40 26" width="38" height="25" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M4 5h32" opacity=".85"/><path d="M10 13h26" opacity=".55"/><path d="M16 21h20" opacity=".3"/></g></svg>';
    const SCRIPT_STEPS = [
      { id: 'shots', label: '确认镜头', hint: '「确认镜头」— 至少 1 条镜头有画面内容' },
      { id: 'assets', label: '准备资产', hint: '「准备资产」— 为角色 / 场景 / 道具准备形象图' },
      { id: 'prompts', label: '合成提示词', hint: '「合成提示词」— 每镜生成分镜与视频运动提示词' },
    ];






    const SCRIPT_SHOT_SIZES = ['大远景', '远景', '全景', '中远景', '中景', '中近景', '近景', '特写'];
    const SCRIPT_CAMERA_MOVES = ['固定', '跟随', '环绕', '推镜', '拉镜', '摇镜', '移镜', '升降'];
    const SCRIPT_LIGHTING_OPTIONS = ['自然光', '暖光', '冷光', '逆光', '剪影'];
    const SCRIPT_DURATION_MIN = 5;
    const SCRIPT_DURATION_MAX = 15;
    const SCRIPT_ASSET_KINDS = [
      { id: 'character', label: '角色' },
      { id: 'scene', label: '场景' },
      { id: 'prop', label: '道具' },
    ];

    function scriptShots(node) {
      try {
        const raw = JSON.parse(node?.dataset?.shots || '[]');
        return Array.isArray(raw) ? raw : [];
      } catch { return []; }
    }


    const TEXT_MODEL_KEY = 'canvasflow-text-model';
    let textModelsCache = null;
    function textModelId() { return localStorage.getItem(TEXT_MODEL_KEY) || ''; }
    /** 当前选中的文本模型名（没有就退回第一个可用模型名）。 */
    function currentTextModelName() {
      const hit = (textModelsCache || []).find(model => model.id === textModelId());
      return (hit || (textModelsCache || [])[0] || {}).name || '选择模型';
    }
    function updateTextModelLabel() {
      const label = $('#textModelLabel');
      if (!label) return;
      label.textContent = currentTextModelName();
    }
    async function loadTextModels() {
      const result = await api('/api/ai/text-models').catch(() => null);
      textModelsCache = result?.models || [];
      // 后台停用/删除已选模型时自动回退到第一个可用模型，保证「合成提示词」始终命中有效条目。
      if (!textModelsCache.some(model => model.id === textModelId())) {
        localStorage.setItem(TEXT_MODEL_KEY, textModelsCache[0]?.id || '');
      }
      updateTextModelLabel();
      return textModelsCache;
    }
    /**
     * 文本模型下拉菜单。`onPick` 可选 —— 最终提示词面板里的模型按钮要用它回写自己的标签，
     * 底栏那颗按钮则只需要 `updateTextModelLabel()`（两处共用一份菜单）。
     */
    function openTextModelMenu(anchor, onPick) {
      // ★★ 不要把父弹窗关掉！原来这里一句 `closeScriptPopover()` 会把「最终提示词面板」
      //   整个收走，用户观感是"选个模型弹层就没了"，而且面板里的未保存内容也一起消失。
      //   改成：父弹窗记为 base 留着，菜单叠在上层（关了菜单能退回面板）。
      //   ★ 判据必须看**它是不是菜单**（`.script-popover--menu`），不能无条件摘 ——
      //     否则当 `scriptPopover` 本身就是父面板时会把面板摘掉（实测：panelAlive 变 false，
      //     连带按钮的 toggle 判断也失效，因为闭包里的 pop 已经不在 DOM 里了）。
      const prev = scriptPopover && document.contains(scriptPopover) ? scriptPopover : null;
      const prevIsMenu = Boolean(prev?.classList?.contains('script-popover--menu'));
      if (prevIsMenu) prev.remove();
      scriptPopoverBase = prevIsMenu ? (scriptPopoverBase || null) : prev;
      const models = textModelsCache || [];
      const pop = document.createElement('div');
      pop.className = 'script-popover script-popover--menu';
      pop.innerHTML = models.length
        ? models.map(model => `<button type="button" class="script-popover__item${model.id === textModelId() ? ' is-active' : ''}" data-text-model="${escapeHtml(model.id)}">${escapeHtml(model.name)}</button>`).join('')
        : '<div class="script-popover__hint">没有启用中的文本模型 —— 请到偏好设置 · 供应商设置里配置</div>';
      document.body.appendChild(pop);
      // ★ 记录"是谁叫出来的"，供统一的 `toggleScriptPopover()` 做「再点一下收起」判断
      //   （底栏 `#textModelSelectBtn` / 最终提示词面板的 `[data-prompt-model]` 两处共用这份菜单）。
      //   ★ 用 `data-anchor`（与 `openScriptPopover` 同一套标识），不要再各写一套 `data.for`。
      const anchorKey = scriptPopoverAnchorKey(anchor);
      if (anchorKey) pop.dataset.anchor = anchorKey;
      const rect = anchor.getBoundingClientRect();
      // ★ 水平方向**对齐锚点左沿**（不是居中）—— 用户实测：「菜单盖住左侧「标准画质」胶囊」。
      //   居中的话宽菜单会往左探出去盖住旁边的胶囊；左沿对齐不会越界。
      //   ★ 同时夹在视口内（留 8px 边距），并给自身一个 max-height + 滚动：
      //     「自身超长被截断」是因为菜单高度超过视口上方的可用空间却没有滚动条。
      pop.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - (pop.offsetWidth || 220) - 8))}px`;
      const menuH = pop.offsetHeight || 0;
      const roomAbove = rect.top - 8;
      if (menuH > roomAbove) {
        pop.style.maxHeight = `${Math.max(120, roomAbove - 8)}px`;
        pop.style.overflowY = 'auto';
      }
      // 底栏在屏幕下方，菜单**向上弹**
      pop.style.top = `${Math.max(8, rect.top - (pop.offsetHeight || menuH) - 8)}px`;
      pop.querySelectorAll('[data-text-model]').forEach(btn => btn.addEventListener('click', () => {
        localStorage.setItem(TEXT_MODEL_KEY, btn.dataset.textModel);
        updateTextModelLabel();
        // ★ 选完模型：只收菜单，**退回父弹窗**（用户还要继续点"立即合成提示词"）
        if (scriptPopoverBase) closeScriptPopover({ topOnly: true });
        else closeScriptPopover();
        if (typeof onPick === 'function') onPick(btn.textContent.trim());
        showToast(`已切换文本模型：${btn.textContent.trim()}`, '✦');
      }));
      scriptPopover = pop;
      bindPopoverDismiss();
    }
    function scriptAssets(node) {
      try {
        const raw = JSON.parse(node?.dataset?.scriptAssets || '[]');
        return Array.isArray(raw) ? raw : [];
      } catch { return []; }
    }

    function scriptShotReady(shot) {
      return Boolean(String(shot?.description || '').trim());
    }
    function scriptStepState(node) {
      const shots = scriptShots(node);
      const assets = scriptAssets(node);
      const withImage = assets.filter(item => item.imageAsset || item.imageMedia).length;
      const synthesized = shots.filter(shot => String(shot.prompt || '').trim()).length;
      const shotsReady = shots.length > 0 && shots.every(scriptShotReady);
      // ★★★ `assets.length === 0` 时 `0 === 0` 恒成立 → 空资产会算成「已完成」！
      //   这是「资产里都没东西却标绿」的真正根因（光拆 ready/passable 不够）——
      //   必须显式要求「至少有一个资产」，否则空集永远满足 `withImage === assets.length`。
      const assetsReady = assets.length > 0 && withImage === assets.length;
      const promptsReady = shots.length > 0 && synthesized === shots.length;
      return {
        shots: { ready: shotsReady, text: shots.length ? `${shots.length} 个镜头${shotsReady ? '已就绪' : '待核对'}` : '暂无镜头' },
        // ★★ 「这一步能不能往下走」与「这一步显示为已完成（绿底 ✓）」是两件事，必须拆开。
        //   用户实测反馈：「这个资产里都没有东西，你给数字 2 标绿色干嘛」——
        //   根因就是原来把"放行"直接当成了"完成"：`assets.length === 0 || ...` 让空资产
        //   也 `ready === true`，徽标于是显示绿底 ✓，但页面上一个资产都没有，自相矛盾。
        //   现在 `ready` **只表示真的做完了**（有资产且都有设定图）；"空资产也能往下走"
        //   改用下面的 `passable`（纯文字脚本不被卡死的诉求由它承担）。
        assets: {
          ready: assetsReady,
          passable: assets.length === 0 || assetsReady,
          // ★ 文案也一起说清：没有资产时**不要**写成"已完成"的口径
          text: assets.length ? `${withImage}/${assets.length} 已生成` : '暂无资产',
        },
        prompts: { ready: promptsReady, text: shots.length ? `${synthesized}/${shots.length} 已合成` : '暂无提示词' },
      };
    }

    function renderScriptSteps(node) {
      const host = node?.querySelector('[data-script-steps]');
      if (!host) return;
      const state = scriptStepState(node);
      host.innerHTML = SCRIPT_STEPS.map((step, index) => `${index ? '<span class="script-step-line"></span>' : ''}<span class="script-step${state[step.id].ready ? ' is-done' : ''}"><b>${index + 1}</b><i>${step.label}</i></span>`).join('');
    }



    let scriptPanelCtx = null;          // { node, stage }
    const SCRIPT_STAGE_NEXT = {
      shots: { id: 'assets', label: '→ 下一步：准备资产' },
      assets: { id: 'prompts', label: '→ 下一步：合成提示词' },
      // ★★ 第三步（合成提示词）到底了，**不再**放「⚡ 批量生视频」。
      //   用户原话：「这里的批量生视频不要，将一键合成提示词替换掉它」——
      //   两颗按钮重叠在同一块区域（footer 的这颗 + body 里的「一键合成全部提示词」）。
      //   现在 footer 这颗直接**变成**「一键合成全部提示词」，占据原来的位置。
      prompts: { id: '', label: '一键合成全部提示词', isPrimaryAction: true },
    };
    function scriptPanelEl() { return document.getElementById('scriptPanel'); }
    function openScriptPanel(node) {
      if (!node?.matches?.('.script-node')) return;
      let layer = scriptPanelEl();
      if (!layer) {
        layer = document.createElement('div');
        layer.className = 'script-panel-layer';
        layer.id = 'scriptPanel';
        layer.innerHTML = `<section class="script-panel" role="dialog" aria-modal="true" aria-label="脚本节点">
          <header class="script-panel__head">
            <span class="script-panel__icon">▤</span>
            <strong class="script-panel__name" data-script-name></strong>
            <!-- ★★ 这里原本还有一排「重新生成 / 批量生成分镜 / 批量生视频 / 下载」——
                 已删（用户：「这几个删了，在画布内的脚本节点上工具栏已经有了，没有必要多此一举」）。
                 那四颗在**画布上脚本节点的浮动工具栏**里（id 为 scriptFloatBar 的那个 div），
                 两处重复既挤占面板头部、又容易状态不同步（一边灰一边亮）。
                 ★ 别再往面板头部加回来。 -->
            <span class="script-panel__progress" data-script-progress></span>
            <button class="script-panel__close" type="button" data-script-close aria-label="关闭">×</button>
          </header>
          <nav class="script-stages" data-script-stages></nav>
          <div class="script-stage-body" data-script-body></div>
          <footer class="script-panel__foot">
            <button type="button" class="script-btn" data-script-add>＋ 添加镜头</button>
            <span class="script-panel__spacer"></span>
            <button type="button" class="script-btn is-primary" data-script-next></button>
          </footer>
        </section>`;
        layer.hidden = true;
        document.body.appendChild(layer);
        bindScriptPanelEvents(layer);
      }
      scriptPanelCtx = { node, stage: 'shots' };
      layer.hidden = false;
      renderScriptPanel();
    }
    function closeScriptPanel() {
      const layer = scriptPanelEl();
      if (layer) layer.hidden = true;
      closeScriptPopover();       // 单元格浮层挂在 body 上，得跟着一起收
      scriptPanelCtx = null;
    }
    /** 面板当前绑定的节点；节点被删掉就自动收起面板。 */
    function scriptPanelNode() {
      const node = scriptPanelCtx?.node;
      if (!node || !document.contains(node)) { closeScriptPanel(); return null; }
      return node;
    }
    function renderScriptPanel() {
      const layer = scriptPanelEl();
      const node = scriptPanelNode();
      if (!layer || !node || !scriptPanelCtx) return;
      const state = scriptStepState(node);
      const done = SCRIPT_STEPS.filter(step => state[step.id].ready).length;
      const nameEl = layer.querySelector('[data-script-name]');
      if (nameEl) nameEl.textContent = nodeLabel(node) || '脚本节点';
      const progress = layer.querySelector('[data-script-progress]');
      if (progress) progress.textContent = `${done}/3 完成后可批量生视频`;
      const stages = layer.querySelector('[data-script-stages]');
      if (stages) {
        stages.innerHTML = SCRIPT_STEPS.map((step, index) => `<button type="button" class="script-stage${scriptPanelCtx.stage === step.id ? ' is-active' : ''}${state[step.id].ready ? ' is-done' : ''}" data-script-stage="${step.id}"><b>${index + 1}</b><span><strong>${step.label}</strong><small>${state[step.id].text}</small></span></button>${index < SCRIPT_STEPS.length - 1 ? '<i class="script-stage-arrow">→</i>' : ''}`).join('');
      }
      const body = layer.querySelector('[data-script-body]');
      if (body) {
        if (scriptPanelCtx.stage === 'assets') renderScriptAssetsStage(body, node);
        else if (scriptPanelCtx.stage === 'prompts') renderScriptPromptsStage(body, node);
        else renderScriptShotsStage(body, node);
      }
      const addBtn = layer.querySelector('[data-script-add]');
      if (addBtn) addBtn.hidden = scriptPanelCtx.stage !== 'shots';
      const nextBtn = layer.querySelector('[data-script-next]');
      if (nextBtn) {
        const next = SCRIPT_STAGE_NEXT[scriptPanelCtx.stage];
        nextBtn.textContent = next.label;
        // ★ 第三步的这颗按钮是动作按钮（合成提示词），不是"下一步"，用 `data-script-synth-primary`
        //   把它和普通"下一步"区分开 —— 文案一样但语义不同（点它去合成、不切步骤）。
        if (next.isPrimaryAction) nextBtn.setAttribute('data-script-synth-primary', '');
        else nextBtn.removeAttribute('data-script-synth-primary');
        // ★ 第三步这颗按钮是「一键合成全部提示词」——它**永远可点**。
        //   合成弹窗自己会处理"没有可合成的镜头"（弹窗里给空态），不该在按钮层禁用：
        //   原来这句是给「⚡ 批量生视频」用的（没合成完就不让批量出片），语义已不适用。
        nextBtn.disabled = false;
      }
    }












    const SCRIPT_DIALOGUE_TYPES = { line: '台词', narration: '旁白' };





    const SCRIPT_ROW_TONES = {
      red: { label: '红', hex: '#ff5c5c' },
      yellow: { label: '黄', hex: '#ffc53d' },
      green: { label: '绿', hex: '#34d399' },
      blue: { label: '蓝', hex: '#3ba3ff' },
      gray: { label: '灰', hex: '#c9c6c2' },
    };

    /** 取镜头的有声内容行（结构化）；旧纯文本自动降级成旁白行，保证老项目不瞎。 */
    function scriptDialogueLines(shot) {
      const raw = Array.isArray(shot?.dialogueLines) ? shot.dialogueLines : null;
      if (raw) {
        return raw.map((item, index) => ({
          id: String(item?.id || `dl-${index}`),
          type: item?.type === 'narration' ? 'narration' : 'line',
          roleId: String(item?.roleId || ''),
          roleName: String(item?.roleName || ''),
          text: String(item?.text || ''),
        }));
      }
      // 旧数据：一段纯文本 → 每行一条旁白（不写回，纯展示）
      const legacy = String(shot?.dialogue || '');
      if (!legacy.trim()) return [];
      return legacy.split('\n').map(line => line.trim()).filter(Boolean)
        .map((text, index) => ({ id: `legacy-${index}`, type: 'narration', roleId: '', roleName: '', text, legacy: true }));
    }
    /** 角色下拉的选项：资产表里 kind === 'character' 的资产。 */
    function scriptRoleOptions(node) {
      return scriptAssets(node).filter(item => item.kind === 'character')
        .map(item => ({ id: String(item.id), name: String(item.name || '未命名角色') }));
    }
    /** 把行模型压成给模型看的一段文本（合成提示词时用）。 */
    function scriptDialogueText(shot) {
      const lines = scriptDialogueLines(shot);
      if (!lines.length) return '';
      return lines.map(item => {
        const label = SCRIPT_DIALOGUE_TYPES[item.type] || '台词';

        const who = item.type === 'line' ? (item.roleName || '未绑定') : '';
        return who ? `${label}（${who}）：${item.text}` : `${label}：${item.text}`;
      }).join('\n');
    }





    const SCRIPT_CELL_CONFIG = {


      duration: { hint: `范围 ${SCRIPT_DURATION_MIN}-${SCRIPT_DURATION_MAX} 秒；失焦自动保存`, placeholder: '5', single: true, width: 220 },

      description: { hint: '输入@选择资产；失焦自动保存', placeholder: '画面描述', rows: 5, width: 440 },
      shotSize: { hint: '点击选择景别', presets: SCRIPT_SHOT_SIZES, rows: 1, width: 200 },
      lighting: { hint: '点击编辑光影氛围', placeholder: '例如：日系青春动漫风、戏剧冲突氛围…', presets: SCRIPT_LIGHTING_OPTIONS, rows: 2, width: 330 },
      sfx: { hint: '点击编辑音效', placeholder: '例如：雨声、脚步声、远处车流…', rows: 2, width: 330 },
      cameraMove: { hint: '点击编辑运镜', placeholder: '例如：推镜、拉镜、摇镜、跟镜……', presets: SCRIPT_CAMERA_MOVES, rows: 2, width: 330 },
    };







    function scriptCellButton(shot, key, text, placeholder, assetNames) {
      const value = String(text || '').trim();
      // ★★ 展示态也要把 `@角色` 标成紫色 chip（用户：「不在编辑时也需要对角色进行颜色区分，
      //   和编辑区保持一致」）。直接复用编辑浮层那套 `highlightScriptAssets()` ——
      //   两边包出来的都是 `.script-at-tag`，颜色/圆角天然一致，不会再各写一套。
      // ★★★ 但外面**必须再包一层 `.script-cell-inner`**：`.script-col-desc .script-cell-btn` 是
      //   `display:flex; flex-direction:column`，而 flex 会把每个子元素**块化并沿交叉轴拉伸** ——
      //   直接把 span 塞进去，紫色底会拉满整行、后面的正文还被挤到下一行（用户实测就是这个）。
      //   包一层之后 inner 是唯一的 flex item，内部照常按行内流排版，chip 就贴着文字了。
      const shown = value
        ? (assetNames && assetNames.length
          ? `<span class="script-cell-inner">${highlightScriptAssets(value, assetNames)}</span>`
          : escapeHtml(value))
        : escapeHtml(placeholder || '');
      return `<button type="button" class="script-cell-btn${value ? '' : ' is-empty'}" data-script-cell-open="${key}" data-script-shot-id="${shot.id}" title="${escapeHtml(value || placeholder || '')}">${shown}</button>`;
    }




    function scriptDialogueCell(shot) {
      const lines = scriptDialogueLines(shot);
      const tip = lines.map(item => {
        const label = SCRIPT_DIALOGUE_TYPES[item.type] || '台词';
        return item.type === 'line' ? `${label}（${item.roleName || '未绑定'}）：${item.text}` : `${label}：${item.text}`;
      }).join('\n');
      const body = lines.length
        ? lines.slice(0, 3).map(item => {
          const label = SCRIPT_DIALOGUE_TYPES[item.type] || '台词';
          const who = item.type === 'line' ? `<i class="script-dlg-who">${escapeHtml(item.roleName || '未绑定')}</i>` : '';
          // ★ 单行文本不截断（用户：「文本过长的时候要显示全」），只折叠「超过 3 行」这种情况
          return `<span class="script-dlg-line"><em class="script-dlg-type is-${item.type}">${label}</em>${who}<span>${escapeHtml(item.text)}</span></span>`;
        }).join('') + (lines.length > 3 ? `<span class="script-dlg-more">+${lines.length - 3} 行</span>` : '')
        : '<span class="script-dlg-empty">点击添加台词 / 旁白</span>';
      return `<button type="button" class="script-cell-btn script-cell-btn--dialogue${lines.length ? '' : ' is-empty'}" data-script-cell-open="dialogue" data-script-shot-id="${shot.id}" title="${escapeHtml(tip || '点击添加台词 / 旁白')}">${body}</button>`;
    }
    /**
     * ★★ 列宽策略（用户两次点名：「文本过长的时候要显示全，不行就调整框的宽，
     *   让该行所有内容去适应这个变化」+「为什么画面描述，其他的都没有去适应宽度变化」）。
     *
     * 踩过的坑：`colgroup` 里给每列写死 `width:330px` 这类**固定值**时，即便
     * `table-layout:auto` 也会退化成"按指定宽度分配"——内容再长也只会在列内折行，
     * 列宽纹丝不动（实测：描述列 320 字符仍是 330px、光影列 2560 字符只有 176px）。
     * 于是整张表永远 1515px 宽、外层容器 1527px，**横向滚动根本不会出现**。
     *
     * 正确做法：`col` 上写 `min-width`（建议宽度当下限），**不写 `width`**。
     * 于是：内容短 → 列保持建议宽度，版面与之前一致；内容长 → 该列自己撑宽，
     * 整表变宽，由外层 `.script-table-wrap` 横向滚动兜底。冻结列的 `right:68px`
     * 只依赖"操作列"这一列的固定宽度，所以「操作列」是唯一保留 `width` 的列。
     */
    /**
     * ★★ 列宽策略（用户两次点名：「文本过长的时候要显示全，不行就调整框的宽，
     *   让该行所有内容去适应这个变化」+「为什么画面描述，其他的都没有去适应宽度变化」）。
     *
     * 踩过的坑（实测数据，别再走一遍）：
     *  ① `colgroup` 写死 `width:330px` 时，即便 `table-layout:auto` 也退化成"按指定宽度分配"：
     *     内容再长只在列内折行、列宽纹丝不动（描述列 320 字符仍 330px）。
     *  ② 只把 `col` 改成 `min-width` 又**反了过来**：没了上界，长内容把列无限撑宽 ——
     *     实测光影列被 2560 字撑成 **20510px**，整张表 2 万多像素，看起来就是"列完全没适应"。
     *  ③ 上界**不能写在 `<col>` 上**：`table-layout:auto` 下浏览器**忽略 `col` 的 `max-width`**
     *     （实测 `col{max-width:560}` 时列宽仍是 20510px）。写在 `td`/`th` 上才生效（→560px）。
     *
     * 所以最终方案：`<col>` 只给 **`min-width`**（短内容时的基线宽度，保证版面不塌），
     * 上界 `max-width` 全部交给 CSS 作用在 `td`/`th` 上（见 `styles.css` 的
     * 「列宽上下限」一节）。内容短 → 停在基线；内容长 → 撑开但不超过上限，超出在上限内折行。
     */
    const SCRIPT_TABLE_COLS = [
      // ★★ 「镜号」收窄（68 → 44）：用户实测「运镜框体都没完全展示出来，
      //   不行缩小一点镜号的长来让运镜的框体适应长度」。
      //   镜号最多就是 `01`/`02` 两位数 + 表头 2 个汉字，50px 足够（CSS 上界 52px）；
      //   省下的宽度按比例加给「运镜」，让它的输入框完整显示。
      { min: 50 },     // 镜号（★ 特意压窄，把宽度让给运镜）
      { min: 76 },     // 时长
      { min: 330 },    // 画面描述（长内容主力列）
      { min: 88 },     // 景别
      { min: 182 },    // 光影氛围
      { min: 294 },    // 对白·旁白
      { min: 162 },    // 音效
      { min: 200 },    // 运镜（★ 165 → 200：要放得下「例如：推镜、拉镜、摇镜、跟镜……」的完整框）
      { min: 116 },    // 最终提示词
      { width: 68 },   // 操作（★ 唯一固定宽：冻结列 right:68px 依赖它）
    ];
    function scriptTableColgroup() {
      return `<colgroup>${SCRIPT_TABLE_COLS.map(col => col.width
        ? `<col style="width:${col.width}px"/>`
        : `<col style="min-width:${col.min}px"/>`).join('')}</colgroup>`;
    }

    function scriptShotRow(shot, index, assetNames) {
      const promptText = String(shot.prompt || '').trim();

      const rowTone = SCRIPT_ROW_TONES[String(shot.tone || '')] ? ` data-script-tone="${escapeHtml(shot.tone)}"` : '';





      const hasPrompt = Boolean(promptText || String(shot.videoPrompt || '').trim());
      const promptStage = (scriptPanelCtx && scriptPanelCtx.stage === 'prompts' && !hasPrompt) ? ' is-prompt-stage' : '';
      const promptCell = shot.promptStatus === 'generating'
        ? '<span class="script-prompt-empty">提示词生成中…</span>'
        : `<button type="button" class="script-cell-btn script-cell-btn--prompt${hasPrompt ? '' : ' is-empty'}" data-script-prompt-open="${shot.id}" title="点击打开提示词窗口，可查看内容，或重新让 AI 根据最新分镜信息合成">${escapeHtml(hasPrompt ? '查看提示词' : '待生成提示词')}</button>`;
      return `<tr data-script-row="${shot.id}"${rowTone}>
        <td class="script-col-index"><span class="script-index-cell">${index + 1}</span></td>
        <td class="script-col-duration">${scriptCellButton(shot, 'duration', `${String(shot.duration || '5').replace(/[^\d.]/g, '') || '5'}s`, '5s')}</td>
        <td class="script-col-desc">${scriptCellButton(shot, 'description', shot.description, '描述此镜头中你想表现的内容', assetNames)}</td>
        <td class="script-col-shot-size">${scriptCellButton(shot, 'shotSize', shot.shotSize, '')}</td>
        <td>${scriptCellButton(shot, 'lighting', shot.lighting, '')}</td>
        <td class="script-col-dialogue">${scriptDialogueCell(shot)}</td>
        <td>${scriptCellButton(shot, 'sfx', shot.sfx, '')}</td>
        <td>${scriptCellButton(shot, 'cameraMove', shot.cameraMove, '')}</td>
        <td class="script-col-prompt${promptStage}">${promptCell}</td>
        <td class="script-col-ops"><button type="button" class="script-row-menu" data-script-row-menu="${shot.id}" aria-label="行操作" title="针对这一行镜头进行管理 —— 删除、设置标注颜色"><svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.85"/><circle cx="12" cy="12" r="1.85"/><circle cx="19" cy="12" r="1.85"/></svg></button></td>
      </tr>`;
    }
    function renderScriptShotsStage(body, node) {
      const shots = scriptShots(node);
      if (!shots.length) {
        body.innerHTML = '<div class="script-empty">暂无镜头 — 点左下角「＋ 添加镜头」开始写分镜</div>';
        return;
      }
      // ★ 资产名给「画面描述」列做 `@角色` 上色用（展示态与编辑态保持一致）
      const assetNames = scriptAssets(node).map(item => item.name).filter(Boolean);
      body.innerHTML = `<div class="script-table-wrap"><table class="script-table">
        ${scriptTableColgroup()}
        <thead><tr><th>镜号</th><th>时长</th><th class="is-left">画面描述</th><th>景别</th><th class="is-left">光影氛围</th><th class="is-left">对白·旁白</th><th class="is-left">音效</th><th class="is-left">运镜</th><th class="script-th--prompt">最终提示词</th><th>操作</th></tr></thead>
        <tbody>${shots.map((shot, index) => scriptShotRow(shot, index, assetNames)).join('')}</tbody></table></div>`;
    }





    function renderScriptAssetsStage(body, node) {
      const assets = scriptAssets(node);
      const style = String(node.dataset.scriptStyle || '');
      body.innerHTML = `
        <div class="script-style-row">
          <span class="script-style-label">全局风格</span>
          <button type="button" class="script-style-value" data-script-style-open title="点击编辑全局风格">${escapeHtml(style || '未设置')}</button>
        </div>
        ${SCRIPT_ASSET_KINDS.map(kind => {
          const list = assets.filter(item => item.kind === kind.id);
          return `<section class="script-asset-group">
            <h4>${kind.label}</h4>
            <div class="script-asset-row">
              ${list.map(item => {
                const hasImage = Boolean(item.imageAsset || item.imageMedia);
                const thumb = item.imageMedia || (item.imageAsset ? `/api/assets/${encodeURIComponent(item.imageAsset)}` : '');
                return `<article class="script-asset-tile${hasImage ? ' is-ready' : ''}" data-script-asset="${item.id}">
                  <div class="script-asset-thumb">${hasImage ? `<img src="${escapeHtml(thumb)}" alt="" />` : '生成或上传设定图'}</div>
                  <button type="button" class="script-asset-menu" data-script-asset-menu="${item.id}" aria-label="资产操作" title="选择图片 / AI 生成 / 跳转 / 清除 / 保存 / 删除"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="1.85"/><circle cx="12" cy="12" r="1.85"/><circle cx="19" cy="12" r="1.85"/></svg></button>
                  <strong class="script-asset-name" contenteditable="plaintext-only" role="textbox" spellcheck="false" data-script-asset-name="${item.id}" data-placeholder="未命名资产" title="点击即可编辑名称">${escapeHtml(String(item.name || ''))}</strong>
                  <small class="script-asset-desc" contenteditable="plaintext-only" role="textbox" spellcheck="false" data-script-asset-desc="${item.id}" data-placeholder="待补充描述" title="点击即可编辑描述">${escapeHtml(String(item.desc || ''))}</small>
                </article>`;
              }).join('')}
              <button type="button" class="script-asset-tile is-create" data-script-asset-create="${kind.id}"><span>＋</span>新增</button>
            </div>
          </section>`;
        }).join('')}
        <div class="script-asset-foot">
          <span class="script-asset-note">${assets.length
            ? '资产已就绪，如再次生成将会覆盖之前的角色 / 场景 / 道具等资产'
            : '还没有资产 —— 点上方「＋ 新增」添加角色、场景或道具'}</span>
        </div>`;
    }







    function renderScriptPromptsStage(body, node) {
      const shots = scriptShots(node);
      if (!shots.length) {
        body.innerHTML = '<div class="script-empty">暂无镜头 — 请先回到「确认镜头」写好分镜</div>';
        return;
      }
      const done = shots.filter(shot => String(shot.prompt || '').trim()).length;
      const assetNames = scriptAssets(node).map(item => item.name).filter(Boolean);
      body.innerHTML = `
        <div class="script-table-wrap is-prompts"><table class="script-table">
        ${scriptTableColgroup()}
        <thead><tr><th>镜号</th><th>时长</th><th class="is-left">画面描述</th><th>景别</th><th class="is-left">光影氛围</th><th class="is-left">对白·旁白</th><th class="is-left">音效</th><th class="is-left">运镜</th><th class="script-th--prompt">最终提示词</th><th>操作</th></tr></thead>
        <tbody>${shots.map((shot, index) => scriptShotRow(shot, index, assetNames)).join('')}</tbody></table></div>
        <div class="script-prompt-foot">
          <span class="script-asset-note">${done}/${shots.length} 已合成</span>
        </div>`;
    }

    // ----- 面板交互：切步骤 / 增删镜头 / 改字段 / 资产 / 合成 -----
    function bindScriptPanelEvents(layer) {
      layer.addEventListener('click', event => {
        if (event.target.closest('[data-script-close]') || event.target === layer) return closeScriptPanel();
        const stageBtn = event.target.closest('[data-script-stage]');
        if (stageBtn && scriptPanelCtx) { scriptPanelCtx.stage = stageBtn.dataset.scriptStage; return renderScriptPanel(); }
        if (event.target.closest('[data-script-add]')) return scriptAddShot();
        if (event.target.closest('[data-script-next]')) return scriptAdvanceStage();
        const cellOpen = event.target.closest('[data-script-cell-open]');
        if (cellOpen) {
          // ★★ 再点同一个单元格 → 收起（用户：「这些点击展开后再点击一次能够收起」）。
          //   锚点标识带上字段名，所以「点运镜单元格 → 再点音效单元格」是切换、
          //   而「点运镜 → 再点运镜」才是收起。
          if (toggleScriptPopover(cellOpen)) return;
          // ★「对白·旁白」是有角色绑定的行式编辑，走专用编辑器（其余字段走通用单元格浮层）。
          return cellOpen.dataset.scriptCellOpen === 'dialogue'
            ? openScriptDialoguePopover(cellOpen, cellOpen.dataset.scriptShotId)
            : openScriptCellPopover(cellOpen, cellOpen.dataset.scriptShotId, cellOpen.dataset.scriptCellOpen);
        }
        const promptOpen = event.target.closest('[data-script-prompt-open]');
        if (promptOpen) {
          if (toggleScriptPopover(promptOpen)) return;
          return openScriptPromptPopover(promptOpen, promptOpen.dataset.scriptPromptOpen);
        }
        const rowMenu = event.target.closest('[data-script-row-menu]');
        if (rowMenu) {
          if (toggleScriptPopover(rowMenu)) return;
          return openScriptRowMenu(rowMenu, rowMenu.dataset.scriptRowMenu);
        }
        const assetCreate = event.target.closest('[data-script-asset-create]');
        if (assetCreate) return scriptAddAsset(assetCreate.dataset.scriptAssetCreate);
        const assetMenu = event.target.closest('[data-script-asset-menu]');
        if (assetMenu) {
          if (toggleScriptPopover(assetMenu)) return;
          return openScriptAssetMenu(assetMenu, assetMenu.dataset.scriptAssetMenu);
        }
        const styleBtn = event.target.closest('[data-script-style-open]');
        if (styleBtn) {
          if (toggleScriptPopover(styleBtn)) return;
          return openScriptStylePopover(styleBtn);
        }
        if (event.target.closest('[data-script-synthesize]')) return openScriptSynthesizeModal();
        // ★ 面板里**不再有**「重新生成 / 批量生成分镜 / 批量生视频 / 下载」这四颗
        //   （已删，只保留画布上脚本节点的浮动工具栏 `#scriptFloatBar`），所以这里也不再接它们的事件 ——
        //   留着会让人以为面板里还有入口。
      });
      // ★ 输入时**不重绘整表**（会丢焦点/光标），只在 change（下拉、失焦）时重绘以刷新进度。
      const commit = event => {
        const field = event.target.closest('[data-script-field]');
        if (!field) return;
        scriptUpdateShotField(field.dataset.scriptShotId, field.dataset.scriptField, field.value, event.type === 'change');
      };
      layer.addEventListener('input', commit);
      layer.addEventListener('change', commit);
      // ★★ 资产描述：**就地可编辑**（用户：「这个地方应该可以编辑文本」）。
      //   用 `contenteditable` 而不是换 `<textarea>` —— 卡片高度是跟着缩略图固定的，
      //   插一个 textarea 会撑高整行、把网格挤乱；contenteditable 保持原字号/行高/换行行为。
      //   ★ 只在 `blur` 落库（不在 input 时重绘整屏 —— 会丢光标，且会让正在输入的框失焦）。
      //   ★ 空内容不写 `''` 而是写 `''`（渲染层用 `data-placeholder` 显示灰字「待补充描述」），
      //     这样清空描述后仍能继续编辑，不会变成一块没有热区的空白。
      const commitAssetDesc = el => {
        const node = scriptPanelNode();
        if (!node) return;
        const id = el.dataset.scriptAssetDesc;
        const list = scriptAssets(node);
        const hit = list.find(entry => entry.id === id);
        if (!hit) return;
        const next = String(el.textContent || '').replace(/\s+/g, ' ').trim();
        if (String(hit.desc || '') === next) return;
        hit.desc = next;
        setScriptAssets(node, list);
        // ★ 不重绘：用户可能还要继续改别的资产描述。`setScriptAssets` 已触发保存。
      };
      // ★★ 资产名称：**就地可编辑**（用户：「这里的新角色应该可以编辑内容」——
      //   卡片上那颗默认名「新角色」以前是纯文本，改不了，只能删了重建）。
      //   与描述同一套路（contenteditable + 只在 blur 落库），差别只有两处：
      //   · 名字是 `@资产名` 引用的**键**，所以**不允许为空** —— 清空就还原回原值；
      //   · 名字改完不重绘（和描述一致），避免打断用户连续编辑。
      const commitAssetName = el => {
        const node = scriptPanelNode();
        if (!node) return;
        const id = el.dataset.scriptAssetName;
        const list = scriptAssets(node);
        const hit = list.find(entry => entry.id === id);
        if (!hit) return;
        const next = String(el.textContent || '').replace(/\s+/g, ' ').trim();
        if (!next || String(hit.name || '') === next) {
          el.textContent = String(hit.name || '');   // 空名还原（渲染层的 data-placeholder 负责显示灰字）
          return;
        }
        hit.name = next;
        setScriptAssets(node, list);
      };
      layer.addEventListener('focusout', event => {
        const descEl = event.target.closest('[data-script-asset-desc]');
        if (descEl) commitAssetDesc(descEl);
        const nameEl = event.target.closest('[data-script-asset-name]');
        if (nameEl) commitAssetName(nameEl);
      });
      layer.addEventListener('keydown', event => {
        // 描述框里回车 = 确认（换行没有意义，描述是单行片段），Esc = 还原
        const descEl = event.target.closest('[data-script-asset-desc]');
        if (descEl) {
          if (event.key === 'Enter') { event.preventDefault(); descEl.blur(); return; }
          if (event.key === 'Escape') {
            event.stopPropagation();
            const node = scriptPanelNode();
            const hit = node && scriptAssets(node).find(entry => entry.id === descEl.dataset.scriptAssetDesc);
            descEl.textContent = String(hit?.desc || '');
            descEl.blur();
            return;
          }
        }
        // 名称框同理：单行片段，回车确认 / Esc 还原
        const nameEl = event.target.closest('[data-script-asset-name]');
        if (nameEl) {
          if (event.key === 'Enter') { event.preventDefault(); nameEl.blur(); return; }
          if (event.key === 'Escape') {
            event.stopPropagation();
            const node = scriptPanelNode();
            const hit = node && scriptAssets(node).find(entry => entry.id === nameEl.dataset.scriptAssetName);
            nameEl.textContent = String(hit?.name || '');
            nameEl.blur();
            return;
          }
        }
        if (event.key === 'Escape') { event.stopPropagation(); closeScriptPanel(); }
      });
    }
    function scriptAddShot() {
      const node = scriptPanelNode();
      if (!node) return;
      const shots = scriptShots(node);
      shots.push({
        id: `shot-${Date.now().toString(36)}`, duration: '5s', description: '', shotSize: '', emotion: '',
        lighting: '', dialogue: '', dialogueLines: [], sfx: '', props: '', cameraMove: '',
        prompt: '', videoPrompt: '', promptStatus: 'idle', tone: '',
      });
      setScriptShots(node, shots);
      renderScriptPanel();
    }
    function scriptDeleteShot(shotId) {
      const node = scriptPanelNode();
      if (!node) return;
      if (scriptShots(node).length <= 1) return showToast('至少保留 1 个镜头', '⚠');
      setScriptShots(node, scriptShots(node).filter(shot => shot.id !== shotId));
      renderScriptPanel();
    }
    function scriptUpdateShotField(shotId, key, value, rerender) {
      const node = scriptPanelNode();
      if (!node || !key) return;
      const shots = scriptShots(node);
      const shot = shots.find(item => item.id === shotId);
      if (!shot) return;
      const next = String(value || '');
      // ★★ 必须**先判断值有没有真的变**，再决定要不要作废提示词。
      //   原来不看变化、只要走到这条路径就把 prompt 清空 —— 于是用户**点开浮层又原样保存**
      //   （什么都没改）也会把已经合成好的提示词清掉，`promptStatus` 一起退回 idle。
      //   实测踩到：验证脚本点了一次「保存」按钮，106 字的提示词当场没了。
      const changed = String(shot[key] || '') !== next;
      shot[key] = next;
      // ★ 真的改了镜头内容 → 该镜的旧提示词**作废**，否则「合成提示词」那步会拿旧结果糊弄人。
      if (changed && key !== 'prompt' && String(shot.prompt || '').trim()) { shot.prompt = ''; shot.promptStatus = 'idle'; }
      setScriptShots(node, shots);
      if (rerender) renderScriptPanel();
    }
    function scriptAdvanceStage() {
      const node = scriptPanelNode();
      if (!node || !scriptPanelCtx) return;
      const next = SCRIPT_STAGE_NEXT[scriptPanelCtx.stage];
      // ★ 第三步的按钮是「一键合成全部提示词」——到顶了，不切步骤，直接开合成弹窗。
      if (next.isPrimaryAction) return openScriptSynthesizeModal();
      if (!next.id) return;
      scriptPanelCtx.stage = next.id;
      renderScriptPanel();
    }
    function setScriptShots(node, shots) {
      node.dataset.shots = JSON.stringify(shots || []);
      renderScriptSteps(node);
      scheduleSave();
    }
    function setScriptAssets(node, assets) {
      node.dataset.scriptAssets = JSON.stringify(assets || []);
      renderScriptSteps(node);
      scheduleSave();
    }

    function scriptAddAsset(kind) {
      const node = scriptPanelNode();
      if (!node) return;
      const assets = scriptAssets(node);
      const type = SCRIPT_ASSET_KINDS.some(item => item.id === kind) ? kind : SCRIPT_ASSET_KINDS[0].id;
      const label = (SCRIPT_ASSET_KINDS.find(item => item.id === type) || {}).label || '资产';
      const item = { id: `asset-${Date.now().toString(36)}`, kind: type, name: `新${label}`, desc: '', imageAsset: '', imageMedia: '' };
      assets.push(item);
      setScriptAssets(node, assets);
      renderScriptPanel();

      openScriptAssetPicker(item.id);
    }

    function scriptAssetRoleWord(kind) {
      return ({ character: '角色', scene: '场景', prop: '道具' })[kind] || '资产';
    }
    /**
     * 资产引用了**画布上的某个节点**时，补一条 `源节点 → 脚本节点` 的连线。
     * 用户诉求：「资产里引用了画布上的内容时应该要连线过来，就好比我这个角色是引用的画布内的
     * 图片节点，此时脚本节点的上游应该有引用的那个图片节点」。
     * ★ 走 `CanvasFlowConnections`（连线的唯一真源），不要自己往 `state.edges` 里塞 ——
     *   那边有 `normalize` / 去重 / 防环 / 落盘一整套处理。
     * ★ 三种情况**静默跳过**（不打扰用户）：自身、已存在同向边、会形成环。
     * @returns {boolean} 是否真的新建了一条线
     */
    function scriptLinkAssetSourceNode(scriptNode, sourceNodeId) {
      const conn = window.CanvasFlowConnections;
      if (!conn?.getEdges || !conn?.setEdges) return false;
      const source = String(sourceNodeId || '');
      const target = String(scriptNode?.dataset?.nodeId || '');
      if (!source || !target || source === target) return false;
      if (!document.querySelector(`.flow-node[data-node-id="${CSS.escape(source)}"]`)) return false;
      const edges = conn.getEdges();
      if (edges.some(edge => edge.source === source && edge.target === target)) return false;
      // 防环：沿 target 的下游走一圈，若能回到 source 就不能连（与 `connections.js` 同判据）。
      const stack = [target];
      const seen = new Set();
      while (stack.length) {
        const current = stack.pop();
        if (current === source) return false;
        if (seen.has(current)) continue;
        seen.add(current);
        edges.filter(edge => edge.source === current).forEach(edge => stack.push(edge.target));
      }
      conn.setEdges([...edges, { id: `edge-asset-${source}-${target}-${Date.now().toString(36)}`, source, target }]);
      return true;
    }
    /**
     * 一个资产**引用了哪些画布节点** —— 删资产 / 换图之后据此判断连线该不该留。
     * ★ 新数据靠 `asset.sourceNodeId`（在「选择图片 → 从当前画布选择」确认时写入）。
     * ★ 旧数据没有这个字段 → 用**资产图 URL 与上游节点的图比对**反推：
     *   应用时 `staged` 就是直接取自源节点的 `previewMedia / previewData`（见 picker 确认分支），
     *   所以只要用户没改过那张图，两者必然相等。
     * @returns {string[]} 源节点 id 列表（可能为空）
     */
    function scriptAssetSourceNodeIds(node, asset) {
      const out = [];
      if (!node || !asset) return out;
      const direct = String(asset.sourceNodeId || '');
      if (direct) out.push(direct);
      const url = String(asset.imageMedia || '');
      // `data:` 是内联 base64（AI 生成 / 本地上传都是这条），不可能来自画布节点，不必反推
      if (!url || url.startsWith('data:')) return out;
      const target = String(node.dataset.nodeId || '');
      const edges = window.CanvasFlowConnections?.getEdges?.() || [];
      for (const edge of edges) {
        if (edge.target !== target || out.includes(String(edge.source))) continue;
        const src = document.querySelector(`.flow-node[data-node-id="${CSS.escape(String(edge.source))}"]`);
        if (!src) continue;
        const handles = nodeImageHandles(src);
        if ((handles.previewMedia || handles.previewData) === url) out.push(String(edge.source));
      }
      return out;
    }
    /**
     * ★★ 删资产 / 清除图片 / 换图之后，把**已经没人引用的**「资产自动连线」收掉。
     *   用户诉求：「画布内图片在脚本节点内使用时画布内不是会自动连接么，
     *              那在脚本节点内删除该资产时会自动删除连线」。
     * ★ 边的结构被 `connections.js` 的 `normalize()` 压成 `{id, source, target}`，
     *   **塞不进 `assetId`** —— 所以判定只能反过来做：先算「剩余资产还引用哪些源节点」，
     *   不在这个集合里的自动连线就删。于是多个资产引用同一个画布节点时，删一个**不会误伤**另一个。
     * ★ 只动 `id` 以 `edge-asset-` 开头的线（`scriptLinkAssetSourceNode()` 建的），
     *   **用户手动的连线一根都不碰**。
     * @returns {number} 实际删掉的线数
     */
    function pruneScriptAssetLinks(node) {
      const conn = window.CanvasFlowConnections;
      if (!node || !conn?.getEdges || !conn?.setEdges) return 0;
      const target = String(node.dataset.nodeId || '');
      if (!target) return 0;
      const edges = conn.getEdges();
      const auto = edges.filter(edge => edge.target === target && String(edge.id || '').startsWith('edge-asset-'));
      if (!auto.length) return 0;
      const alive = new Set();
      scriptAssets(node).forEach(asset => scriptAssetSourceNodeIds(node, asset).forEach(id => alive.add(id)));
      const dropped = new Set(auto.filter(edge => !alive.has(String(edge.source))).map(edge => edge.id));
      if (!dropped.size) return 0;
      conn.setEdges(edges.filter(edge => !dropped.has(edge.id)));
      return dropped.size;
    }








    function openScriptAssetPicker(assetId, initialTab) {
      const node = scriptPanelNode();
      const list = scriptAssets(node);
      const item = list.find(asset => asset.id === assetId);
      if (!item) return;
      closeScriptPopover();
      const pick = document.createElement('div');
      pick.className = 'script-popover script-picker';
      const tabs = [
        { id: 'generate', label: 'AI生成' },
        { id: 'pick', label: '从当前画布选择' },
        { id: 'upload', label: '本地上传' },
        { id: 'library', label: '个人资产库' },
      ];
      let tab = tabs.some(entry => entry.id === initialTab) ? initialTab : 'generate';
      pick.innerHTML = `<header class="script-picker__head">
          <strong>${escapeHtml(item.name || '未命名资产')} · 选择图片</strong>
          <button type="button" class="script-picker__close" data-picker-close aria-label="关闭">✕</button>
        </header>
        <nav class="script-picker__tabs">${tabs.map(entry => `<button type="button" class="script-picker__tab${entry.id === tab ? ' is-active' : ''}" data-picker-tab="${entry.id}">${entry.label}</button>`).join('')}</nav>
        <div class="script-picker__body" data-picker-body></div>
        <footer class="script-picker__foot">
          <span class="script-picker__note" data-picker-note></span>
          <span class="script-popover__spacer"></span>
          <button type="button" class="script-picker__action" data-picker-cancel>取消</button>
          <button type="button" class="script-picker__action is-primary" data-picker-confirm>确认</button>
        </footer>`;
      document.body.appendChild(pick);
      const bodyEl = pick.querySelector('[data-picker-body]');
      const noteEl = pick.querySelector('[data-picker-note]');
      const confirmBtn = pick.querySelector('[data-picker-confirm]');
      let staged = '';           // 待确认的图源（落盘直链 或 素材库 id 形态）
      let stagedAssetId = '';    // 来自「个人资产库」时记 id（走鉴权回源）
      // ★★ 来自「从当前画布选择」时记下**源节点 id** —— 用户诉求：
      //   「资产里引用了画布上的内容时应该要连线过来，就好比我这个角色是引用的画布内的图片节点，
      //     此时脚本节点的上游应该有引用的那个图片节点」。
      //   确认应用时按它建一条 `源图片节点 → 脚本节点` 的边。
      let stagedSourceNodeId = '';
      let stagedSourceNode = null;



      const applyStaged = () => {
        const isGenerate = tab === 'generate';
        confirmBtn.textContent = isGenerate ? '✦ 确认生成' : '确认';
        confirmBtn.disabled = isGenerate ? false : !staged;
        noteEl.textContent = isGenerate ? '' : (staged ? '已选择 1 张图，点「确认」应用' : '');
      };







      const genBase = normalizeImageGenerationSettings(state.imageGenerationSettings);
      const genSpec = {
        modelId: '',
        tier: imageResTier(genBase.resolution),
        quality: genBase.quality || 'standard',
        aspect: genBase.aspect || '16:9',
      };
      const genModelName = () => {
        if (genSpec.modelId) {
          return (state.t2iModels || []).find(model => model.id === genSpec.modelId)?.name || '跟随画布模型';
        }
        // 跟随画布 —— 显示画布当前实际生效的模型名，取不到才退回「跟随画布模型」
        const current = (state.t2iModels || []).find(model => model.id === t2iModelId());
        return current ? `${current.name}（跟随画布）` : '跟随画布模型';
      };
      // ★★★ 画质档按模型能力显灰（r824，与画布底栏的设置弹层同一套规则）。
      //   本弹层能切模型（`genSpec.modelId` 为空 = 跟随画布），所以判据要用**这次出图真正会用的那个模型**。
      //   `supportedImageQualities()` 返回 `null` = 未知（旧服务端没下发）→ 一律不显灰。
      const genQualityGroupHtml = () => {
        const supported = supportedImageQualities(genSpec.modelId || t2iModelId());
        const ok = id => !Array.isArray(supported) || supported.includes(id);
        const row = IMAGE_QUALITY_OPTIONS.map(([id, label]) => {
          const can = ok(id);
          // ★ 不支持的档位**不标选中**：`is-active` 与 `is-disabled` 同挂会互相打架。
          const cls = `libtv-pset__btn${can && id === genSpec.quality ? ' is-active' : ''}${can ? '' : ' is-disabled'}`;
          const attrs = can ? ' tabindex="0"' : ' tabindex="-1" aria-disabled="true" title="当前生图模型不支持该画质档"';
          return `<div class="${cls}" data-gen-quality="${id}" role="button"${attrs}>${label}</div>`;
        }).join('');
        const labels = IMAGE_QUALITY_OPTIONS.filter(([id]) => ok(id)).map(([, label]) => label);
        const hint = !Array.isArray(supported) ? ''
          : supported.length
            ? (labels.length < IMAGE_QUALITY_OPTIONS.length ? `<div class="libtv-pset__hint">当前模型仅支持：${labels.join(' / ')}</div>` : '')
            : '<div class="libtv-pset__hint">当前模型不支持画质设置，该档位不会发往上游</div>';
        return `<div class="libtv-pset__group" data-gen-quality-group><div class="libtv-pset__title">画质</div>
              <div class="libtv-pset__row">${row}</div>${hint}</div>`;
      };
      const renderGenerate = () => {
        const role = scriptAssetRoleWord(item.kind);
        bodyEl.innerHTML = `<div class="script-picker__gen">
            <label class="script-picker__field"><span>画面描述</span>
              <textarea class="script-picker__area" data-picker-prompt rows="3" placeholder="${escapeHtml(`描述${role}的核心特征或希望保留的细节`)}">${escapeHtml(String(item.desc || ''))}</textarea></label>
            <p class="script-picker__hint">风格：${escapeHtml(String(node?.dataset.scriptStyle || '未设置'))}</p>
            <div class="libtv-pset__group"><div class="libtv-pset__title">模型</div>
              <button type="button" class="script-picker__model-btn" data-picker-model aria-haspopup="listbox"><span data-picker-model-label>${escapeHtml(genModelName())}</span><i>▾</i></button></div>
            ${genQualityGroupHtml()}
            <div class="libtv-pset__group"><div class="libtv-pset__title">清晰度</div>
              <div class="libtv-pset__row">${IMAGE_RES_TIERS.map(value => `<div class="libtv-pset__btn${value === genSpec.tier ? ' is-active' : ''}" data-gen-tier="${value}" role="button" tabindex="0">${value}</div>`).join('')}</div></div>
            <div class="libtv-pset__group"><div class="libtv-pset__title">比例</div>
              <div class="libtv-pset__aspect-grid">${IMAGE_ASPECT_RATIOS.map(value => `<div class="libtv-pset__aspect-card${value === genSpec.aspect ? ' is-active' : ''}" data-gen-aspect="${value}" role="button" tabindex="0" title="${aspectCardLabel(value)}"><div class="libtv-pset__aspect-preview">${isAutoAspect(value) ? '<span class="libtv-pset__aspect-auto">自适应</span>' : `<div style="${aspectBoxStyle(value)}"></div>`}</div><span>${aspectCardLabel(value)}</span></div>`).join('')}</div></div>
          </div>`;
      };
      // ---- 页签 2：从当前画布选择（列出画布上所有有图的节点） ----
      const renderPick = () => {
        const candidates = Array.from(document.querySelectorAll('.flow-node.image-node, .flow-node.model-node, .flow-node.output-node'))
          .filter(el => el !== node && nodeHasUsableImage(el));
        bodyEl.innerHTML = candidates.length
          ? `<div class="script-picker__grid">${candidates.map((el, i) => {
            const name = String(el.querySelector('.node-title, .node-name')?.textContent || '').trim() || `图片节点 ${i + 1}`;
            const thumb = nodeImageHandles(el).previewMedia || nodeImageHandles(el).previewData || '';
            return `<button type="button" class="script-picker__cell" data-picker-canvas="${escapeHtml(el.dataset.nodeId || '')}">
                <span class="script-picker__cell-img">${thumb ? `<img src="${escapeHtml(thumb)}" alt="" />` : ''}</span>
                <small>${escapeHtml(name)}</small>
              </button>`;
          }).join('')}</div>`
          : '<div class="script-picker__empty">画布上暂无带图的节点</div>';
      };
      // ---- 页签 3：本地上传 ----
      const renderUpload = () => {
        bodyEl.innerHTML = `<div class="script-picker__drop" data-picker-drop>
            <b>点击选择图片</b><small>支持 jpg / png / webp，单张不超过 8MB</small>
            <input type="file" accept="image/*" data-picker-file hidden />
          </div>`;
      };
      // ---- 页签 4：个人资产库（服务端素材表，只挑图片） ----
      const renderLibrary = () => {
        bodyEl.innerHTML = '<div class="script-picker__empty">正在读取资产库…</div>';
        api('/api/assets').then(payload => {
          // 素材表字段：{id, name, kind, mediaId, mediaUrl, size, hasPreview}；kind 里带 image 才算图片。
          const rows = (payload?.assets || []).filter(row => {
            const url = String(row.mediaUrl || '');
            return row.hasPreview !== false && (row.kind === 'image' || /\.(png|jpe?g|webp|gif)$/i.test(url));
          });
          if (tab !== 'library') return;
          bodyEl.innerHTML = rows.length
            ? `<div class="script-picker__grid">${rows.map(row => {
              const url = String(row.mediaUrl || (row.mediaId ? `/api/assets/${encodeURIComponent(row.mediaId)}` : ''));
              return `<button type="button" class="script-picker__cell" data-picker-library="${escapeHtml(row.mediaId || row.id)}" data-picker-library-url="${escapeHtml(url)}">
                <span class="script-picker__cell-img"><img src="${escapeHtml(url)}" alt="" /></span>
                <small>${escapeHtml(String(row.name || '未命名').slice(0, 14))}</small>
              </button>`;
            }).join('')}</div>`
            : '<div class="script-picker__empty">资产库暂无图片</div>';
        }).catch(() => { if (tab === 'library') bodyEl.innerHTML = '<div class="script-picker__empty">资产库读取失败</div>'; });
      };
      const renderTab = () => {
        pick.querySelectorAll('[data-picker-tab]').forEach(btn => btn.classList.toggle('is-active', btn.dataset.pickerTab === tab));
        applyStaged();
        if (tab === 'generate') renderGenerate();
        else if (tab === 'pick') renderPick();
        else if (tab === 'upload') renderUpload();
        else renderLibrary();
      };
      renderTab();

      pick.addEventListener('click', async event => {
        const tabBtn = event.target.closest('[data-picker-tab]');
        if (tabBtn) { tab = tabBtn.dataset.pickerTab; staged = ''; stagedAssetId = ''; return renderTab(); }
        if (event.target.closest('[data-picker-close]') || event.target.closest('[data-picker-cancel]')) return closeScriptPopover();
        const canvasCell = event.target.closest('[data-picker-canvas]');
        if (canvasCell) {
          bodyEl.querySelectorAll('.script-picker__cell').forEach(cell => cell.classList.remove('is-picked'));
          canvasCell.classList.add('is-picked');
          const source = document.querySelector(`.flow-node[data-node-id="${CSS.escape(canvasCell.dataset.pickerCanvas)}"]`);
          const handles = nodeImageHandles(source);
          staged = handles.previewMedia || handles.previewData;
          stagedAssetId = '';
          // ★ 记下源节点：确认后要连一条「该图片节点 → 脚本节点」的线（用户诉求）。
          stagedSourceNodeId = canvasCell.dataset.pickerCanvas || '';
          stagedSourceNode = source || null;
          return applyStaged();
        }
        const libCell = event.target.closest('[data-picker-library]');
        if (libCell) {
          bodyEl.querySelectorAll('.script-picker__cell').forEach(cell => cell.classList.remove('is-picked'));
          libCell.classList.add('is-picked');
          stagedAssetId = libCell.dataset.pickerLibrary;
          staged = libCell.dataset.pickerLibraryUrl || `/api/assets/${encodeURIComponent(stagedAssetId)}`;
          stagedSourceNodeId = '';
          stagedSourceNode = null;
          return applyStaged();
        }
        if (event.target.closest('[data-picker-drop]')) return pick.querySelector('[data-picker-file]')?.click();
        // ---- AI 生成页签的参数选择（即选即生效，不出图） ----
        if (event.target.closest('[data-picker-model]')) {
          // ★ 再点一次收起（用户 12 连里那两张「生图模型下拉」截图）
          if (toggleScriptPopover(pick.querySelector('[data-picker-model]'))) return;
          openScriptGenModelMenu(pick.querySelector('[data-picker-model]'), genSpec, () => {
            const label = pick.querySelector('[data-picker-model-label]');
            if (label) label.textContent = genModelName();
            // ★ 换了模型 → 画质档的可用性可能整个变了（如 gpt-image-2 → agnes-image-2.5-flash）。
            //   档位已不被支持就回落到支持档（与画布底栏「套用模型默认值」同规则），
            //   然后**只重渲画质段** —— 整块 re-render 会把用户已经填好的「画面描述」清掉。
            genSpec.quality = fallbackImageQuality(genSpec.quality, supportedImageQualities(genSpec.modelId || t2iModelId()));
            const group = bodyEl.querySelector('[data-gen-quality-group]');
            if (group) group.outerHTML = genQualityGroupHtml();
          });
          return;
        }
        const genQuality = event.target.closest('[data-gen-quality]');
        if (genQuality) {
          // 灰掉的档位：不写设置，但**给一句解释** —— 静默无反应最容易被当成"按钮坏了"。
          if (genQuality.classList.contains('is-disabled')) return showToast('当前生图模型不支持该画质档', '✦');
          genSpec.quality = genQuality.dataset.genQuality;
          bodyEl.querySelectorAll('[data-gen-quality]').forEach(el => el.classList.toggle('is-active', el === genQuality));
          return;
        }
        const genTier = event.target.closest('[data-gen-tier]');
        if (genTier) {
          genSpec.tier = genTier.dataset.genTier;
          bodyEl.querySelectorAll('[data-gen-tier]').forEach(el => el.classList.toggle('is-active', el === genTier));
          return;
        }
        const genAspect = event.target.closest('[data-gen-aspect]');
        if (genAspect) {
          genSpec.aspect = genAspect.dataset.genAspect;
          bodyEl.querySelectorAll('[data-gen-aspect]').forEach(el => el.classList.toggle('is-active', el === genAspect));
          return;
        }
        if (event.target.closest('[data-picker-confirm]')) {

          if (tab === 'generate') {
            const prompt = String(pick.querySelector('[data-picker-prompt]')?.value || '').trim();
            if (!prompt) return showToast('请先填写画面描述', '⚠');
            const role = scriptAssetRoleWord(item.kind);
            confirmBtn.disabled = true;
            confirmBtn.textContent = '生成中…';
            const ok = await scriptGenerateAssetImage(item.id, prompt, {
              modelId: genSpec.modelId || undefined,
              resolution: aspectToResolution(genSpec.aspect, genSpec.tier),
              quality: genSpec.quality,
              aspect: genSpec.aspect,
            });
            confirmBtn.disabled = false;
            confirmBtn.textContent = `✦ 确认生成`;
            if (ok) closeScriptPopover();
            return;
          }
          if (!staged) return;
          const fresh = scriptAssets(node);
          const hit = fresh.find(asset => asset.id === assetId);
          if (hit) {
            // 落盘直链进 imageMedia；素材库 id 进 imageAsset（两条取图链路都写，避免三句柄漏一个）
            // ★ `sourceNodeId` 记录「这张图来自画布上的哪个节点」—— 删资产时要靠它判断连线该不该留。
            //   本地上传 / 资产库 / AI 生成都不来自画布节点，一律清空。
            if (stagedAssetId) { hit.imageAsset = stagedAssetId; hit.imageMedia = ''; hit.sourceNodeId = ''; }
            else { hit.imageMedia = staged; hit.imageAsset = ''; hit.sourceNodeId = String(stagedSourceNodeId || ''); }
          }
          setScriptAssets(node, fresh);
          // ★ 换图 = 引用关系变了：原来指向的画布节点若已不再被本资产引用，那条自动连线就该消失。
          pruneScriptAssetLinks(node);
          // ★★ 引用来源是**画布上的节点**时，补一条「该图片节点 → 脚本节点」的连线。
          //   用户诉求：「资产里引用了画布上的内容时应该要连线过来，就好比我这个角色是引用的
          //   画布内的图片节点，此时脚本节点的上游应该有引用的那个图片节点」。
          //   ★ 只连**图片节点**（引用关系要看得见；从资产库/本地上传的不连，它们不在画布上）。
          //   ★ 已存在同向边 / 会成环时静默跳过 —— `connect` 会弹 toast 报错，这里不需要打扰用户。
          if (stagedSourceNodeId) scriptLinkAssetSourceNode(node, stagedSourceNodeId);
          renderScriptPanel();
          closeScriptPopover();
          showToast('图片已应用到资产', '✓');
        }
      });
      pick.addEventListener('change', async event => {
        const file = event.target.closest('[data-picker-file]')?.files?.[0];
        if (!file) return;
        noteEl.textContent = '正在上传…';
        const media = await uploadMediaFile(file);
        if (media?.url) { staged = media.url; stagedAssetId = ''; noteEl.textContent = ''; }
        else noteEl.textContent = '上传失败，请重试';
        applyStaged();
      });
      // ★ 居中必须用**实测高度**：`height` 写死过 480，但真实高度随内容变
      //   （body min-height 280 + 头 + 页签 + 底栏），写死就会偏上/偏下。
      //   先给宽度让布局成立 → 量 offsetHeight → 再算 top。这也是 `openScriptPromptPopover` 的做法。
      ensureScriptPopoverBackdrop();
      const width = 720;
      pick.style.width = `min(${width}px, calc(100vw - 32px))`;
      pick.style.left = `${Math.max(16, (window.innerWidth - Math.min(width, window.innerWidth - 32)) / 2)}px`;
      pick.style.top = '16px';           // 先给个占位，量完再改（避免看不见时 offsetHeight=0）
      const shownHeight = pick.offsetHeight || 0;
      pick.style.top = `${Math.max(16, (window.innerHeight - shownHeight) / 2)}px`;
      scriptPopover = pick;
      // ★ 模态弹层：不绑「点外面关」（里面要填描述/模型/清晰度/比例，误点空白全丢）。
      bindPopoverDismiss({ modal: true });
    }




    function openScriptAssetMenu(anchor, assetId) {
      closeScriptPopover();
      const node = scriptPanelNode();
      const item = scriptAssets(node).find(asset => asset.id === assetId);
      if (!item) return;
      const role = scriptAssetRoleWord(item.kind);
      const hasImage = Boolean(item.imageAsset || item.imageMedia);
      const pop = document.createElement('div');
      pop.className = 'script-popover script-popover--menu script-asset-menu-pop';
      // ★ 记锚点 → 「再点一次收起」生效（用户截图里的资产 ⋯ 菜单）
      const assetAnchorKey = scriptPopoverAnchorKey(anchor);
      if (assetAnchorKey) pop.dataset.anchor = assetAnchorKey;
      pop.innerHTML = `<button type="button" class="script-popover__item" data-asset-act="edit">编辑</button>
        <button type="button" class="script-popover__item" data-asset-act="select">选择图片</button>
        <button type="button" class="script-popover__item" data-asset-act="ai">AI 生${escapeHtml(role)}</button>
        <button type="button" class="script-popover__item" data-asset-act="jump">跳转至节点</button>
        <button type="button" class="script-popover__item" data-asset-act="clear"${hasImage ? '' : ' disabled'}>清除图片</button>
        <button type="button" class="script-popover__item" data-asset-act="save"${hasImage ? '' : ' disabled'}>保存到个人资产</button>
        <button type="button" class="script-popover__item is-danger" data-asset-act="delete">删除</button>`;
      document.body.appendChild(pop);
      const rect = anchor.getBoundingClientRect();
      pop.style.left = `${Math.max(8, Math.min(rect.left - 150, window.innerWidth - 210))}px`;
      pop.style.top = `${Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - 240))}px`;
      pop.addEventListener('click', async event => {
        const btn = event.target.closest('[data-asset-act]');
        if (!btn || btn.disabled) return;
        const act = btn.dataset.assetAct;
        if (act === 'select') { closeScriptPopover(); openScriptAssetPicker(assetId, 'pick'); return; }
        if (act === 'ai') { closeScriptPopover(); openScriptAssetPicker(assetId, 'generate'); return; }
        if (act === 'jump') { closeScriptPopover(); return; }
        if (act === 'clear') {
          const fresh = scriptAssets(node);
          const hit = fresh.find(asset => asset.id === assetId);
          // ★ 图清掉了 = 不再引用画布上那个节点 → `sourceNodeId` 一起清，下面的 prune 会把线收掉
          if (hit) { hit.imageAsset = ''; hit.imageMedia = ''; hit.sourceNodeId = ''; }
          setScriptAssets(node, fresh);
          pruneScriptAssetLinks(node);
          renderScriptPanel(); closeScriptPopover();
          return showToast('已清除图片', '✓');
        }
        if (act === 'save') {
          closeScriptPopover();
          try {
            const id = item.imageAsset || '';
            if (!id) return showToast('该图片不在素材库中，暂不支持保存', '⚠');
            showToast('已保存到个人资产', '✓');
          } catch { showToast('保存失败', '×'); }
          return;
        }
        if (act === 'edit') { closeScriptPopover(); return openScriptAssetEditor(assetId); }
        if (act === 'delete') { closeScriptPopover(); return openScriptAssetDeleteConfirm(assetId); }
      });
      scriptPopover = pop;
      bindPopoverDismiss();
    }
    /** 为单个资产生成设定图（资产选择弹层「AI生成」页签的后端调用）。返回是否成功。 */
    /**
     * 「选择图片 → AI生成」页签里的生图模型菜单。
     * 结构沿用历史节点模型菜单的设计（同一个 `.charview-model-menu` 外壳），
     * 差别只在：它写的是弹层级的临时 `genSpec.modelId`，不落到节点上、也不写回画布设置。
     */
    function openScriptGenModelMenu(anchor, spec, onPick) {
      // ★★ 开关语义：点一下展开、**再点一下收起**（用户截图里那张「生图模型」下拉）。
      //   它用的是 `.charview-model-menu` 外壳（不在 `scriptPopover` 体系里），
      //   所以不能用 `toggleScriptPopover()` —— 用 `data-anchor` 自己判：
      //   同一个锚点再点 → 只删菜单、直接返回。
      const genKey = scriptPopoverAnchorKey(anchor);
      const existing = $('.charview-model-menu');
      if (existing && genKey && existing.dataset.anchor === genKey) { existing.remove(); return; }
      existing?.remove();
      const models = state.t2iModels || [];
      const menu = document.createElement('div');
      menu.className = 'charview-model-menu';
      if (genKey) menu.dataset.anchor = genKey;
      menu.innerHTML = modelMenuOptionHtml('', '跟随画布设置', '使用底部创作栏选择的模型', !spec.modelId)
        + models.map(model => modelMenuOptionHtml(model.id, model.name, model.provider || '', spec.modelId === model.id)).join('');
      document.body.appendChild(menu);
      const rect = anchor.getBoundingClientRect();
      menu.style.left = `${Math.max(8, Math.min(window.innerWidth - menu.offsetWidth - 8, rect.left))}px`;
      menu.style.top = `${Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - menu.offsetHeight - 8))}px`;
      const onKey = event => { if (event.key === 'Escape') menu.remove(); };
      document.addEventListener('keydown', onKey, true);
      menu.addEventListener('click', event => {
        const option = event.target.closest('[data-model-id]');
        if (!option) return;
        spec.modelId = option.dataset.modelId || '';
        menu.remove();
        document.removeEventListener('keydown', onKey, true);
        onPick?.();
      });
      setTimeout(() => {
        const outside = event => {
          if (!event.target.closest('.charview-model-menu')) {
            menu.remove();
            document.removeEventListener('pointerdown', outside, true);
          }
        };
        document.addEventListener('pointerdown', outside, true);
      }, 0);
    }
    async function scriptGenerateAssetImage(assetId, prompt, options) {
      const node = scriptPanelNode();
      if (!node) return false;
      try {
        // 与「一键生成所有资产」同一条链路：`/api/ai/image-generate` 返回的 `image` 是内联 data URI。
        // options：{ modelId, resolution, quality, aspect } —— 未传时退回画布设置，行为与旧版一致。
        const result = await api('/api/ai/image-generate', { method: 'POST', body: JSON.stringify({
          modelId: options?.modelId || t2iModelId() || undefined,
          prompt,
          size: options?.resolution || '1024x1024',
          quality: options?.quality || undefined,
          aspect: options?.aspect || undefined,
        }) });
        const image = String(result?.image || '');
        if (!image) { showToast('资产图生成失败，请检查生图模型配置', '×'); return false; }
        const fresh = scriptAssets(node);
        const hit = fresh.find(asset => asset.id === assetId);
        if (hit) hit.imageMedia = image;
        setScriptAssets(node, fresh);
        renderScriptPanel();
        showToast('资产图已生成', '✓');
        return true;
      } catch (error) {
        showToast(`生成失败：${error.message}`, '×');
        return false;
      }
    }

    function openScriptStylePopover(anchor) {
      const node = scriptPanelNode();
      if (!node) return;
      openScriptPopover(anchor, {
        hint: '全局风格 —— 合成提示词时会作为统一风格写进每一镜',
        placeholder: '例如：现代青春校园 真人写实电影',
        value: String(node.dataset.scriptStyle || ''),
        rows: 2,
        width: 380,
        onSave: (value) => {
          node.dataset.scriptStyle = String(value || '').trim().slice(0, 120);
          renderScriptPanel();
          scheduleSave();
        },
      });
    }






    function scriptDeleteAsset(assetId) {
      const node = scriptPanelNode();
      if (!node) return;
      setScriptAssets(node, scriptAssets(node).filter(item => item.id !== assetId));
      pruneScriptAssetLinks(node);
      renderScriptPanel();
    }
    /** 正则元字符转义（资产名是用户输入，直接拼进 RegExp 会炸）。 */
    function scriptRegEscape(text) {
      return String(text || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
    /** 去掉文本里对某个资产名的 `@` 引用（连它后面的一个空格），**保留普通文字**。 */
    function stripAssetAtRef(text, name) {
      const raw = String(text || '');
      if (!raw || !name) return raw;
      return raw.replace(new RegExp('@' + scriptRegEscape(name) + '\\s?', 'g'), '').trim();
    }









    function openScriptAssetDeleteConfirm(assetId) {
      const node = scriptPanelNode();
      if (!node) return;
      const asset = scriptAssets(node).find(item => item.id === assetId);
      if (!asset) return;
      const kindLabel = SCRIPT_ASSET_KINDS.find(kind => kind.id === asset.kind)?.label || '资产';
      const name = String(asset.name || '未命名资产');
      const refCount = scriptShots(node).filter(shot => String(shot.description || '').includes('@' + name)).length;
      const canClean = asset.kind === 'character' || asset.kind === 'scene';
      const cleanTitle = asset.kind === 'scene' ? '同时从分镜场景引用中移除' : '同时从分镜角色列表中移除';
      const cleanDetail = asset.kind === 'scene'
        ? '清掉每行场景引用 + 提示词里的 @ 提及（如有），保留普通文字'
        : '清掉每行角色列表 + 提示词里的 @ 提及，保留普通文字';
      document.querySelector('.script-asset-del-layer')?.remove();
      const layer = document.createElement('div');
      layer.className = 'ftv-prompt-preset__layer script-asset-del-layer';
      layer.setAttribute('role', 'presentation');
      layer.innerHTML = `<section class="script-confirm" role="dialog" aria-modal="true" aria-label="删除资产">
          <header class="script-confirm__head">
            <strong>删除资产</strong>
            <button type="button" class="script-confirm__close" data-del-close aria-label="关闭">✕</button>
          </header>
          <div class="script-confirm__body">${escapeHtml(refCount
            ? `资产「${name}」（${kindLabel}）当前被 ${refCount} 个分镜引用，删除前请选择处理方式：`
            : `资产「${name}」（${kindLabel}）所在脚本已存在分镜内容。为避免改名后旧名称残留导致误删，删除前请选择处理方式：`)}</div>
          <div class="script-del-asset__options">
            <label class="script-del-asset__opt is-active" data-del-opt="keep">
              <input type="radio" name="scriptAssetDelMode" value="keep" checked />
              <strong>仅删除资产，保留分镜中的文字</strong>
              <small>分镜里的角色名 / 描述 / 台词文字保持原样</small>
            </label>
            <label class="script-del-asset__opt${canClean ? '' : ' is-disabled'}" data-del-opt="clean">
              <input type="radio" name="scriptAssetDelMode" value="clean"${canClean ? '' : ' disabled'} />
              <strong>${canClean ? cleanTitle : '当前阶段暂无可结构化清理的引用'}</strong>
              <small>${canClean ? cleanDetail : '道具/风格仍以保留文字为主，精确替换与文本联动留到后续阶段'}</small>
            </label>
          </div>
          <footer class="script-confirm__foot">
            <button type="button" class="script-confirm__btn" data-del-cancel>取消</button>
            <button type="button" class="script-confirm__btn is-danger" data-del-confirm>删除</button>
          </footer>
        </section>`;
      document.body.appendChild(layer);

      const close = () => layer.remove();
      layer.addEventListener('click', event => {
        if (event.target === layer || event.target.closest('[data-del-close]') || event.target.closest('[data-del-cancel]')) return close();
        const opt = event.target.closest('[data-del-opt]');
        if (opt && !opt.classList.contains('is-disabled')) {
          layer.querySelectorAll('[data-del-opt]').forEach(el => el.classList.toggle('is-active', el === opt));
          const radio = opt.querySelector('input');
          if (radio) radio.checked = true;
          return;
        }
        if (!event.target.closest('[data-del-confirm]')) return;
        const mode = layer.querySelector('input[name="scriptAssetDelMode"]:checked')?.value || 'keep';
        setScriptAssets(node, scriptAssets(node).filter(item => item.id !== assetId));
        // ★ 用户诉求：「画布内图片在脚本节点内使用时画布内不是会自动连接么，
        //   那在脚本节点内删除该资产时会自动删除连线」。
        //   → 资产没了，它那条 `源节点 → 脚本节点` 的自动连线也一并收掉（没别的资产还引用同一节点时才删）。
        pruneScriptAssetLinks(node);
        if (mode === 'clean') {
          // 「同时从分镜角色列表 / 场景引用中移除」：清 @ 提及 + 清对白行上的角色绑定，普通文字保留
          const cleaned = scriptShots(node).map(shot => {
            const out = { ...shot };
            out.description = stripAssetAtRef(out.description, name);
            out.prompt = stripAssetAtRef(out.prompt, name);
            out.videoPrompt = stripAssetAtRef(out.videoPrompt, name);
            if (Array.isArray(out.dialogueLines)) {
              out.dialogueLines = out.dialogueLines.map(line => (line && line.roleId === assetId)
                ? { ...line, roleId: '', roleName: '' } : line);
              const lines = out.dialogueLines.filter(line => String(line?.text || '').trim());
              out.dialogue = lines.length
                ? lines.map(line => {
                  const label = SCRIPT_DIALOGUE_TYPES[line.type] || '台词';
                  return line.type === 'line' ? `${label}（${line.roleName || '未绑定'}）：${line.text}` : `${label}：${line.text}`;
                }).join('\n')
                : '';
            }
            return out;
          });
          setScriptShots(node, cleaned);
        }
        close();
        renderScriptPanel();
        showToast(mode === 'clean' ? '已删除资产并清理引用' : '已删除资产', '✓');
      });
    }






    function openScriptAssetEditor(assetId) {
      const node = scriptPanelNode();
      if (!node) return;
      const asset = scriptAssets(node).find(item => item.id === assetId);
      if (!asset) return;
      const kind = SCRIPT_ASSET_KINDS.find(item => item.id === asset.kind);
      const kindLabel = kind?.label || '资产';
      const thumb = asset.imageMedia || (asset.imageAsset ? `/api/assets/${encodeURIComponent(asset.imageAsset)}` : '');
      document.querySelector('.script-asset-editor')?.remove();
      const panel = document.createElement('aside');
      panel.className = 'script-asset-editor';
      panel.setAttribute('role', 'dialog');
      panel.setAttribute('aria-label', `编辑${kindLabel}`);
      panel.innerHTML = `<header class="script-asset-editor__head">
          <strong>编辑${escapeHtml(kindLabel)}</strong>
          <button type="button" class="script-asset-editor__close" data-editor-close aria-label="关闭">✕</button>
        </header>
        <div class="script-asset-editor__body">
          <div class="script-asset-editor__figure">
            ${thumb ? `<img src="${escapeHtml(thumb)}" alt="" />` : `<div class="is-empty">还没有${escapeHtml(kindLabel)}形象图</div>`}
            <div class="script-asset-editor__tools">
              <button type="button" class="script-asset-editor__tool" data-editor-zoom title="查看大图" aria-label="查看大图"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5M11 8v6M8 11h6"/></svg></button>
              <button type="button" class="script-asset-editor__tool" data-editor-more title="更多操作" aria-label="更多操作"><svg viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="1.8"/><circle cx="12" cy="12" r="1.8"/><circle cx="19" cy="12" r="1.8"/></svg></button>
            </div>
          </div>
          <label class="script-asset-editor__field">
            <span>${escapeHtml(kindLabel)}名称</span>
            <input type="text" data-editor-name value="${escapeHtml(String(asset.name || ''))}" placeholder="请输入${escapeHtml(kindLabel)}名称" />
          </label>
          <label class="script-asset-editor__field">
            <span>${escapeHtml(kindLabel)}描述</span>
            <textarea data-editor-desc placeholder="${escapeHtml(kindLabel)}描述">${escapeHtml(String(asset.desc || ''))}</textarea>
          </label>
        </div>`;
      document.body.appendChild(panel);
      const nameEl = panel.querySelector('[data-editor-name]');
      const descEl = panel.querySelector('[data-editor-desc]');
      /** 改资产字段并落库；`allowEmpty=false` 时（名称）空值还原，不写空串。 */
      const commit = (key, value, allowEmpty) => {
        const list = scriptAssets(node);
        const hit = list.find(item => item.id === assetId);
        if (!hit) return;
        const next = String(value || '').replace(/\s+/g, ' ').trim();
        if (!next && !allowEmpty) { nameEl.value = String(hit.name || ''); return; }
        if (String(hit[key] || '') === next) return;
        hit[key] = next;
        setScriptAssets(node, list);
      };
      nameEl?.addEventListener('change', () => commit('name', nameEl.value, false));
      nameEl?.addEventListener('blur', () => commit('name', nameEl.value, false));
      descEl?.addEventListener('change', () => commit('desc', descEl.value, true));
      descEl?.addEventListener('blur', () => commit('desc', descEl.value, true));
      panel.querySelector('[data-editor-close]')?.addEventListener('click', () => { panel.remove(); renderScriptPanel(); });
      panel.querySelector('[data-editor-zoom]')?.addEventListener('click', () => {
        void openScriptAssetPreview(asset, asset.name || kindLabel);
      });
      panel.querySelector('[data-editor-more]')?.addEventListener('click', event => {
        // 复用资产卡右上角那套菜单（选择图片 / AI 生成 / 跳转 / 清除 / 保存 / 删除）
        openScriptAssetMenu(event.currentTarget, assetId);
      });
    }





