      const pop = document.createElement('div');
      pop.className = 'script-popover';
      // ★ 记下「是谁叫出来的」，供 `toggleScriptPopover()` 做再点收起
      const anchorKey = scriptPopoverAnchorKey(anchor);
      if (anchorKey) pop.dataset.anchor = anchorKey;
      const multiline = !config.single;
      pop.innerHTML = `<div class="script-popover__hint">${escapeHtml(config.hint || '')}</div>
        ${config.single
          ? `<input class="script-popover__input script-popover__input--single" type="text" inputmode="numeric" placeholder="${escapeHtml(config.placeholder || '')}"${config.readOnly ? ' readonly' : ''} value="${escapeHtml(config.value || '')}" />`
          : `<div class="script-popover__editor">
              <div class="script-popover__mirror" data-script-mirror aria-hidden="true">${highlightScriptAssets(config.value, config.assetNames)}</div>
              <textarea class="script-popover__input script-popover__input--over" rows="${config.rows || 3}" placeholder="${escapeHtml(config.placeholder || '')}"${config.readOnly ? ' readonly' : ''}>${escapeHtml(config.value || '')}</textarea>
            </div>`}
        ${config.assetPicker ? '<div class="script-at-menu" data-script-at-menu hidden></div>' : ''}
        <div class="script-popover__foot">
          ${(config.actions || []).map((action, i) => action.atShortcut
            ? `<button type="button" class="script-popover__action" data-script-at-open>${escapeHtml(action.label)}</button>`
            : `<button type="button" class="script-popover__action" data-script-pop-action="${i}">${escapeHtml(action.label)}</button>`).join('')}
          <span class="script-popover__spacer"></span>
          ${config.readOnly ? '' : '<button type="button" class="script-popover__save">保存</button>'}
        </div>`;
      document.body.appendChild(pop);
      const rect = anchor.getBoundingClientRect();
      const width = config.width || 330;
      pop.style.width = `${width}px`;
      pop.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - width - 12))}px`;
      // ★★ 定位（用户实测：「这边编辑完文本后都没法保存了」——浮层跑出视口底部，
      //   「保存」按钮被任务栏挡住点不到）。
      //   根因：原来写死 `window.innerHeight - 180` 当上界，可浮层的真实高度远超 180
      //   （hint + 5 行 textarea + 预设按钮行 + 保存行），于是 top 合法但**底边溢出**。
      //   正确做法：先把 top 放到视口顶部量出**真实高度**，再决定向下弹还是向上弹：
      //     · 下方放得下 → 贴 anchor 下沿；
      //     · 下方放不下、上方放得下 → 向上翻转，底边贴 anchor 上沿；
      //     · 两头都放不下 → 夹在视口内并给自身加 `max-height` + 内部滚动（保证保存按钮永远可达）。
      const GAP = 6;
      const MARGIN = 8;
      pop.style.top = `${MARGIN}px`;                    // 占位，避免量高度时元素不可见
      const popH = pop.offsetHeight || 240;
      const belowTop = rect.bottom + GAP;
      const aboveTop = rect.top - GAP - popH;
      const roomBelow = window.innerHeight - MARGIN - belowTop;
      const roomAbove = rect.top - GAP - MARGIN;
      let top;
      if (popH <= roomBelow) top = belowTop;                        // 优先向下
      else if (popH <= roomAbove) top = aboveTop;                   // 向下放不下 → 向上翻转
      else top = Math.max(MARGIN, window.innerHeight - MARGIN - popH); // 都放不下 → 夹住
