    function pushImageHistory(node, assetId) {
      if (!node || !assetId) return;
      let list = [];
      try { list = JSON.parse(node.dataset.imageHistory || '[]'); } catch { list = []; }
      if (list[list.length - 1] === assetId) return;
      list.push(assetId);
      node.dataset.imageHistory = JSON.stringify(list.slice(-8));
    }
    function readImageHistory(node) {
      try { return JSON.parse(node?.dataset.imageHistory || '[]') || []; } catch { return []; }
    }
    async function openImageHistory(node) {
      if (!node?.matches('.image-node')) return;
      const ids = readImageHistory(node);
      if (!ids.length) return showToast('还没有生成历史：AI 生成图片后会自动记录最近 8 次', '⏱');
      const backdrop = document.createElement('div');
      backdrop.className = 'image-editor-backdrop open';
      const box = document.createElement('div');
      box.className = 'image-history-modal';
      box.innerHTML = `<div class="image-editor-head"><div><span class="eyebrow">GENERATION HISTORY</span><strong>生成历史</strong></div><button class="modal-close" type="button" data-history-close="1">×</button></div><div class="image-history-grid"><div class="editor-loading">正在加载历史画面…</div></div>`;
      backdrop.appendChild(box);
      document.body.appendChild(backdrop);
      const close = () => { document.removeEventListener('keydown', onKey, true); backdrop.remove(); };
      const onKey = event => { if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); } };
      document.addEventListener('keydown', onKey, true);
      backdrop.addEventListener('pointerdown', event => { if (event.target === backdrop) close(); });
      box.querySelector('[data-history-close]').addEventListener('click', close);
      $('.image-editor-backdrop')?.remove();
      document.body.appendChild(backdrop);
      const grid = box.querySelector('.image-history-grid');
      const entries = await Promise.all(ids.map(async (assetId, index) => ({ assetId, index, data: await fetchAssetData(assetId) })));
      const usable = entries.filter(item => item.data);
      grid.innerHTML = usable.length
        ? usable.slice().reverse().map(item => `<button class="image-history-thumb" type="button" data-history-pick="${item.assetId}" title="点击恢复这一版"><img src="${item.data}" alt="历史画面 ${item.index + 1}" /><small>第 ${item.index + 1} 次</small></button>`).join('')
        : '<div class="editor-loading">历史画面已失效（资产被清理）</div>';
      grid.addEventListener('click', async event => {
        const pick = event.target.closest('[data-history-pick]');
        if (!pick) return;
        const data = await fetchAssetData(pick.dataset.historyPick);
        if (!data) return showToast('这一版画面已失效', '×');
        setMediaNodeImage(node, data, `历史画面 · ${node.dataset.previewName || '图片'}`, pick.dataset.historyPick, '历史恢复');
        scheduleSave();
        close();
        showToast('已恢复到这一版画面', '⏱');
      });
    }





