        const aspect = nodeOverride?.dataset.aspectRatio || settings.aspect || '16:9';
        const tier = nodeOverride?.dataset.resolution || imageResTier(settings.resolution);


        const qualityLabel = imageQualityLabelFor(settings.quality, supportedImageQualities(t2iModelId()));
        const countLabel = Math.max(1, Number(settings.count) || 1);
        aspectLabel.textContent = `${aspect} · ${qualityLabel} · ${tier} · ${countLabel}张`;
