      'ordered-list': '<path d="M9.5 6.5h10.5M9.5 12h10.5M9.5 17.5h10.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><text x="2.6" y="9" font-size="7.5" fill="currentColor">1</text><text x="2.6" y="14.5" font-size="7.5" fill="currentColor">2</text><text x="2.6" y="20" font-size="7.5" fill="currentColor">3</text>',
