      bar.querySelector('[data-popover="color"]').innerHTML = '<button type="button" role="menuitem" class="is-swatch is-default" data-text-color="" aria-label="默认颜色"></button>'
        + TEXT_COLORS.map(color => `<button type="button" role="menuitem" class="is-swatch" data-text-color="${color}" style="--text-swatch:${color}" aria-label="文字颜色 ${color}"></button>`).join('');
      bar.querySelector('[data-popover="align"]').innerHTML = [['left', '左对齐'], ['center', '居中对齐'], ['right', '右对齐']]
        .map(([value, label]) => `<button type="button" role="menuitem" title="${label}" aria-label="${label}" data-text-align="${value}">${textFormatIcon(`align-${value}`)}</button>`).join('');
