      if (button.dataset.fontSize !== undefined) { applyTextFontSize(button.dataset.fontSize); closeTextPopovers(bar); return; }
      if (button.dataset.textColor !== undefined) { applyTextColor(button.dataset.textColor); closeTextPopovers(bar); return; }
      if (button.dataset.textAlign !== undefined) { applyTextAlign(button.dataset.textAlign); closeTextPopovers(bar); return; }
      const action = button.dataset.format;
      if (!action) return;
      if (action === 'font-size' || action === 'color' || action === 'align') return toggleTextPopover(bar, action);
      if (action === 'bold') return execTextCommand('bold');
      if (action === 'italic') return execTextCommand('italic');
      if (action === 'underline') return execTextCommand('underline');
