    /**
     * 社区卡片工厂（r891 抽出）——**社区页与个人中心「分享的内容」共用同一份实现**。
     *
     * ★★★ 为什么必须抽出来：用户的需求是「已发布模型应该叫分享的内容，
     *   社区分享里我的分享里的内容在这里也要显示」——两个入口必须**同口径同内容**。
     *   若各写一份 markup，迟早漂移（本项目已多次踩「同一语义散落在多个入口」）。
     * ★ `mine()` 判据必须与社区页完全一致，**含 `item.id === state.projectId`**
     *   —— 少了这一条，当前正在编辑、还没打 shared 标记的项目就会漏掉。
     * ★ `filter` 语义与 `.community-tab` 的 `data-community-filter` 完全一致：
     *   all / projects / images / videos / music / models / templates / mine。
     * 返回 `{ html, counts }`：`html` 是卡片串，`counts` 是各分类条数（个人中心画「共 N 项」）。
     */
    function modelFavoriteButton(model) {return `<button type="button" class="community-model-favorite${model.favorited?' is-active':''}" data-model-favorite="${escapeHtml(model.id)}" aria-label="${model.favorited?'取消收藏':'收藏模型'}" aria-pressed="${!!model.favorited}" title="${model.favorited?'取消收藏':'收藏到预演台'}">${model.favorited?'★':'☆'}</button>`;}
    async function toggleCommunityModelFavorite(button){
      if(button.disabled)return;button.disabled=true;
      try{const result=await window.CanvasFlowDirectorFavoriteModel(button.dataset.modelFavorite,button.getAttribute('aria-pressed')!=='true');for(const b of document.querySelectorAll('[data-model-favorite]'))if(b.dataset.modelFavorite===result.id){b.textContent=result.favorited?'★':'☆';b.setAttribute('aria-pressed',String(result.favorited));b.ariaLabel=result.favorited?'取消收藏':'收藏模型';b.classList.toggle('is-active',result.favorited);}showToast(result.favorited?'已收藏，可在预演台“我的收藏”查看':'已取消收藏','☆');}catch(error){showToast(error.message,'×');}finally{button.disabled=false;}
    }
    function communityCardsFor(data = {}, filter = 'all') {
      const projects = Array.isArray(data.projects) ? data.projects : [];
      const music = Array.isArray(data.music) ? data.music : [];
      const assets = Array.isArray(data.assets) ? data.assets : [];
      const templates = Array.isArray(data.templates) ? data.templates : [];
      const models = Array.isArray(data.models) ? data.models : [];
      const user = currentUser();
      const mine = item => !!item?.ownerId && item.ownerId === user.id;
      const filteredProjects = filter === 'mine' ? projects.filter(mine) : filter === 'projects' ? projects : filter === 'all' ? projects : [];
      const filteredMusic = filter === 'mine' ? music.filter(mine) : filter === 'music' ? music : filter === 'all' ? music : [];
      const filteredAssets = filter === 'mine' ? assets.filter(mine) : filter === 'images' ? assets.filter(asset => asset.kind === 'image') : filter === 'videos' ? assets.filter(asset => asset.kind === 'video') : filter === 'all' ? assets : [];
      const filteredModels = filter === 'mine' ? models.filter(mine) : filter === 'models' ? models : filter === 'all' ? models : [];
      const coverStyle = item => item?.cover ? ` style="background-image:url('${escapeHtml(item.cover)}')"` : '';
      const projectCards = filteredProjects.map((project, index) => `<article class="community-card community-project-card" data-community-kind="projects" data-community-open-project="${escapeHtml(project.id)}" data-search-text="${escapeHtml(`${project.projectName || ''} ${project.ownerName || ''}`)}" title="点击进入项目工作流"><div class="community-cover community-cover-${index % 5}"${coverStyle(project)}><span>✦</span><small>${Number(project.nodeCount) || 0} 个节点</small><b class="community-cover-action">进入工作流</b></div><div class="community-card-copy"><strong>${escapeHtml(project.projectName || '未命名项目')}</strong><small>${escapeHtml(project.shared ? '公开工作流' : '仅自己可见')} · ${escapeHtml(formatUpdatedAt(project.updatedAt))}</small></div><div class="community-author"><button class="author-link" data-profile-id="${escapeHtml(project.ownerId || user.id)}" type="button"><span class="author-avatar">${escapeHtml(project.ownerAvatar || String(project.ownerName || '创').slice(0, 1))}</span>${escapeHtml(project.ownerName || user.name)}</button><button class="community-preview-button" data-community-preview-project="${escapeHtml(project.id)}" type="button">查看详情 →</button>${likeButtonMarkup('project', project)}<button class="community-open" data-community-open-project="${escapeHtml(project.id)}" type="button">进入工作流 →</button>${mine(project) ? `<button class="community-delete" data-community-delete-kind="project" data-community-delete="${escapeHtml(project.id)}" type="button" title="取消分享">取消分享</button>` : ''}</div></article>`).join('');
      const musicCards = filteredMusic.map((track, index) => `<article class="community-card community-music-card" data-community-kind="music" data-music-id="${escapeHtml(track.id)}" data-search-text="${escapeHtml(`${track.name || ''} ${track.ownerName || ''}`)}"><div class="community-music-cover music-cover-${index % 4}"><span>♫</span><button class="music-play" data-music-action="play" type="button" title="播放音频">▶</button><small>${escapeHtml(track.duration || '音频')}</small></div><div class="community-card-copy"><strong>${escapeHtml(track.name || '未命名音乐')}</strong><small>音乐分享 · ${escapeHtml(track.size || '社区音频')}</small></div><div class="community-author"><button class="author-link" data-profile-id="${escapeHtml(track.ownerId || user.id)}" type="button"><span class="author-avatar">${escapeHtml(track.ownerAvatar || String(track.ownerName || '创').slice(0, 1))}</span>${escapeHtml(track.ownerName || user.name)}</button><button class="community-preview-button" data-community-preview-music="${escapeHtml(track.id)}" type="button">查看详情 →</button>${likeButtonMarkup('music', track)}${mine(track) ? `<button class="community-delete" data-community-delete-kind="music" data-community-delete="${escapeHtml(track.id)}" type="button" title="删除分享">删除分享</button>` : ''}</div></article>`).join('');
      const assetCards = filteredAssets.map((asset, index) => `<article class="community-card community-asset-card" data-community-kind="assets" data-search-text="${escapeHtml(`${asset.name || ''} ${asset.ownerName || ''}`)}"><button class="community-asset-cover community-asset-open asset-${['one','two','three'][index % 3]}" data-community-open-asset="${escapeHtml(asset.id)}" type="button" title="放大查看${escapeHtml(asset.kind === 'video' ? '视频' : '图片')}">${asset.thumbnail||asset.cover||(asset.kind==='image'&&asset.mediaUrl)?`<img src="${escapeHtml(asset.thumbnail||asset.cover||asset.mediaUrl)}" alt="${escapeHtml(asset.name)}" loading="lazy">`:`<span>${escapeHtml(asset.kind === 'video' ? '▶' : '▧')}</span>`}<small>${escapeHtml(assetKindNames[asset.kind] || '素材')}</small><b class="community-cover-action">放大查看</b></button><div class="community-card-copy"><strong>${escapeHtml(asset.name || '未命名素材')}</strong><small>${escapeHtml(assetKindNames[asset.kind] || '素材')} · ${escapeHtml(asset.size || '—')}</small>${asset.description?`<p class="community-share-description">${escapeHtml(asset.description)}</p>`:''}</div><div class="community-author"><button class="author-link" data-profile-id="${escapeHtml(asset.ownerId || 'user-canvasflow')}" type="button"><span class="author-avatar">${escapeHtml(asset.ownerAvatar || String(asset.ownerName || '创').slice(0, 1))}</span>${escapeHtml(asset.ownerName || 'CanvasFlow 社区')}</button>${likeButtonMarkup('asset', asset)}<button class="community-preview-button" data-community-open-asset="${escapeHtml(asset.id)}" type="button">放大查看 →</button>${mine(asset) ? `<button class="community-delete" data-community-delete-kind="asset" data-community-delete="${escapeHtml(asset.id)}" type="button" title="删除分享">删除分享</button>` : ''}</div></article>`).join('');
      const modelCards = filteredModels.map((model, index) => `<article class="community-card community-model-card" data-community-kind="models" data-search-text="${escapeHtml(`${model.name || ''} ${model.ownerName || ''}`)}"><button class="community-cover community-model-preview community-cover-${index % 5}" data-community-preview-model="${escapeHtml(model.id)}" type="button" title="查看模型详情">${model.thumbnail?`<img src="${escapeHtml(model.thumbnail)}" alt="${escapeHtml(model.name)}" loading="lazy">`:'<span>◎</span>'}<small>${Number(model.uses) || 0} 次使用</small><b class="community-cover-action">查看详情</b></button><div class="community-card-copy"><strong>${escapeHtml(model.name || '未命名模型')}</strong><small>${escapeHtml(model.description || '暂无简介')}</small></div><div class="community-author"><button class="author-link" data-profile-id="${escapeHtml(model.ownerId || user.id)}" type="button"><span class="author-avatar">${escapeHtml(model.ownerAvatar || String(model.ownerName || '创').slice(0, 1))}</span>${escapeHtml(model.ownerName || user.name)}</button>${likeButtonMarkup('model', model)}${modelFavoriteButton(model)}<button class="community-preview-button" data-community-preview-model="${escapeHtml(model.id)}" type="button">查看详情 →</button>${mine(model) ? `<button class="community-delete" data-community-delete-kind="model" data-community-delete="${escapeHtml(model.id)}" type="button" title="删除分享">删除分享</button>` : ''}</div></article>`).join('');
      const counts = {
        projects: filteredProjects.length,
        images: filteredAssets.filter(item => item.kind === 'image').length,
        videos: filteredAssets.filter(item => item.kind === 'video').length,
        music: filteredMusic.length,
        models: filteredModels.length,
      };
      return { html: projectCards + musicCards + assetCards + modelCards, counts };
    }
