    async function searchAdminUsers() {
      const query = $('#adminUserSearch')?.value?.trim() || '';
      const result = await authRequest(`/api/admin/users?q=${encodeURIComponent(query)}`);
      if (!Array.isArray(result?.users)) return showToast(result?.message || '用户搜索失败', '×');
      adminState.users = result.users; renderAdminUsersPanel();
      const input = $('#adminUserSearch'); if (input) input.value = query;
    }
    async function saveAdminStorage(userId){
      const row=document.querySelector(`[data-admin-user-row="${CSS.escape(userId)}"]`),input=row?.querySelector('[data-admin-storage-quota]'),button=row?.querySelector('[data-admin-storage-save]');
      const value=Number(input?.value);if(!input?.value||!Number.isFinite(value)||value<0||value>102400)return showToast('请输入 0 至 102400 GB 的配额','×');
      button.disabled=true;
      try{await api('/api/admin/users/'+encodeURIComponent(userId)+'/storage',{method:'PUT',throwOnError:true,body:JSON.stringify({quotaBytes:Math.round(value*1024**3)})});state.storageView=null;showToast('账户空间配额已更新','✓');await loadAdminConsole();}
      catch(error){showToast(error.message,'×');}finally{button.disabled=false;}
    }
    async function saveAdminUser(userId) {
      const row = document.querySelector(`[data-admin-user-row="${CSS.escape(userId)}"]`); if (!row) return;
      const payload = { status: row.querySelector('[data-admin-account-status]')?.value, role: row.querySelector('[data-admin-role]')?.value, creditDelta: Number(row.querySelector('[data-admin-credit-delta]')?.value || 0), creditReason: row.querySelector('[data-admin-credit-reason]')?.value?.trim() || '管理员调整' };
      const result = await authRequest(`/api/admin/users/${encodeURIComponent(userId)}`, { method: 'PUT', body: JSON.stringify(payload) });
      if (!result?.user) return showToast(result?.message || '用户修改失败', '×');
      // ★ 调整的是**当前登录用户自己**时，同步侧边栏用量卡与本地余额缓存 ——
      //   refreshUsage 只在充值和页面启动时被调，后台改完自己的余额后侧边栏会一直显示旧值。
      if (userId === currentUser().id && Number.isFinite(Number(result.user.creditBalance))) {
        const balance = Number(result.user.creditBalance);
        const saved = identity.read();
        identity.write({ ...saved, bonusCredits: balance });
        if (authenticatedUser) authenticatedUser.creditBalance = balance;
        void refreshUsage();
      }
      showToast('用户权限与积分余额已更新', '✓'); await loadAdminConsole();
    }
    // 单用户积分调整记录（credit_ledger 台账）：余额 = SUM(amount)，删记录即回退该笔调整。
    // 区块可折叠：默认收起，首次展开才拉取（拉过一次后折叠/展开不再重复请求）。
    const adminChExpandedUsers = new Set();
    function toggleAdminCreditHistory(holder) {
      if (!holder) return;
      const userId = holder.dataset.adminHistoryUser;
      const collapsed = holder.classList.toggle('is-collapsed');
      if (collapsed) adminChExpandedUsers.delete(userId);
      else {
        adminChExpandedUsers.add(userId);
        if (!holder.dataset.loaded) void loadAdminCreditHistory(userId);
      }
    }
    async function loadAdminCreditHistory(userId) {
      const holder = document.querySelector(`[data-admin-credit-history][data-admin-history-user="${CSS.escape(userId)}"]`);
      if (!holder) return;
      const body = holder.querySelector('.admin-ch-body');
      const meta = holder.querySelector('.admin-ch-meta');
      const result = await authRequest(`/api/admin/users/${encodeURIComponent(userId)}/credit-history`);
      const history = Array.isArray(result?.history) ? result.history : [];
      holder.dataset.loaded = '1';
      if (meta) meta.textContent = history.length ? `（${history.length}）` : '（无）';
      if (!body) return;
      if (!history.length) { body.innerHTML = '<em class="admin-ch-empty">暂无调整记录</em>'; return; }
      body.innerHTML = history.map(item => `
        <div class="admin-ch-row"><b class="${item.amount < 0 ? 'is-minus' : 'is-plus'}">${item.amount > 0 ? '+' : ''}${creditMoney(item.amount)}</b><span class="admin-ch-reason" title="${escapeHtml(item.reason || '')}">${escapeHtml(item.reason || '管理员调整')}</span><time>${escapeHtml(String(item.createdAt || '').replace('T', ' ').slice(5, 16))}</time><button type="button" class="admin-ch-del" data-admin-ch-del="${escapeHtml(item.id)}" title="删除这条记录（余额将回退这笔调整）">×</button></div>`).join('');
    }
