        <div class="admin-plan-form-actions"><button type="button" class="admin-save-user" data-admin-plan-save="${escapeHtml(editing.id || '')}">保存</button><button type="button" class="admin-delete-user" data-admin-plan-cancel type="button">取消</button></div>
