    async function saveAdminPlan(planId) {
      const form = document.querySelector('[data-admin-plan-form]'); if (!form) return;
      const note = form.querySelector('[data-plan-field="note"]')?.value?.trim() || '';
      if (!note) return showToast('请填写套餐名称', '×');
      const price = Number(form.querySelector('[data-plan-field="price"]')?.value || 0);
      const features = (form.querySelector('[data-plan-field="features"]')?.value || '').split('\n').map(line => line.trim()).filter(Boolean).slice(0, 8);
      const popular = !!form.querySelector('[data-plan-field="popular"]')?.checked;
      const payload = { note, price, features, popular };
      const result = planId
        ? await authRequest(`/api/admin/plans/${encodeURIComponent(planId)}`, { method: 'PUT', body: JSON.stringify(payload) })
        : await authRequest('/api/admin/plans', { method: 'POST', body: JSON.stringify(payload) });
      if (!result?.plan) return showToast(result?.message || '套餐保存失败', '×');
      adminState.plans = Array.isArray(result.plans) ? result.plans : adminState.plans;
      subscriptionPlansCache = adminState.plans;   // 订阅弹窗同源刷新
      adminState.planEditing = null;
      showToast(planId ? '套餐已更新' : '套餐已创建', '✓');
      renderAdminPlansPanel();
    }
    async function deleteAdminPlan(planId) {
      const plan = (adminState.plans || []).find(item => item.id === planId); if (!plan) return;
      const confirmed = await askConfirm({ title: '删除套餐', message: `确定删除「${plan.note}」吗？订阅弹窗将不再展示该套餐。`, confirmText: '删除套餐', danger: true, icon: '🗑\uFE0E' });
      if (!confirmed) return;
      const result = await authRequest(`/api/admin/plans/${encodeURIComponent(planId)}`, { method: 'DELETE' });
      if (!result?.deleted) return showToast(result?.message || '删除失败', '×');
      adminState.plans = Array.isArray(result.plans) ? result.plans : adminState.plans;
      subscriptionPlansCache = adminState.plans;
      if (adminState.planEditing?.id === planId) adminState.planEditing = null;
      showToast(`已删除套餐「${plan.note}」`, '🗑\uFE0E');
      renderAdminPlansPanel();
    }
    // Auto-arrange: layered left-to-right layout. Nodes are assigned layers by longest-path
    // from their sources (Kahn), layers stack vertically centered, edges keep pointing right.
    function autoArrangeNodes() {
      const nodes = $$('.flow-node');
      if (nodes.length < 2) return showToast('至少两个节点才能整理布局', '▦');
      const edges = window.CanvasFlowConnections?.getEdges?.() || [];
      const zoom = state.zoom || 1;
      const info = new Map(nodes.map(node => {
        const rect = node.getBoundingClientRect();
        return [node.dataset.nodeId, { node, w: rect.width / zoom, h: rect.height / zoom, layer: 0 }];
      }));
      const relevant = edges.filter(edge => info.has(edge.source) && info.has(edge.target));
      const indegree = new Map([...info.keys()].map(id => [id, 0]));
      relevant.forEach(edge => indegree.set(edge.target, indegree.get(edge.target) + 1));
      const queue = [...info.keys()].filter(id => indegree.get(id) === 0);
      const settled = new Set();
      while (queue.length) {
        const id = queue.shift();
        if (settled.has(id)) continue;
        settled.add(id);
        relevant.filter(edge => edge.source === id).forEach(edge => {
          info.get(edge.target).layer = Math.max(info.get(edge.target).layer, info.get(id).layer + 1);
          indegree.set(edge.target, indegree.get(edge.target) - 1);
          if (indegree.get(edge.target) === 0) queue.push(edge.target);
        });
      }
      const layers = new Map();
      [...info.values()].forEach(item => {
        if (!layers.has(item.layer)) layers.set(item.layer, []);
        layers.get(item.layer).push(item);
      });
      // Keep each layer's current vertical order so the arrange feels like tidying, not shuffling.
      layers.forEach(list => list.sort((a, b) => (parseFloat(a.node.style.top) || 0) - (parseFloat(b.node.style.top) || 0)));
      const gapX = 96, gapY = 44;
      const metrics = [...layers.entries()].map(([layer, list]) => ({
        list,
        height: list.reduce((sum, item) => sum + item.h, 0) + gapY * (list.length - 1),
        width: Math.max(...list.map(item => item.w)),
      })).sort((a, b) => a.layer - b.layer);
      const tallest = Math.max(...metrics.map(metric => metric.height));
      remember();
      nodes.forEach(node => node.classList.add('layout-animating'));
      let x = 0;
      metrics.forEach(metric => {
        let y = (tallest - metric.height) / 2;
        metric.list.forEach(item => {
          item.node.style.left = `${Math.round(x)}px`;
          item.node.style.top = `${Math.round(y)}px`;
          y += item.h + gapY;
        });
        x += metric.width + gapX;
      });
      renderMiniMap();
      scheduleSave();
      setTimeout(() => {
        nodes.forEach(node => node.classList.remove('layout-animating'));
        window.CanvasFlowConnections?.draw?.();
        fitCanvas();
        showToast(`已整理 ${nodes.length} 个节点布局`, '▦');
      }, 480);
    }

    async function deleteAllNodes() {
      const nodes = $$('.flow-node');
      if (!nodes.length) return showToast('画布上还没有节点', '⌫');
      const confirmed = await askConfirm({ title: '删除全部节点', message: `确定删除画布上的全部 ${nodes.length} 个节点吗？所有连线会一并清除。可按 Ctrl+Z 撤销。`, confirmText: '全部删除', danger: true, icon: '🗑\uFE0E' });
      if (!confirmed) return;
      remember();
      window.CanvasFlowConnections?.setEdges?.([]);
      nodes.forEach(node => node.remove());
      state.activeNodeId = null;
      state.nodeCount = 0;
      updateNodeCount();
      renderMiniMap();
      scheduleSave();
      showToast(`已删除 ${nodes.length} 个节点及全部连线（可撤销）`, '⌫');
    }

    async function deleteAdminUser(userId) {
      const user = adminState.users.find(item => item.id === userId); if (!user) return;
      const name = user.nickname || user.email || user.id;
      const confirmed = await askConfirm({ title: '删除账户', message: `确定删除「${name}」吗？该账户的登录凭证和积分记录将一并清除，且无法恢复。`, confirmText: '删除账户', danger: true, icon: '🗑\uFE0E' });
      if (!confirmed) return;
      const result = await authRequest(`/api/admin/users/${encodeURIComponent(userId)}`, { method: 'DELETE' });
      if (!result?.deleted) return showToast(result?.message || '账户删除失败', '×');
      showToast(`已删除账户「${name}」`, '🗑\uFE0E'); await loadAdminConsole();
    }

    // 离开画布（切到项目 / 素材 / 社区 / 模板 / 后台…）时把对话面板收起来：
    // 面板和设置弹窗都是 position:fixed，不收起来会一直浮在别的页面上挡内容。
    function agentCollapseForViewChange() {
      if (agentState.open) agentToggle(false);
      agentSettingsClose();
    }

    function mountGenerationStudio(host, kind) {
      const isImage = kind === 'image';
      const medium = isImage ? '图片' : '视频';
      const epoch = navigationEpoch;
      const headers = workspaceHeader();
      const draftKey = JSON.stringify([headers['X-Workspace-Id'] || '', kind]);
      const active = () => epoch === navigationEpoch && !host.hidden
        && headers['X-Workspace-Id'] === workspaceHeader()['X-Workspace-Id'];
      const request = (path, options = {}) => api(path, { ...options, headers, throwOnError: true });
      host.innerHTML = `<div class="content-view-inner generation-studio">
        <header class="view-heading"><div><span class="eyebrow">独立创作</span><h1>${medium}生成台</h1>
          <p>在当前工作区直接生成${medium}，生成结果可在素材管理中找到。</p></div></header>
        <div class="studio-layout">
          <form class="studio-panel studio-form">
            <label>生成模型<select name="model" required><option value="">正在加载模型…</option></select></label>
            <p class="studio-note" data-model-note></p>
            <button class="studio-secondary" type="button" data-provider>供应商设置</button>
            <label>提示词<textarea name="prompt" required placeholder="${isImage ? '描述主体、构图和光线…' : '描述主体动作、镜头运动和场景变化…'}"></textarea></label>
            <div class="studio-fields" data-specs></div>
            <label data-reference>${isImage ? '参考图片（可选）' : '参考图片'}<input name="reference" type="file" accept="image/png,image/jpeg,image/webp"></label>
            <button class="view-action" type="submit" disabled>生成${medium}</button>
            <p class="studio-note" role="status" data-submit-status></p>
          </form>
          <section class="studio-panel studio-history" aria-label="工作区任务">
            <header><h2>工作区任务</h2><button class="studio-secondary" type="button" data-refresh>刷新</button></header>
            <div data-history aria-live="polite"><p class="studio-note">正在加载任务…</p></div>
            <button class="studio-secondary" type="button" data-more hidden>查看更多</button>
          </section>
        </div></div>`;
      const form = host.querySelector('.studio-form');
      form.elements.prompt.value = generationStudioDrafts.get(draftKey) || '';
      const saveDraft = () => generationStudioDrafts.set(draftKey, form.elements.prompt.value);
      form.elements.prompt.addEventListener('input', saveDraft);
      const modelSelect = form.elements.model;
      const reference = form.elements.reference;
      const referenceField = reference.closest('label');
      const specs = form.querySelector('[data-specs]');
      const submit = form.querySelector('[type="submit"]');
      const status = form.querySelector('[data-submit-status]');
      const modelNote = form.querySelector('[data-model-note]');
      const history = host.querySelector('[data-history]');
      const more = host.querySelector('[data-more]');
      let models = [], busy = false, loading = false, historyLoading = false;
      let limit = 12, timer, lastHistory, pollIndex = 0;
      const selectedModel = () => models.find(model => model.id === modelSelect.value);

      function renderModelControls() {
        const model = selectedModel();
        const contract = currentModelContract(model)?.providerContract || {};
        const rows = model ? (specRowsFor(kind, model) || []) : [];
        const select = (key, label, options, defaultValue) => options.length ? `<label>${label}<select name="${key}">${options.map(({ value, label: caption }) =>
          `<option value="${escapeHtml(value)}"${String(value) === String(defaultValue) ? ' selected' : ''}>${escapeHtml(caption || value)}</option>`).join('')}</select></label>` : '';
        const field = (key, label) => {
          const row = specRowOf(rows, key);
          return select(key, label, row?.options || [], row?.default);
        };
        const modes = [
          { value: 'text2video', label: '文生视频' },
          { value: 'singleImage2video', label: '图生视频' },
        ].filter(mode => !contract.apiReferenceModes?.length || contract.apiReferenceModes.includes(mode.value));
        specs.innerHTML = model ? (isImage
          ? field('aspectRatio', '画面比例') + field('resolution', '清晰度') + field('quality', '画质')
          : select('mode', '生成方式', modes, 'text2video') + field('aspectRatio', '画面比例')
            + field('resolution', '清晰度') + field('duration', '时长') + field('generateAudio', '生成音频')) : '';
        modelNote.textContent = !model ? '请在供应商设置中启用对应的模型。'
          : !isImage && !modes.length ? '此模型需要其他参考素材，请在创作画布中使用。' : '';
        updateForm();
      }

      function updateForm() {
        referenceField.hidden = !isImage && form.elements.mode?.value !== 'singleImage2video';
        reference.required = !referenceField.hidden && !isImage;
        submit.disabled = busy || loading || !selectedModel() || (!isImage && !form.elements.mode);
      }

      async function loadModels() {
        if (!active() || loading) return;
        loading = true;
        updateForm();
        try {
          const [, result] = await Promise.all([loadModelSpecs(), request('/api/ai/models')]);
          if (!active()) return;
          const previous = modelSelect.value;
          models = result.models?.[isImage ? 't2i' : 'video'] || [];
          modelSelect.innerHTML = models.length ? models.map(model =>
            `<option value="${escapeHtml(model.id)}">${escapeHtml(model.name || model.model || model.id)}</option>`).join('')
            : '<option value="">没有已启用的模型</option>';
          if (models.some(model => model.id === previous)) modelSelect.value = previous;
          renderModelControls();
        } catch (error) {
          if (active()) modelNote.textContent = error.message || '模型列表加载失败。';
        } finally {
          loading = false;
          if (active()) updateForm();
        }
      }

      function mediaUrl(job) {
        const url = String(isImage ? job.imageUrl || '' : job.videoUrl || '');
        if (/^\/media\/[\w.-]+$/.test(url)) return url;
        try {
          const parsed = new URL(url);
          return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : '';
        } catch { return ''; }
      }

      function renderHistory(result) {
        const jobs = result.jobs || [];
        const markup = jobs.map(job => {
          const url = escapeHtml(mediaUrl(job));
          const progress = job.progress == null ? '' : ` · ${Math.round(Number(job.progress) || 0)}%`;
          const label = ({ queued: '排队中', running: '生成中', completed: '已完成', failed: '失败' })[job.status] || '处理中';
          const media = job.status === 'completed' && url
            ? (isImage ? `<img src="${url}" alt="生成的图片" loading="lazy">`
              : `<video src="${url}" controls preload="none" playsinline aria-label="生成的视频"></video>`)
            : '';
          return `<article class="studio-job">${media}<div class="studio-job-copy">
            <strong>${escapeHtml(job.prompt || medium + '任务')}</strong>
            <span>${label}${job.status === 'running' ? progress : ''} · ${escapeHtml(models.find(model => model.id === job.modelId)?.name || job.modelId || '生成模型')}</span>
            ${job.error ? `<p>${escapeHtml(job.error)}</p>` : ''}
            ${media ? `<a href="${url}" ${url.startsWith('/media/') ? 'download' : 'target="_blank" rel="noopener"'}>${url.startsWith('/media/') ? '下载原文件' : '打开原文件'}</a>` : ''}
          </div></article>`;
        }).join('');
        // Keep video playback intact when a refresh leaves the task list unchanged.
        if (markup !== lastHistory) {
          history.innerHTML = markup || `<p class="studio-note studio-empty">这个工作区还没有${medium}任务。</p>`;
          lastHistory = markup;
        }
        more.hidden = jobs.length >= result.total || limit >= 200;
      }

      async function loadHistory(sync = false) {
        if (!active() || historyLoading) return;
        clearTimeout(timer);
        historyLoading = true;
        try {
          const path = `/api/jobs?kind=${kind}&limit=${limit}`;
          let result = await request(path);
          if (!active()) return;
          if (sync && result.activeCount) {
            const candidates = (await request(`/api/jobs?kind=${kind}&status=running&limit=200`)).jobs || [];
            const queued = (await request(`/api/jobs?kind=${kind}&status=queued&limit=200`)).jobs || [];
            const pending = [...candidates, ...queued];
            if (active() && pending.length) {
              const job = pending[pollIndex++ % pending.length];
              await request(`/api/jobs/${encodeURIComponent(job.id)}`).catch(() => null);
              if (active()) result = await request(path);
            }
          }
          if (active()) renderHistory(result);
        } catch (error) {
          if (active()) {
            lastHistory = undefined;
            history.textContent = error.message || '任务记录加载失败，请刷新。';
          }
        } finally {
          historyLoading = false;
          if (active()) timer = setTimeout(() => loadHistory(true), 3500);
        }
      }

      form.addEventListener('submit', async event => {
        event.preventDefault();
        const model = selectedModel();
        const prompt = form.elements.prompt.value.trim();
        if (!active() || busy || !model || submit.disabled) return;
        if (!prompt) { status.textContent = '请填写提示词。'; return; }
        const values = new FormData(form);
        const mode = values.get('mode');
        const file = referenceField.hidden ? null : reference.files[0];
        busy = true;
        updateForm();
        status.textContent = file ? '正在上传参考图片…' : '正在提交任务…';
        try {
          const referenceImages = [];
          if (file) {
            const uploaded = await uploadMediaFile(file);
            if (!active()) return;
            if (!uploaded?.url) throw new Error('参考图片上传失败，请检查文件格式后重试。');
            referenceImages.push(uploaded.url);
          }
          const payload = { modelId: model.id, prompt, referenceImages };
          if (isImage) {
            const aspect = values.get('aspectRatio');
            const resolution = values.get('resolution');
            payload.asyncTask = true;
            if (resolution || aspect) payload.size = aspectToResolution(aspect || '1:1', resolution || '1K');
            if (values.has('quality')) payload.quality = values.get('quality');
            payload.generationSettings = { ...(aspect ? { aspect } : {}), ...(resolution ? { resolution } : {}) };
          } else {
            const settings = modelDefaultSettings(model);
            settings.referenceMode = mode;
            settings.videoMode = mode === 'singleImage2video' ? 'image-to-video' : 'text-to-video';
            for (const key of ['aspectRatio', 'resolution', 'duration', 'generateAudio']) {
              if (!values.has(key)) continue;
              const value = values.get(key);
              settings[key] = key === 'generateAudio' ? ['true', 'on', '1'].includes(value) : value;
            }
            if (typeof settings.generateAudio === 'string') settings.generateAudio = ['true', 'on', '1'].includes(settings.generateAudio);
            settings.generateCount = 1;
            payload.generationSettings = settings;
          }
          await request(isImage ? '/api/ai/image-generate' : '/api/generate', {
            method: 'POST', body: JSON.stringify(payload),
          });
          if (active()) {
            status.textContent = '任务已提交，可在右侧查看进度。';
            void loadHistory();
          }
        } catch (error) {
          if (active()) status.textContent = error.message || '生成任务提交失败。';
        } finally {
          busy = false;
          if (active()) updateForm();
        }
      });
      modelSelect.addEventListener('change', renderModelControls);
      specs.addEventListener('change', updateForm);
      form.querySelector('[data-provider]').addEventListener('click', () => window.CanvasFlowSettings?.open?.('providers'));
      host.querySelector('[data-refresh]').addEventListener('click', () => { void loadHistory(true); void loadModels(); });
      more.addEventListener('click', () => { limit = Math.min(200, limit + 12); void loadHistory(); });
      window.addEventListener('canvasflow:models-changed', loadModels);
      unmountGenerationStudio = () => {
        saveDraft();
        clearTimeout(timer);
        window.removeEventListener('canvasflow:models-changed', loadModels);
      };
      void loadModels();
      void loadHistory();
    }

    function openView(viewName) {
      agentCollapseForViewChange();
      if (['admin','profile','community'].includes(viewName)) return;
      // ★ r881：侧边栏「个人中心」入口。个人中心不是「取接口渲染 viewPanel」那一类视图，
      //   直接复用已有的 `openProfileCenter()`（它内部会 `setActiveNav('profile')` 点亮入口）。
      if (viewName === 'profile') return openProfileCenter();
      const view = $('#contentView'); if (!view) return;
      if (viewName === 'image-studio' || viewName === 'video-studio') {
        clearTimeout(state.saveTimer);
        void saveProject();
        view.hidden = false;
        $('#canvasWrap')?.classList.add('view-hidden');
        $('.composer-bar')?.classList.add('view-hidden');
        inspector.classList.add('view-hidden');
        setHeaderContext(false);
        setActiveNav(viewName);
        mountGenerationStudio(view, viewName === 'image-studio' ? 'image' : 'video');
        return;
      }
      if (viewName === 'materials') {
        clearTimeout(state.saveTimer);
        const pendingSave = saveProject();
        view.hidden = false;
        $('#canvasWrap')?.classList.add('view-hidden');
        $('.composer-bar')?.classList.add('view-hidden');
        inspector.classList.add('view-hidden');
        setHeaderContext(false); setActiveNav('materials');
        window.CanvasFlowMaterials.mount({host:view, escapeHtml, api,
          workspaceName:currentWorkspace()?.name, pendingSave,
          toast:showToast, askText, openProject, upload:uploadMediaFile});
        return;
      }
      const configs = {
        projects: ['项目空间', '我的项目', '管理你的创作项目、版本和最近生成内容。', '新建项目'],
        assets: ['素材管理', '素材库', '集中管理图片、视频、音频和生成结果，随时拖入画布。', '上传素材'],
        music: ['社区音频', '音乐库', '选择、收藏和分享可复用的音乐，为你的画面补充声音氛围。', '上传音乐'],
        community: ['发现与分享', '社区分享', '浏览创作者公开分享的项目、工作流和音乐素材。', '分享当前项目'],
      };
      const config = configs[viewName]; if (!config) return;
      // 社区视图自带 community-heading（标题+描述+分享按钮），不能重复渲染 viewHeading，
      // 但 #viewPanel 容器必须存在，否则社区内容没有任何挂载点（之前整个页面因此空白）。
      if (viewName !== 'community') view.innerHTML = viewHeading(...config, viewName);
      else view.innerHTML = '<div class="content-view-inner"><div id="viewPanel" class="view-panel"><div class="loading-state">正在加载社区分享…</div></div></div>';
      view.hidden = false;
      $('#canvasWrap')?.classList.add('view-hidden'); $('.composer-bar')?.classList.add('view-hidden'); inspector.classList.add('view-hidden'); setHeaderContext(false); setActiveNav(viewName);
      if (viewName === 'music') return renderMusicLibrary();
      if (viewName === 'community') return loadCommunity();
      const endpoint = viewName === 'projects' ? '/api/projects' : '/api/assets';
      const pendingSave = viewName === 'projects' ? saveProject() : null;
      const viewEpoch = navigationEpoch;
      Promise.resolve(pendingSave).then(() => api(endpoint)).then(result => {
        if (viewEpoch !== navigationEpoch) return;
        if (viewName === 'projects') renderProjects(result?.projects || readLocalProjects());
        if (viewName === 'assets') renderAssets(result?.assets || []);
      });
    }

    function updateProjectBadge(count) {
      state.workspaceProjectCount = Math.max(0, Number(count) || 0);
      const badge = $('.nav-item[data-view="projects"] em');
      if (badge) badge.textContent = String(Math.max(0, Number(count) || 0));
    }

    async function deleteProject(projectId) {
      if (!projectId || projectId === 'new') return;
      const card = $$('.project-card').find(item => item.dataset.projectId === projectId);
      const label = card?.querySelector('strong')?.textContent?.trim() || '这个项目';
      const confirmed = await askConfirm({ title: '删除项目', message: `确定删除「${label}」吗？关联成片将移入本地回收区保留，画布项目将被删除。`, confirmText: '删除', danger: true, icon: '⌫' });
      if (!confirmed) return;
      const wasActive = state.projectId === projectId;
      const wasPending = state.projectLoadPending;
      if (wasActive) { clearTimeout(state.saveTimer); state.projectLoadPending = true; stopJobPolling(); }
      const result = await api(`/api/projects/${encodeURIComponent(projectId)}`, { method: 'DELETE' });
      if (!isStandaloneFile() && !result?.deleted) {
        if (wasActive && state.projectId === projectId) { state.projectLoadPending = wasPending; resumeJobBindings(); }
        return showToast('删除失败，请确认本地服务已启动', '×');
      }
      projectSaveQueue.discard(projectId);
      removeLocalProject(projectId);
      if (state.projectId === projectId) clearCurrentProject();
      const refreshed = await api('/api/projects');
      const remaining = refreshed?.projects || readLocalProjects();
      if (!remaining.length && (!state.projectId || state.projectId === projectId)) clearCurrentProject();
      openView('projects');
      renderProjects(remaining);
      showToast(remaining.length ? `已删除「${label}」` : '已删除最后一个项目，请先新建项目，再进入创作画布', '⌫');
    }

    function applyLoadedProject(project) {
      state.canvasEpoch = (state.canvasEpoch || 0) + 1;
      state.activeAgentRun?.abort();
      state.activeVideoSubmission?.release();
      state.projectIsDraft = false;
      state.projectLoadPending=false;
      stopJobPolling();
      state.projectId = project.id; state.lastOpenedProjectId = project.id; state.projectName = project.projectName || '未命名创作项目';
      updateProjectUrl(state.projectId);
      // ★★ 乐观锁的版本号必须跟着项目一起搬，否则下一个项目会带着**上一个项目的 revision** 去保存。
      //   漏了这一行的后果（实测复现过）：
      //     打开 A（revision 1）→ 编辑几次推到 3 → 从项目列表切到 B（B 自己还是 1）
      //     → 在 B 里一改，PUT 带上 `revision: 3` → 服务端 3 != 1 → **409 被拒**
      //     → 前端弹「这个项目在别处被更新过，已按你当前的版本覆盖」——
      //     用户根本没在别处编辑过，这是一句**和事实不符的告警**；B 还白丢一次保存。
      //   注意 `loadProject()` 那条路径是有这行的（见 `state.projectRevision = Number(project.revision)`），
      //   这里是对称补上 —— 改一处时务必同时想另一处。
      state.projectRevision = Number(project.revision) || 0;
      projectSaveQueue.reset(state.projectId,state.projectRevision);
      state.zoom = Number(project.zoom) || 1; state.panX = Number(project.panX) || 0; state.panY = Number(project.panY) || 0;
      state.advancedSettings = project.advancedSettings ? { ...defaultAdvancedSettings(), ...project.advancedSettings } : defaultAdvancedSettings();
      state.generationSettings = project.generationSettings ? { ...defaultGenerationSettings(), ...project.generationSettings } : defaultGenerationSettings();
        if (project.imageGenerationSettings) state.imageGenerationSettings = normalizeImageGenerationSettings(project.imageGenerationSettings);
       state.projectShared = Boolean(project.shared); state.projectDescription = project.description || '';
       state.modelPrompt = typeof project.modelPrompt === 'string' ? project.modelPrompt : '';
       state.projectOwnerId = project.ownerId || ''; state.projectOwnerName = project.ownerName || ''; state.projectOwnerAvatar = project.ownerAvatar || '';
      state.references = Array.isArray(project.references) ? project.references : [];
      state.linkedRefs = [];
      renderDockRefs();
      applyJobBindings(project.jobBindings);
      state.lastRefsSig = null;
      // The canvas must be visible before the graph is applied, otherwise ports measure 0x0 and edges land at the origin.
      openCanvas(); updateTransform();
      if (Array.isArray(project.nodes) && project.nodes.length) applyGraph(project); else resetCanvasNodes();
      if (Array.isArray(project.edges)) setGraphEdges(project.edges);
      $('#projectName').textContent = state.projectName; updateNodeCount(); resetHistoryBaseline();
      window.CanvasFlowConnections?.draw?.();
      // 载入项目后不预选节点：刷新 / 首次进入都保持「无选中」状态，避免凭空高亮第一张卡片
      // （连带弹出快捷工具栏、把提示词 Dock 钉到该卡片下方）。选中只由用户点击卡片产生。
      clearNodeSelection();
      syncInspectorToNode(null);
      resumeJobBindings();
      void resumeGenerationJobs();
    }

    function clearCurrentProject() {
      state.projectNavigationRequest = (state.projectNavigationRequest || 0) + 1;
      state.canvasEpoch = (state.canvasEpoch || 0) + 1;
      state.activeAgentRun?.abort();
      state.activeVideoSubmission?.release();
      const previousId = state.projectId;
      clearTimeout(state.saveTimer);
      stopJobPolling();
      if (previousId) projectSaveQueue.discard(previousId);
      state.projectLoadPending = true;
      state.projectIsDraft = false;
      state.projectId = ''; state.lastOpenedProjectId = ''; state.projectName = ''; state.projectRevision = 0;
      state.jobBindings = []; state.references = []; state.linkedRefs = []; state.modelPrompt = ''; state.lastRefsSig = null;
      if (promptInput) promptInput.value = '';
      if (safeStorage.get()?.projectId === previousId) safeStorage.set(null);
      updateProjectUrl('');
      resetCanvasNodes(); resetHistoryBaseline(); renderDockRefs(); syncInspectorToNode(null);
      const name = $('#projectName'); if (name) name.textContent = '';
    }

    function activateFallbackProject() {
      const missingId = state.projectId;
      clearCurrentProject();
      if (missingId) removeLocalProject(missingId);
      openView('projects');
      showToast('项目不存在或已被删除，请打开其他项目或新建项目', 'ⓘ');
      window.CanvasFlowStartup?.ready();
    }

    async function openProject(projectId) {
      if (projectId === 'new') return newProject();
      const requestId = state.projectNavigationRequest = (state.projectNavigationRequest || 0) + 1;
      const viewEpoch = navigationEpoch;
      const headers = { ...workspaceHeader() };
      const result = await api(`/api/projects/${encodeURIComponent(projectId)}`, { headers });
      if (requestId !== state.projectNavigationRequest || viewEpoch !== navigationEpoch
          || JSON.stringify(headers) !== JSON.stringify(workspaceHeader())) return;
      const project = result?.project || findLocalProject(projectId);
      if (!project) return showToast('项目暂时无法打开', '×');
      applyLoadedProject(project);
      saveProject();
      showToast(`已打开${state.projectName}`, '↗');
    }

    function remember() {
      if (state.isRestoring) return;
      state.history.push(historySnapshot());
      if (state.history.length > 30) state.history.shift(); state.future = [];
    }

    function restoreSnapshot(snapshot) {
      if (!snapshot) return;
      state.isRestoring = true; applyGraph(snapshot);
      state.zoom = Number(snapshot.zoom) || 1; state.panX = Number(snapshot.panX) || 0; state.panY = Number(snapshot.panY) || 0;
      state.projectName = snapshot.projectName || state.projectName; $('#projectName').textContent = state.projectName;
      state.isRestoring = false; updateTransform(); updateNodeCount(); scheduleSave();
      // 撤销可能改掉了当前选中节点的文案；不同步的话 Dock 里还留着旧文本，敲一个键就把撤销吃掉了。
      const activeNode = $$('.flow-node').find(item => item.dataset.nodeId === state.activeNodeId);
      if (activeNode) syncInspectorToNode(activeNode);
      else { state.modelPrompt = ''; if (promptInput) promptInput.value = ''; renderPromptHighlight(); }
    }

    function undo() {
      if (!requireCurrentProject()) return;
      // The initial snapshot is the baseline, not a user action; consuming it would look like an
      // undo that changes nothing, so stop when only the baseline is left.
      if (state.history.length <= 1) return showToast('没有可撤销的操作', '↶');
      const previous = state.history.pop(); if (!previous) return showToast('没有可撤销的操作', '↶');
      state.future.push(historySnapshot()); restoreSnapshot(previous); showToast('已撤销上一步操作', '↶');
    }
    function redo() {
      if (!requireCurrentProject()) return;
      const next = state.future.pop(); if (!next) return showToast('没有可重做的操作', '↷');
      state.history.push(historySnapshot()); restoreSnapshot(next); showToast('已重做上一步操作', '↷');
    }

    function shareProject() {

    }

    function exportProject() {
      if (!requireCurrentProject()) return;
      const blob = new Blob([JSON.stringify({ projectId: state.projectId, projectName: state.projectName, ...graphSnapshot(), zoom: state.zoom, panX: state.panX, panY: state.panY, generationSettings: state.generationSettings, advancedSettings: state.advancedSettings }, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `${state.projectName || 'canvasflow-project'}.json`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); showToast('项目 JSON 已导出', '↓');
    }

    // Each lane is one source group feeding a model + output pair, so node counts stay in sync with the catalog.
    const templateBlueprints = {
      'template-mv': [['prompt', 'image', 'audio'], ['prompt', 'image'], ['prompt'], ['prompt']],
      'template-drama': [['prompt', 'image', 'prompt'], ['prompt', 'audio']],
      'template-ugc': [['prompt', 'image'], ['prompt']],
      'template-travel': [['prompt', 'image'], ['prompt', 'audio'], ['prompt']],
    };

    // 「角色一致性 · 测试」模板：一键铺出 角色设定 → 视频生成 的测试链路。
    function buildCharacterTestGraph() {
      const charDesc = '黑色短发少女，齐肩发微乱，清冷眼神；JK 制服：白衬衫 + 深蓝背心 + 格纹短裙 + 黑色过膝袜；白色运动鞋。气质安静疏离。';
      const nodes = [
        { id: 'ct-prompt-char', type: 'prompt', left: 90, top: 90, title: '角色设定 · 奈々', copy: charDesc },
        { id: 'ct-prompt-shot', type: 'prompt', left: 90, top: 620, title: '镜头 · 走廊回眸', copy: '黄昏教室走廊，逆光。奈々穿 JK 制服从走廊尽头缓步走来，忽然回头看向镜头，裙摆与发丝随风轻扬，浅景深，电影感构图。' },
        { id: 'ct-model', type: 'model', left: 470, top: 90 },
        { id: 'ct-output', type: 'output', left: 880, top: 90 },
      ];
      const edges = [
        { id: 'edge-ct-1', source: 'ct-prompt-char', target: 'ct-model' },
        { id: 'edge-ct-2', source: 'ct-prompt-shot', target: 'ct-model' },
        { id: 'edge-ct-3', source: 'ct-model', target: 'ct-output' },
      ];
      return { nodes, edges };
    }

    // Vertical steps have to clear the tallest node (an output card is ~244px), otherwise stacked lane
    // inputs cover each other's ports and the generated template cannot be rewired. 215px used to
    // overlap cards; the step must stay above the real media-node height.
    const LANE_SOURCE_STEP = 260;
    const LANE_GAP = 90;
    const LANE_MIN_HEIGHT = 300;
    function blueprintGraph(lanes) {
      const nodes = [];
      const edges = [];
      let top = 90;
      lanes.forEach((lane, laneIndex) => {
        const modelId = `bp-model-${laneIndex + 1}`;
        const outputId = `bp-output-${laneIndex + 1}`;
        lane.forEach((type, index) => {
          const id = `bp-${type}-${laneIndex + 1}-${index + 1}`;
          nodes.push({ id, type, left: 90, top: top + index * LANE_SOURCE_STEP });
          edges.push({ id: `edge-${id}-${modelId}`, source: id, target: modelId });
        });
        const laneHeight = Math.max(lane.length * LANE_SOURCE_STEP, LANE_MIN_HEIGHT);
        const middle = top + Math.round((laneHeight - LANE_SOURCE_STEP) / 2);
        nodes.push({ id: modelId, type: 'model', left: 520, top: middle });
        nodes.push({ id: outputId, type: 'output', left: 950, top: middle + 20 });
        edges.push({ id: `edge-${modelId}-${outputId}`, source: modelId, target: outputId });
        top += laneHeight + LANE_GAP;
      });
      return { nodes, edges };
    }

    async function useTemplate(target) {
      const templateId = target.dataset.templateId;
      const name = target.querySelector('strong')?.textContent?.trim() || '模板项目';
      return applyTemplate(templateId, name);
    }

    async function applyTemplate(templateId, templateName) {
      const name = String(templateName || '模板项目');
      const lanes = templateBlueprints[templateId];
      remember();
      stopJobPolling();
      state.projectName = `${name} · 副本`;
      state.zoom = 1; state.panX = 0; state.panY = 0;
      state.advancedSettings = defaultAdvancedSettings();
      state.generationSettings = defaultGenerationSettings();
       state.imageGenerationSettings = { modelId: 'flux-1.1' };
      state.jobBindings = [];
      state.lastRefsSig = null;
      // 不重置就会继承上一项目的分享状态和参考图：模板副本会被静默公开，旧参考图也会混进来。
      state.projectShared = false; state.projectDescription = '';
      state.references = [];
      state.linkedRefs = [];
      state.modelPrompt = '';
      if (promptInput) promptInput.value = '';
      const templateOwner = currentUser();
      state.projectOwnerId = templateOwner.id; state.projectOwnerName = templateOwner.name; state.projectOwnerAvatar = templateOwner.avatar;
      renderDockRefs();
      openCanvas();
      if (templateId === 'template-charactertest') applyGraph(buildCharacterTestGraph());
      else if (lanes) applyGraph(blueprintGraph(lanes));
      else resetCanvasNodes();
      $('#projectName').textContent = state.projectName;
      updateTransform();
      window.CanvasFlowConnections?.draw?.();
      const snapshot = graphSnapshot();
      const created = await api('/api/projects', { method: 'POST', body: JSON.stringify({ projectName: state.projectName, ...snapshot, nodeCount: snapshot.nodes.length }) });
      state.projectId = created?.project?.id || `project-${Date.now()}`;
      state.lastOpenedProjectId = state.projectId;
      updateProjectUrl(state.projectId);
      resetHistoryBaseline();
      saveProject();
      // 模板生成的图同样不预选第一个节点，保持「进入画布即无选中」的一致行为。
      clearNodeSelection();
      syncInspectorToNode(null);
      showToast(`已按「${name}」模板生成 ${snapshot.nodes.length} 个节点`, '✦');
    }

    const AGREEMENT_VERSION = '2026-09-01';
    let authenticatedUser = {id:'local-device',nickname:'本地工作台',role:'admin',local:true};
    let sessionExpired = false;
    function expireAuthenticatedSession() {

    }
    async function checkAuthenticatedSession() {

    }
    
    window.addEventListener('focus', checkAuthenticatedSession);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) checkAuthenticatedSession(); });
    let authResendTimer = null;
    let authResendRemaining = 0;
    let authMode = 'login';
    async function authRequest(path, options = {}) {
      try {
        const headers = { 'Content-Type': 'application/json', ...workspaceHeader(), ...(options.headers || {}) };
        const response = await fetch(path, { ...options, headers });
        const payload = await response.json().catch(() => ({}));
        return response.ok ? payload : { ...payload, error: payload.error || `HTTP ${response.status}` };
      } catch (error) {
        return { error: 'network_error', message: `无法连接本地服务：${error.message}` };
      }
    }
    function setAuthMessage(message = '', success = false) {
      const box = $('#authMessage');
      if (!box) return;
      box.textContent = message;
      box.classList.toggle('success', Boolean(success));
    }
    function applyAuthenticatedUser(user) {
authenticatedUser=user; applyIdentity();
    }
    function agreementAccepted(mode = authMode) {
      return Boolean(mode === 'register' ? $('#authRegisterAgreement')?.checked : $('#authLoginAgreement')?.checked);
    }
    function updateAuthAgreementState() {
      const loginAccepted = agreementAccepted('login');
      const registerAccepted = agreementAccepted('register');
      const loginButton = $('#authLoginBtn');
      const registerButton = $('#authRegisterBtn');
      const sendButton = $('#authRegisterSendBtn');
      if (loginButton && loginButton.textContent.trim() !== '正在登录…') loginButton.disabled = !loginAccepted;
      if (registerButton && registerButton.textContent.trim() !== '正在创建账号…') registerButton.disabled = !registerAccepted;
      if (sendButton && sendButton.textContent.trim() !== '发送中…') sendButton.disabled = !registerAccepted || authResendRemaining > 0;
    }
    function openLegalDocument(documentType = 'terms') {
      const modal = $('#legalModal');
      if (!modal) return;
      const selected = documentType === 'privacy' ? 'privacy' : 'terms';
      modal.hidden = false;
      $$('[data-legal-tab]').forEach(button => button.classList.toggle('active', button.dataset.legalTab === selected));
      $$('[data-legal-panel]').forEach(panel => { panel.hidden = panel.dataset.legalPanel !== selected; });
      const title = $('#legalTitle'); if (title) title.innerHTML = selected === 'privacy' ? '<span class="aurora-text">CanvasFlow</span> 隐私政策' : '<span class="aurora-text">CanvasFlow</span> 用户服务协议';
      setTimeout(() => $('#legalCloseBtn')?.focus?.(), 20);
    }
    function closeLegalDocument() { const modal = $('#legalModal'); if (modal) modal.hidden = true; }
    function bindLegalDocuments() {
      $$('[data-legal-doc]').forEach(button => button.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); openLegalDocument(button.dataset.legalDoc); }));
      $$('[data-legal-tab]').forEach(button => button.addEventListener('click', () => openLegalDocument(button.dataset.legalTab)));
      $('#legalCloseBtn')?.addEventListener('click', closeLegalDocument);
      $('#legalAcknowledgeBtn')?.addEventListener('click', closeLegalDocument);
      $('#legalModal')?.addEventListener('click', event => { if (event.target.id === 'legalModal') closeLegalDocument(); });
      // learn 落地页页脚的协议链接（/?legal=terms|privacy）→ 进入主应用后自动打开对应协议弹层。
      const legalParam = new URLSearchParams(location.search).get('legal');
      if (legalParam === 'terms' || legalParam === 'privacy') setTimeout(() => openLegalDocument(legalParam), 400);
    }
    function showAuthMode(mode = 'login', { message = '' } = {}) {
      authMode = mode === 'register' ? 'register' : 'login';
      const gate = $('#authGate'); if (gate) gate.hidden = false;
      $('#authLoading')?.setAttribute('hidden', '');
      $('#authTabs')?.removeAttribute('hidden');
      $('#authLoginForm')?.toggleAttribute('hidden', authMode !== 'login');
      $('#authRegisterForm')?.toggleAttribute('hidden', authMode !== 'register');
      $$('[data-auth-mode]').forEach(button => button.classList.toggle('active', button.dataset.authMode === authMode));
      const title = $('#authTitle');
      const description = $('#authDescription');
      // 品牌名使用 aurora 流光，需要内嵌 span（textContent 会冲掉标签）。
      if (title) title.innerHTML = authMode === 'login' ? '登录 <span class="aurora-text">CanvasFlow</span>' : '创建 <span class="aurora-text">CanvasFlow</span> 账号';
      if (description) description.textContent = authMode === 'login' ? '使用邮箱和密码登录，继续管理你的项目、素材与会员权益。' : '设置邮箱和密码，并通过邮箱验证码完成账号注册。';
      const savedEmail = identity.read().email || '';
      const field = authMode === 'login' ? $('#authLoginEmail') : $('#authRegisterEmail');
      if (field && savedEmail && !field.value) field.value = savedEmail;
      if (authMode === 'register') validateRegistrationEmail(false);
      setAuthMessage(message);
      updateAuthAgreementState();
      setTimeout(() => field?.focus?.(), 30);
    }
    function startRegistrationCountdown(seconds = 60) {
      clearInterval(authResendTimer);
      const button = $('#authRegisterSendBtn');
      authResendRemaining = seconds;
      const render = () => {
        if (!button) return;
        button.disabled = authResendRemaining > 0 || !agreementAccepted('register');
        button.textContent = authResendRemaining > 0 ? `${authResendRemaining} 秒` : '重新获取';
      };
      render();
      authResendTimer = setInterval(() => {
        authResendRemaining -= 1; render();
        if (authResendRemaining <= 0) { authResendRemaining = 0; clearInterval(authResendTimer); authResendTimer = null; updateAuthAgreementState(); }
      }, 1000);
    }
    function registrationEmailMessage(value) {
      const email = String(value || '').trim().toLowerCase();
      if (!email) return '请先输入注册邮箱';
      const parts = email.split('@');
      const local = parts[0];
      if (email.length > 254 || parts.length !== 2 || local.length > 64 || !/^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(local) || local.startsWith('.') || local.endsWith('.') || local.includes('..') || !/^[a-z0-9-]+(?:\.[a-z0-9-]+)+$/.test(parts[1])) return '邮箱格式不正确，请填写完整的 QQ 邮箱或 Gmail 地址';
      if (!['qq.com', 'gmail.com'].includes(parts[1])) return '仅支持 QQ 邮箱（@qq.com）和谷歌 Gmail（@gmail.com）注册，请检查邮箱后缀';
      return '';
    }
    function validateRegistrationEmail(showEmpty = false) {
      const input = $('#authRegisterEmail');
      if (!input) return false;
      const message = registrationEmailMessage(input.value);
      const show = Boolean(message && (showEmpty || input.value));
      input.setCustomValidity(message);
      input.setAttribute('aria-invalid', String(show));
      input.closest('.auth-field')?.classList.toggle('is-invalid', show);
      const error = $('#authRegisterEmailError');
      if (error) { error.textContent = message; error.hidden = !show; }
      return !message;
    }
    async function sendRegistrationCode() {
      const email = $('#authRegisterEmail')?.value?.trim().toLowerCase();
      if (!agreementAccepted('register')) return setAuthMessage('请先阅读并同意用户服务协议和隐私政策');
      if (!validateRegistrationEmail(true)) { $('#authRegisterEmail')?.focus(); return; }
      const button = $('#authRegisterSendBtn');
      if (button) { button.disabled = true; button.textContent = '发送中…'; }
      setAuthMessage('');
      const result = await authRequest('/api/auth/send-code', { method: 'POST', body: JSON.stringify({ email, agreementAccepted: true, agreementVersion: AGREEMENT_VERSION }) });
      if (!result?.sent) {
        if (button) { button.disabled = false; button.textContent = '获取验证码'; }
        if (result?.error === 'email_registered') showAuthMode('login', { message: result.message });
        else setAuthMessage(result?.message || '验证码发送失败，请稍后重试');
        return;
      }
      const dev = $('#authDevCode');
      if (dev) { dev.hidden = !result.devCode; dev.textContent = result.devCode ? `开发环境验证码：${result.devCode}` : ''; }
      const codeField = $('#authRegisterCode');
      if (codeField) codeField.value = result.devCode || '';
      startRegistrationCountdown(60);
      setAuthMessage(result.delivery === 'development' ? '本地开发模式：验证码已显示在上方。' : '注册验证码已发送，请检查收件箱和垃圾邮件。', true);
      codeField?.focus?.();
    }
    function bindEmailAuth() {
      const loginForm = $('#authLoginForm');
      if (!loginForm || loginForm.dataset.bound) return;
      loginForm.dataset.bound = '1';
      bindLegalDocuments();
      $('#authLoginAgreement')?.addEventListener('change', updateAuthAgreementState);
      $('#authRegisterAgreement')?.addEventListener('change', updateAuthAgreementState);
      $$('[data-auth-mode]').forEach(button => button.addEventListener('click', () => showAuthMode(button.dataset.authMode)));
      loginForm.addEventListener('submit', async event => {
        event.preventDefault();
        const email = $('#authLoginEmail')?.value?.trim().toLowerCase();
        const password = $('#authLoginPassword')?.value || '';
        if (!agreementAccepted('login')) return setAuthMessage('请先阅读并同意用户服务协议和隐私政策');
        if (!email || !password) return setAuthMessage('请输入邮箱和密码');
        const button = $('#authLoginBtn');
        if (button) { button.disabled = true; button.textContent = '正在登录…'; }
        const result = await authRequest('/api/auth/login', { method: 'POST', body: JSON.stringify({ email, password, agreementAccepted: true, agreementVersion: AGREEMENT_VERSION }) });
        if (button) { button.disabled = false; button.textContent = '登录'; }
        if (!result?.user) return setAuthMessage(result?.message || '登录失败');
        const sessionResult = await authRequest('/api/auth/me');
        if (!sessionResult?.user) return setAuthMessage(sessionResult?.message || '登录状态验证失败，请重新登录');
        {const url=new URL(location.href);url.searchParams.delete('project');history.replaceState(null,'',url);}
        applyAuthenticatedUser(sessionResult.user);
        // 项目/素材等数据接口要求登录态；登录前发起的加载已经 401，重载一次让画布拿到真实数据。
        location.reload();
      });
      const registerEmail = $('#authRegisterEmail');
      registerEmail?.addEventListener('input', () => validateRegistrationEmail(false));
      registerEmail?.addEventListener('blur', () => validateRegistrationEmail(false));
      registerEmail?.addEventListener('invalid', () => validateRegistrationEmail(true));
      validateRegistrationEmail(false);
      $('#authRegisterSendBtn')?.addEventListener('click', sendRegistrationCode);
      $('#authRegisterForm')?.addEventListener('submit', async event => {
        event.preventDefault();
        const email = $('#authRegisterEmail')?.value?.trim().toLowerCase();
        const password = $('#authRegisterPassword')?.value || '';
        const confirm = $('#authRegisterConfirm')?.value || '';
        const code = $('#authRegisterCode')?.value?.replace(/\D/g, '').slice(0, 6);
        if (!agreementAccepted('register')) return setAuthMessage('请先阅读并同意用户服务协议和隐私政策');
        if (!validateRegistrationEmail(true)) { $('#authRegisterEmail')?.focus(); return; }
        if (password.length < 8 || !/[A-Za-z]/.test(password) || !/\d/.test(password)) return setAuthMessage('密码至少 8 位，并且需要包含字母和数字');
        if (password !== confirm) return setAuthMessage('两次输入的密码不一致');
        if (code?.length !== 6) return setAuthMessage('请输入六位邮箱验证码');
        const button = $('#authRegisterBtn');
        if (button) { button.disabled = true; button.textContent = '正在创建账号…'; }
        const result = await authRequest('/api/auth/register', { method: 'POST', body: JSON.stringify({ email, password, code, agreementAccepted: true, agreementVersion: AGREEMENT_VERSION }) });
        if (button) { button.disabled = false; button.textContent = '创建账号'; }
        if (!result?.user) return setAuthMessage(result?.message || '注册失败');
        clearInterval(authResendTimer); authResendTimer = null;
        const sessionResult = await authRequest('/api/auth/me');
        {const url=new URL(location.href);url.searchParams.delete('project');history.replaceState(null,'',url);}
        applyAuthenticatedUser(sessionResult?.user || result.user);
        location.reload();
      });
      $('#authRegisterCode')?.addEventListener('input', event => { event.target.value = event.target.value.replace(/\D/g, '').slice(0, 6); });
    }
    // 落地门：未登录先看落地页，点「开始使用 / 打开画布」再进登录门。
    function showLandingGate() {
      const gate = $('#authGate'); if (gate) gate.hidden = true;
      const landing = $('#landingGate'); if (landing) landing.hidden = false;
    }
    function hideLandingGate() {
      const landing = $('#landingGate'); if (landing) landing.hidden = true;
    }
    function bindLandingGate() {
      const landing = $('#landingGate');
      if (!landing || landing.dataset.landingBound) return;
      landing.dataset.landingBound = '1';
      landing.addEventListener('click', event => {
        const action = event.target.closest('[data-landing-action]');
        if (!action) return;
        // 「了解 CanvasFlow」→ 跳本地托管的星河落地页（server.py 的 /learn/ 静态路由）。
        // ★ 不带 ?预览模板= 参数：皮肤由配置桩的 网站模板列表=[2] 驱动（带参 = 预览模式，
        //   会出橙色横幅且禁用全部交互，不适合给真实用户看）。
        if (action.dataset.landingAction === 'learn') {
          location.href = '/learn/';
          return;
        }
        hideLandingGate();
        showAuthMode('login');
      });
      // 黑白主题切换：只作用于登录前的落地页/登录门，选择持久化。
      const themeBtn = $('#landingThemeToggle');
      if (themeBtn && !themeBtn.dataset.themeBound) {
        themeBtn.dataset.themeBound = '1';
        themeBtn.addEventListener('click', () => {
          const light = document.documentElement.classList.toggle('light');
          try { localStorage.setItem('canvasflow-theme', light ? 'light' : 'dark'); } catch { /* private browsing */ }
        });
      }
    }


    function applyCanvasPrefsFromSettings(prefs) {
      const value = prefs || window.CanvasFlowSettings?.canvasPrefs?.() || {};
      const miniMap = $('.mini-map');
      if (miniMap) miniMap.hidden = value.miniMap === false;
      const grid = $('.canvas-grid');
      if (grid) grid.hidden = value.gridVisible === false;
      state.gridSnap = Boolean(value.gridSnap);
      const snapBtn = $('#toggleSnapBtn');
      snapBtn?.classList.toggle('active', state.gridSnap);
      snapBtn?.setAttribute('aria-pressed', String(state.gridSnap));
      state.smartGuides = Boolean(value.smartGuides);
      if (!state.smartGuides) window.CanvasFlowSettings?.clearGuides?.();
    }

    // 辅助线图层挂在画布舞台里，坐标即画布坐标；舞台被重建后自动补回。
    function ensureGuideLayer() {
      const stageEl = $('.canvas-stage');
      if (!stageEl) return null;
      let layer = stageEl.querySelector(':scope > .smart-guide-layer');
      if (!layer) {
        layer = document.createElement('div');
        layer.className = 'smart-guide-layer';
        stageEl.appendChild(layer);
      }
      return layer;
    }

    // 对齐参考：除自己以外的所有节点（多选中一起拖动的成员也不参与，否则会自己吸自己）。
    function collectAlignTargets(excludeNode) {
      const targets = [];
      $$('.flow-node').forEach(node => {
        if (node === excludeNode) return;
        if (state.multiSelection && state.multiSelection.size > 1 && state.multiSelection.has(node.dataset.nodeId)) return;
        targets.push({
          left: parseFloat(node.style.left) || 0,
          top: parseFloat(node.style.top) || 0,
          width: node.offsetWidth || NODE_SLOT_W,
          height: node.offsetHeight || NODE_SLOT_H,
        });
      });
      return targets;
    }

    // 工作区顶栏的深浅切换：与落地页共用同一个持久化偏好。
    function bindWorkspaceThemeToggle() {
      const btn = $('#themeToggleBtn');
      if (!btn || btn.dataset.themeBound) return;
      btn.dataset.themeBound = '1';
      btn.addEventListener('click', () => {
        const light = document.documentElement.classList.toggle('light');
        try { localStorage.setItem('canvasflow-theme', light ? 'light' : 'dark'); } catch { /* private browsing */ }
        showToast(light ? '已切换到浅色主题' : '已切换到深色主题', light ? '☀' : '☾');
      });
    }
    async function initializeEmailAuth() {
bindWorkspaceThemeToggle();
      const result = await authRequest('/api/local/bootstrap');
      if (!result?.context) { window.CanvasFlowStartup?.skip(); showToast('本地服务连接失败，请重新启动应用', '×'); return; }
      authenticatedUser = result.context;
      await syncWorkspacesFromServer();
      applyIdentity();
      if (new URLSearchParams(location.search).get('project')) loadProject();
      else beginDraftCanvas();
      if (!new URLSearchParams(location.search).get('project')) window.CanvasFlowStartup?.ready();
      announceWorkspaceSwitch();
    }
    // 切换工作区是整页重载完成的，提示信息靠 sessionStorage 带过来，重载后再弹。
    function announceWorkspaceSwitch() {
      let name = '';
      try {
        name = sessionStorage.getItem('canvasflow-workspace-switched') || '';
        if (name) sessionStorage.removeItem('canvasflow-workspace-switched');
      } catch { return; }
      if (name) setTimeout(() => showToast(`已切换到「${name}」，这是独立空间`, '✓'), 400);
    }

    const identity = {
      read() { try { return JSON.parse(localStorage.getItem('canvasflow-identity') || 'null') || {}; } catch { return {}; } },
      write(value) { try { localStorage.setItem('canvasflow-identity', JSON.stringify(value)); } catch { /* private browsing */ } },
    };
    function currentUser() {
return {id:'local-device', name:'本地工作台', avatar:'本', email:'', role:'admin', local:true};
    }

    const workspacesStorage = {
      get() { try { return JSON.parse(localStorage.getItem('canvasflow-workspaces') || 'null'); } catch { return null; } },
      set(value) { try { localStorage.setItem('canvasflow-workspaces', JSON.stringify(value)); } catch { /* private browsing */ } },
    };

    // 工作区之间是彼此独立的两个空间，所以「空间里的东西」必须跟着空间走。
    // 做法：切换时把下面这些键整体挪到 canvasflow-ws:<工作区id>:<键> 暂存，再把目标空间的挪回来。
    // 这样所有读写这些键的老代码一行都不用改，也不会出现「切过去还带着上个空间的收藏」。
    // 判据：**只有「这个空间里独有的东西」才进来**。
    //   - 不进来：canvasflow-characters（角色卡跨空间共用）、canvasflow-published-models（服务端
    //     模型列表的本地缓存）、canvasflow-agent-skill-fav / -recent（技能不隔离，收藏自然也不隔离）
    //     —— 这三样都是「跟着人走」的，隔离了会出现「切个空间模型/技能就没了」的假故障。
    const WORKSPACE_SCOPED_KEYS = [
      'canvasflow-project', 'canvasflow-projects',
      'canvasflow-asset-favorites', 'canvasflow-audio-voice-favorites',
      'canvasflow:camera-motion-favorites', 'canvasflow-connections',
    ];
    function workspaceScopedKeys() {
      const keys = new Set(WORKSPACE_SCOPED_KEYS);
      try {
        // 提示词预设是按 kind 分键的（canvasflow:prompt-presets:image 等），前缀扫一遍才不会漏。
        for (let index = 0; index < localStorage.length; index += 1) {
          const key = localStorage.key(index);
          if (key && key.startsWith('canvasflow:prompt-presets')) keys.add(key);
        }
      } catch { /* private browsing */ }
      return [...keys];
    }
    function stashWorkspaceLocalState(workspaceId) {
      if (!workspaceId) return;
      workspaceScopedKeys().forEach(key => {
        try {
          const value = localStorage.getItem(key);
          if (value === null) localStorage.removeItem(`canvasflow-ws:${workspaceId}:${key}`);
          else localStorage.setItem(`canvasflow-ws:${workspaceId}:${key}`, value);
        } catch { /* private browsing */ }
      });
    }
    function applyWorkspaceLocalState(workspaceId) {
      if (!workspaceId) return;
      workspaceScopedKeys().forEach(key => {
        try {
          const stashed = localStorage.getItem(`canvasflow-ws:${workspaceId}:${key}`);
          if (stashed === null) localStorage.removeItem(key);
          else localStorage.setItem(key, stashed);
        } catch { /* private browsing */ }
      });
    }
    function dropWorkspaceLocalState(workspaceId) {
      if (!workspaceId) return;
      try {
        const prefix = `canvasflow-ws:${workspaceId}:`;
        const doomed = [];
        for (let index = 0; index < localStorage.length; index += 1) {
          const key = localStorage.key(index);
          if (key && key.startsWith(prefix)) doomed.push(key);
        }
        doomed.forEach(key => localStorage.removeItem(key));
      } catch { /* private browsing */ }
    }
    function currentWorkspaceId() {
      return String(identity.read()?.workspaceId || '');
    }
    function readWorkspaces() {
      const saved = workspacesStorage.get();
      if (Array.isArray(saved) && saved.length) return saved;
      const oldIdentity = identity.read();
      const name = oldIdentity.workspace || '默认工作区';
      // 服务端还没应答时的本机兜底，真正的空间列表会被 syncWorkspacesFromServer() 覆盖。
      const seed = [{ id: 'workspace-personal', name, type: '本地空间', isDefault: true, createdAt: new Date().toISOString() }];
      workspacesStorage.set(seed);
      identity.write({ ...oldIdentity, workspaceId: seed[0].id, workspace: name });
      return seed;
    }
    function currentWorkspace() {
      const saved = identity.read();
      const list = readWorkspaces();
      return list.find(item => item.id === saved.workspaceId) || list[0];
    }
    async function syncWorkspacesFromServer() {
      const result = await api('/api/workspaces').catch(() => null);
      if (!Array.isArray(result?.workspaces) || !result.workspaces.length) return false;
      workspacesStorage.set(result.workspaces);
      const saved = identity.read();
      // 本机缓存里的 id 可能已经过期（换了账号、工作区被删），以服务端为准纠正，
      // 否则后续每个请求都会带着一个无效 id 打过去。
      if (!result.workspaces.some(item => item.id === saved.workspaceId)) {
        const fallback = result.workspaces.find(item => item.isDefault) || result.workspaces[0];
        identity.write({ ...saved, workspaceId: fallback.id, workspace: fallback.name });
      }
      return true;
    }
    function renderWorkspaceOptions() {
      const container = $('#workspaceOptions');
      if (!container) return;
      const active = currentWorkspace();
      container.innerHTML = `${readWorkspaces().map(workspace => {
        const isActive = workspace.id === active.id;
        const counts = workspace.counts || {};
        // 让每个空间一眼看出「里面有没有东西」，也顺便告诉用户旧内容落在哪。
        const summary = workspace.isDefault
          ? `默认工作区${counts.projects ? ` · ${counts.projects} 个项目` : ''}`
          : `${workspace.type || '本地空间'}${counts.projects ? ` · ${counts.projects} 个项目` : ' · 空空间'}`;
        // 默认工作区不给删除入口：升级前的老内容全在这里，删掉等于把它们藏起来。
        const remove = workspace.isDefault ? '' : `<span class="workspace-delete" data-delete-workspace="${escapeHtml(workspace.id)}" role="button" tabindex="0" aria-label="删除工作区 ${escapeHtml(workspace.name)}" title="删除工作区">×</span>`;
        return `<button class="workspace-option${isActive ? ' active' : ''}" data-workspace-id="${escapeHtml(workspace.id)}" type="button"><span class="workspace-avatar mini">${escapeHtml((workspace.name || '工').slice(0, 1))}</span><span class="workspace-option-copy"><strong>${escapeHtml(workspace.name)}</strong><small>${escapeHtml(summary)}${isActive ? ' · 当前' : ''}</small></span><span class="workspace-option-actions">${remove}<b>${isActive ? '✓' : '→'}</b></span></button>`;
      }).join('')}<button class="workspace-option workspace-create" data-workspace-action="create" type="button"><span class="workspace-avatar mini add">＋</span><span><strong>创建新工作区</strong><small>独立空间，内容互不相通</small></span><b>→</b></button>`;
    }
    function applyIdentity() {
const active=currentWorkspace();
      if(active){
        const label=$('#workspaceBtn strong');if(label)label.textContent=active.name;
        const sub=$('#workspaceBtn span:not(.chevron)');if(sub)sub.textContent='本地空间';
        const avatar=$('#workspaceBtn .workspace-avatar');if(avatar)avatar.textContent=(active.name||'本').slice(0,1);
        identity.write({...identity.read(),workspaceId:active.id,workspace:active.name});
      }
      renderWorkspaceOptions();
    }
    async function createWorkspace() {
      const next = await askText({ title: '创建新工作区', message: '新工作区是一个独立空间：项目、素材、技能都从空白开始，与其它工作区互不相通。', value: '', placeholder: '例如：品牌广告组' });
      if (!next) return;
      const result = await api('/api/workspaces', { method: 'POST', body: JSON.stringify({ name: next, type: '本地空间' }) });
      if (!result?.workspace) return showToast('工作区创建失败，请稍后重试', '×');
      const list = readWorkspaces().filter(item => item.id !== result.workspace.id);
      list.push(result.workspace);
      workspacesStorage.set(list);
      enterWorkspace(result.workspace);
    }
    async function renameWorkspace() {
      const active = currentWorkspace();
      if (!active) return;
      const next = await askText({ title: '重命名工作区', message: '名称只影响显示，不会移动空间里的任何内容。', value: active.name, placeholder: '例如：木木工作室' });
      if (!next || next === active.name) return;
      const result = await api(`/api/workspaces/${encodeURIComponent(active.id)}`, { method: 'PUT', body: JSON.stringify({ name: next }) }).catch(() => null);
      if (!result?.workspace) return showToast('重命名失败，请稍后重试', '×');
      workspacesStorage.set(readWorkspaces().map(item => item.id === active.id ? { ...item, name: next } : item));
      identity.write({ ...identity.read(), workspace: next });
      applyIdentity();
      showToast(`工作区已重命名为${next}`, '✎');
    }
    // 进入另一个工作区。两个空间的数据、收藏、画布都不同，而内存里的状态有二十来处，
    // 手工清理漏掉任何一处都会把上个空间的东西带过来 —— 所以这里直接重载页面，
    // 让所有状态从零按新空间重新拉取（这条以前踩过：清了界面没清状态，界面是新的但行为还是旧的）。
    function enterWorkspace(workspace) {
      if (!workspace?.id) return;
      stashWorkspaceLocalState(currentWorkspaceId());
      identity.write({ ...identity.read(), workspaceId: workspace.id, workspace: workspace.name });
      applyWorkspaceLocalState(workspace.id);
      try { sessionStorage.setItem('canvasflow-workspace-switched', workspace.name); } catch { /* private browsing */ }
      $('#workspacePopover')?.classList.remove('open');
      window.location.reload();
    }
    function switchWorkspace(workspaceId) {
      const workspace = readWorkspaces().find(item => item.id === workspaceId);
      if (!workspace) return;
      if (currentWorkspaceId() === workspaceId) {
        $('#workspacePopover')?.classList.remove('open');
        return showToast(`当前已是「${workspace.name}」`, '✓');
      }
      enterWorkspace(workspace);
    }

    async function deleteWorkspace(workspaceId) {
      const list = readWorkspaces();
      if (list.length <= 1) return showToast('至少需要保留一个工作区', '×');
      const workspace = list.find(item => item.id === workspaceId);
      if (!workspace) return;
      if (workspace.isDefault) return showToast('默认工作区不能删除', '×');
      const confirmed = await askConfirm({ title: '删除工作区', message: `确定删除「${workspace.name}」吗？空间里的项目和素材不会被删除，会回到你的默认工作区。`, confirmText: '删除', danger: true, icon: '⌫' });
      if (!confirmed) return;
      const result = await api(`/api/workspaces/${encodeURIComponent(workspaceId)}`, { method: 'DELETE' }).catch(() => null);
      if (!result?.deleted) return showToast('删除失败，请稍后重试', '×');
      const remaining = list.filter(item => item.id !== workspaceId);
      workspacesStorage.set(remaining);
      dropWorkspaceLocalState(workspaceId);
      $('#workspacePopover')?.classList.remove('open');
      if (currentWorkspaceId() === workspaceId) return enterWorkspace(remaining.find(item => item.isDefault) || remaining[0]);
      applyIdentity();
      showToast(`已删除工作区「${workspace.name}」，里面的内容已回到默认工作区`, '⌫');
    }

    // 工作区之间唯一的出口：把一个项目搬到另一个空间去。
    // 选择器复用 openDialog 的视觉结构（同一套 .modal-backdrop / .dialog-box），中间换成可点的空间列表。
    async function askWorkspaceTarget() {
      // 空间列表可能在别处变过（另一个标签页、刚通过接口建的），选择器必须拿最新的 ——
      // 否则会漏掉刚建好的目标空间，用户点了「移动」却发现无处可去。
      const remote = await api('/api/workspaces').catch(() => null);
      if (Array.isArray(remote?.workspaces) && remote.workspaces.length) workspacesStorage.set(remote.workspaces);
      const targets = readWorkspaces();
      const active = currentWorkspaceId();
      return new Promise(resolve => {
        const backdrop = document.createElement('div');
        backdrop.className = 'modal-backdrop app-dialog open';
        backdrop.dataset.dialogRoot = '1';
        const box = document.createElement('div');
        box.className = 'modal dialog-box';
        box.innerHTML = [
          '<button class="modal-close" type="button" data-workspace-pick="cancel">×</button>',
          '<div class="modal-icon">⇄</div>',
          '<h3>移动到工作区</h3>',
          '<p>项目会从当前空间移走，之后只出现在目标空间里。</p>',
          `<div class="workspace-pick-list">${targets.map(item => {
            const isActive = item.id === active;
            return `<button type="button" class="workspace-pick${isActive ? ' active' : ''}" data-workspace-pick="${escapeHtml(item.id)}"${isActive ? ' disabled' : ''}><span class="workspace-avatar mini">${escapeHtml((item.name || '工').slice(0, 1))}</span><span class="workspace-option-copy"><strong>${escapeHtml(item.name)}</strong><small>${isActive ? '当前工作区' : (item.type || '本地空间')}</small></span><b>${isActive ? '✓' : '→'}</b></button>`;
          }).join('')}</div>`,
          '<div class="dialog-actions"><button type="button" class="dialog-cancel" data-workspace-pick="cancel">取消</button></div>',
        ].join('');
        backdrop.appendChild(box);
        document.body.appendChild(backdrop);
        const finish = value => {
          document.removeEventListener('keydown', onKey, true);
          backdrop.remove();
          resolve(value);
        };
        function onKey(event) {
          if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); finish(''); }
        }
        document.addEventListener('keydown', onKey, true);
        backdrop.addEventListener('pointerdown', event => { if (event.target === backdrop) finish(''); });
        box.addEventListener('click', event => {
          const hit = event.target.closest('[data-workspace-pick]');
          if (!hit || hit.disabled) return;
          event.preventDefault();
          const value = String(hit.dataset.workspacePick || '');
          finish(value === 'cancel' ? '' : value);
        });
      });
    }

    async function moveProjectToWorkspace(projectId) {
      if (!projectId || projectId === 'new') return;
      if (readWorkspaces().length <= 1) return showToast('还没有其它工作区，先创建一个再移动', '×');
      const target = await askWorkspaceTarget();
      if (!target || target === currentWorkspaceId()) return;
      const card = $$('.project-card').find(item => item.dataset.projectId === projectId);
      const label = card?.querySelector('strong')?.textContent?.trim() || '这个项目';
      const result = await api(`/api/projects/${encodeURIComponent(projectId)}`, { method: 'PUT', body: JSON.stringify({ workspaceId: target }) }).catch(() => null);
      if (!result?.project) return showToast('移动失败，请稍后重试', '×');
      const workspace = readWorkspaces().find(item => item.id === target);
      removeLocalProject(projectId);
      // 项目已经不属于这个空间了：画布上如果正开着它，得先摘掉，
      // 否则后续每次自动保存都会撞上「该项目属于另一个工作区」。
      if (state.projectId === projectId) clearCurrentProject();
      showToast(`「${label}」已移动到「${workspace?.name || '另一个工作区'}」`, '⇄');
      const refreshed = await api('/api/projects');
      renderProjects(refreshed?.projects || readLocalProjects());
      refreshProjectBadge();
    }

    // ===== r886：社交关系（关注 / 粉丝 / 获赞 / 作品）=====
    // ★★★ 真源 = **服务端**。用户需求：「我用当前账号关注别人，应该我的账号信息这边显示，
    //   并且应该是可以点进去查看关注了哪些人的……获赞和作品这些数量都需要有统计，并且同步，
    //   获赞的话应该是社区分享里，分享的任何东西都要加入点赞功能。」
    //   r884 那版把关注状态放在 localStorage —— 结果：对方粉丝数永远是 0、列不出「我关注了谁」、
    //   点赞更无从统计。所以整块换成服务端 API（`/api/social`、`/api/follows`、`/api/likes`）。
    //   localStorage 在这里只做**同步渲染缓存**：进页面要立刻画出 4 个数字，不能等网络。
    const SOCIAL_CACHE_KEY = 'canvasflow-social';
    function readSocialCache() {
      try {
        const saved = JSON.parse(localStorage.getItem(`${SOCIAL_CACHE_KEY}:${currentUser().id}`) || 'null');
        return saved && typeof saved === 'object' ? saved : null;
      } catch { return null; }
    }
    function writeSocialCache(value) {
      try { localStorage.setItem(`${SOCIAL_CACHE_KEY}:${currentUser().id}`, JSON.stringify(value)); } catch { /* 隐私模式：只在本次会话有效 */ }
    }
    state.social = state.social || readSocialCache();
    function socialStats() {
      const stats = state.social?.stats;
      return { works: Number(stats?.portfolioWorks ?? stats?.works) || 0, likes: Number(stats?.likes) || 0,
               following: Number(stats?.following) || 0, followers: Number(stats?.followers) || 0 };
    }
    async function loadSocial() {
      if (isStandaloneFile()) return state.social;
      const accountId = currentUser().id;
      const result = await api('/api/social');
      if (currentUser().id !== accountId) return state.social;
      if (result && result.stats) { state.social = result; writeSocialCache(result); }
      return state.social;
    }
    function isFollowingCreator(profileId) {
      return Boolean(profileId && (state.social?.following || []).some(person => person?.id === profileId));
    }
    /** 关注按钮的外观只在这里改 —— 避免「文案换了、状态类没换」这种半更新。 */
    function paintFollowButton(btn, following) {
      if (!btn) return;
      btn.classList.toggle('is-following', Boolean(following));
      btn.setAttribute('aria-pressed', following ? 'true' : 'false');
      btn.setAttribute('title', following ? '点击取消关注' : '关注这位创作者');
      btn.textContent = following ? '✓ 已关注' : '＋ 关注';
    }
    /** 只更新顶部那排数字，**不重绘整页** —— 重绘会把用户正在看的页签重置回默认。 */
    function paintProfileStatsBar() {
      const stats = socialStats();
      $$('.profile-center-stats [data-stat]').forEach(el => {
        const strong = el.querySelector('strong');
        if (strong && el.dataset.stat in stats) strong.textContent = String(stats[el.dataset.stat]);
      });
    }
    async function toggleFollowCreator(btn) {
      const view = btn?.closest('.public-profile-view');
      const profileId = view?.dataset.publicProfileId;
      if (!profileId) return;
      const nowFollowing = !btn.classList.contains('is-following');
      const name = view.querySelector('.public-profile-head h1')?.textContent?.trim() || '这位创作者';
      btn.disabled = true;
      const result = nowFollowing
        ? await api('/api/follows', { method: 'POST', body: JSON.stringify({ userId: profileId }) })
        : await api(`/api/follows/${encodeURIComponent(profileId)}`, { method: 'DELETE' });
      btn.disabled = false;
      if (!result || result.error) return showToast(result?.message || '操作失败，请确认本地服务已启动', '×');
      paintFollowButton(btn, Boolean(result.following));
      // ★ 用户要的「我的账号信息这边显示」：我的「关注」立刻 +1 / −1，并落进缓存
      const current = state.social || { stats: {}, following: [], followers: [], likes: [] };
      const rest = (current.following || []).filter(person => person?.id !== profileId);
      state.social = { ...current, stats: result.stats || socialStats(),
                       following: result.following ? [result.target || { id: profileId }, ...rest] : rest };
      writeSocialCache(state.social);
      paintProfileStatsBar();
      // 对方主页的「粉丝」用**服务端真值**回填（不再是「基线 + 我这一票」的假算法）
      const counter = view.querySelector('[data-profile-followers]');
      if (counter && result.targetStats) counter.textContent = String(Number(result.targetStats.followers) || 0);
      showToast(result.following ? `已关注「${name}」，可在个人中心查看关注列表` : `已取消关注「${name}」`,
                result.following ? '✓' : '·');
    }
    // ---- 点赞（社区分享里**每一张内容卡**上都有）----
    function likeButtonMarkup(kind, item, extraClass = '') {
      const liked = Boolean(item?.liked);
      const count = Number(item?.likeCount) || 0;
      return `<button class="community-like${liked ? ' is-liked' : ''}${extraClass ? ` ${extraClass}` : ''}" data-like-kind="${escapeHtml(kind)}" data-like-id="${escapeHtml(String(item?.id || ''))}" type="button" aria-pressed="${liked ? 'true' : 'false'}" title="${liked ? '取消点赞' : '点赞'}"><span class="like-heart" aria-hidden="true">${liked ? '♥' : '♡'}</span><b data-like-count>${count}</b></button>`;
    }
    function paintLikeButton(btn, liked, count) {
      if (!btn) return;
      btn.classList.toggle('is-liked', Boolean(liked));
      btn.setAttribute('aria-pressed', liked ? 'true' : 'false');
      btn.setAttribute('title', liked ? '取消点赞' : '点赞');
      const heart = btn.querySelector('.like-heart');
      if (heart) heart.textContent = liked ? '♥' : '♡';
      const label = btn.querySelector('[data-like-count]');
      if (label && count !== undefined && count !== null) label.textContent = String(Number(count) || 0);
    }
    /** 本地缓存里同步「我点过的赞」，这样切走再回来按钮状态还是对的。 */
    function syncLikedCache(kind, id, liked) {
      const current = state.social || { stats: {}, following: [], followers: [], likes: [] };
      const key = `${kind}:${id}`;
      const list = (current.likes || []).filter(pair => `${pair?.[0]}:${pair?.[1]}` !== key);
      if (liked) list.push([kind, id]);
      state.social = { ...current, likes: list };
      writeSocialCache(state.social);
    }
    const communityLikeRequests=new Set();
    async function setCommunityLike(kind,id,liked) {
      const account=currentUser().id,key=account+':'+kind+':'+id;
      if(communityLikeRequests.has(key))return null;
      communityLikeRequests.add(key);
      try{
        const result=liked?await api('/api/likes',{method:'POST',throwOnError:true,body:JSON.stringify({kind,id})}):await api(`/api/likes/${encodeURIComponent(kind)}/${encodeURIComponent(id)}`,{method:'DELETE',throwOnError:true});
        if(account!==currentUser().id)return null;
        for(const button of document.querySelectorAll('[data-like-kind]'))if(button.dataset.likeKind===kind&&button.dataset.likeId===id)paintLikeButton(button,!!result.liked,result.likeCount);
        for(const list of Object.values(state.communityData||{}))if(Array.isArray(list))for(const item of list)if(item.id===id){item.liked=!!result.liked;item.likeCount=result.likeCount;}
        for(const item of state.musicTracks||[])if(kind==='music'&&item.id===id){item.liked=!!result.liked;item.likeCount=result.likeCount;}
        syncLikedCache(kind,id,!!result.liked);
        await loadFavoriteItems();renderLibrary();renderLibraryManager();
        if($('.profile-center-tab[data-profile-tab="favorites"]')?.classList.contains('active'))renderFavoritesInto($('#profileCenterBody'),state.favoriteItems||[]);
        if(result.ownerId===account)loadSocial().then(paintProfileStatsBar);
        return result;
      }finally{communityLikeRequests.delete(key);}
    }
    async function toggleLike(btn) {
      const kind=btn.dataset.likeKind,id=btn.dataset.likeId;
      if(!kind||!id||btn.disabled)return;
      btn.disabled=true;
      try{const result=await setCommunityLike(kind,id,!btn.classList.contains('is-liked'));if(result)showToast(result.liked?'已点赞并收藏':'已取消点赞',result.liked?'♥':'·');}
      catch(error){showToast(error.message||'点赞失败，请重试','×');}
      finally{btn.disabled=false;}
    }

    // ---- 「关注 / 粉丝」名单弹层（用户要的「可以点进去查看关注了哪些人」）----
    function closeSocialList() { $('#socialListLayer')?.remove(); }
    function openSocialList(kind) {
      const isFollowing = kind === 'following';
      const people = (isFollowing ? state.social?.following : state.social?.followers) || [];
      closeSocialList();
      const layer = document.createElement('div');
      layer.className = 'social-list-layer';
      layer.id = 'socialListLayer';
      layer.innerHTML = `<div class="social-list-backdrop" data-social-close></div><div class="social-list-card" role="dialog" aria-modal="true" aria-label="${isFollowing ? '我关注的人' : '关注我的人'}"><div class="social-list-head"><div><span class="eyebrow">${isFollowing ? 'FOLLOWING' : 'FOLLOWERS'}</span><h3>${isFollowing ? '我关注的人' : '关注我的人'}</h3></div><button class="social-list-close" data-social-close type="button" aria-label="关闭">×</button></div><div class="social-list-body">${people.length ? people.map(person => `<button class="social-person" data-profile-id="${escapeHtml(person.id)}" type="button"><span class="social-person-avatar">${escapeHtml(person.avatar || String(person.name || '创').slice(0, 1))}</span><span class="social-person-name">${escapeHtml(person.name || '创作者')}</span><span class="social-person-go">查看主页 →</span></button>`).join('') : `<div class="social-list-empty">${isFollowing ? '还没有关注任何人。在社区里点创作者名字或「＋ 关注」就能关注。' : '还没有人关注你。把作品分享到社区，会更容易被看到。'}</div>`}</div></div>`;
      document.body.appendChild(layer);
      layer.addEventListener('click', event => {
        if (event.target.closest('[data-social-close]')) return closeSocialList();
        const person = event.target.closest('[data-profile-id]');
        if (person) { closeSocialList(); openPublicProfile(person.dataset.profileId); }
      });
    }
    // ---- ★ r887 追加：「收藏」= 我在社区里点过赞的内容 ----
    // 用户需求：「我点赞他人分享的作品，个人中心的收藏也要同步。」
    // ★★★ 真源只有一个 = `likes` 表。前端**不另存一份收藏表** —— 否则点赞与收藏必然对不上。
    //   所以「收藏」页签 = `/api/social` 的 `likes` 列表 × `/api/community` 的内容明细；
    //   取消点赞即取消收藏（两处永远一致）。
    const FAVORITE_KIND_META = {
      project: { key: 'projects', tag: '项目分享', icon: '✦' },
      music:   { key: 'music',    tag: '音乐分享', icon: '♫' },
      asset:   { key: 'assets',   tag: '素材分享', icon: '▧' },
      model:   { key: 'models',   tag: '模型分享', icon: '◎' },
    };
    function favoriteItemName(kind, item) {
      if (kind === 'project') return item.projectName || item.name || '未命名项目';
      return item.name || '未命名内容';
    }
    function favoriteItemMeta(kind, item) {
      if (kind === 'project') return `${Number(item.nodeCount) || 0} 个节点`;
      if (kind === 'music') return `音乐分享 · ${item.duration || '音频'}`;
      if (kind === 'asset') return `${item.kind === 'video' ? '视频' : '图片'} · ${item.size || '—'}`;
      return `模型分享 · ${Number(item.uses) || 0} 次使用`;
    }
    /** 收藏卡上的「去看看」按钮 —— 复用社区那套 data-* 动作，不新造入口。
     *  ★ 必须带 `public-work-action` 类：全局 reset 只清了 `border` / `appearance`，
     *    UA 默认的「白底黑字」会直接露出来（`.public-work-card>button` 那条管不到
     *    套在 `.public-work-actions` 里的按钮）。 */
    function favoriteActionButton(kind, item) {
      const id = escapeHtml(String(item.id || ''));
      const cls = 'public-work-action';
      if (kind === 'project') return `<button class="${cls}" data-community-open-project="${id}" type="button">打开项目 →</button>`;
      if (kind === 'music') return `<button class="${cls}" data-community-preview-music="${id}" type="button">查看详情 →</button>`;
      if (kind === 'asset') return `<button class="${cls}" data-community-open-asset="${id}" type="button">放大查看 →</button>`;
      return `<button class="${cls}" data-community-preview-model="${id}" type="button">查看详情 →</button>`;
    }
    function renderFavoritesInto(body, favorites) {
      if (!body) return;
      const heading = `<div class="profile-section-heading"><div><span class="eyebrow">FAVORITES</span><h2>收藏</h2><p>你在社区中点赞或收藏的图片、视频、音乐和模型都显示在这里。</p></div></div>`;
      if (!favorites.length) {
        body.innerHTML = `${heading}<div class="profile-empty-card compact"><div class="profile-empty-icon">♡</div><h3>还没有收藏内容</h3><p>去「社区分享」里点赞或收藏喜欢的内容，它就会出现在这里。</p></div>`;
        return;
      }
      const cards = favorites.map(({ kind, item }, index) => {
        const meta = FAVORITE_KIND_META[kind];
        return `<article class="public-work-card profile-favorite-card" data-favorite-kind="${escapeHtml(kind)}" data-favorite-id="${escapeHtml(String(item.id || ''))}"><div class="community-cover community-cover-${index % 5}">${item.thumbnail||item.cover||(kind==='asset'&&item.kind==='image'&&item.mediaUrl)?`<img src="${escapeHtml(item.thumbnail||item.cover||item.mediaUrl)}" alt="${escapeHtml(favoriteItemName(kind,item))}">`:`<span>${meta.icon}</span>`}<span class="profile-favorite-tag">${meta.tag}</span></div><strong>${escapeHtml(favoriteItemName(kind, item))}</strong><small>${escapeHtml(favoriteItemMeta(kind, item))} · 来自 ${escapeHtml(item.ownerName || 'CanvasFlow 社区')}</small><div class="public-work-actions">${likeButtonMarkup(kind, item)}${kind==='model'?modelFavoriteButton(item):''}${favoriteActionButton(kind, item)}</div></article>`;
      }).join('');
      body.innerHTML = `${heading}<div class="public-profile-grid profile-favorite-grid">${cards}</div>`;
    }
    /** 拉服务端真值并渲染「收藏」页签。 */
    async function loadFavorites() {
      const body=$('#profileCenterBody');if(!body)return;
      try{
        const favorites=await loadFavoriteItems();
        if(!$('.profile-center-tab[data-profile-tab="favorites"]')?.classList.contains('active'))return;
        renderFavoritesInto(body,favorites);
      }catch(error){if(body.isConnected)body.innerHTML=`<p class="loading-state">${escapeHtml(error.message||'收藏加载失败')}</p>`;}
    }

    function profileCenterData() {
      const saved = identity.read();
      return {
        name: saved.account || $('#profileBtn strong')?.textContent?.trim() || '林默',
        avatar: (saved.account || $('#profileBtn strong')?.textContent?.trim() || '林默').slice(0, 1),
        plan: '积分制账户',
        bio: saved.bio || '用镜头记录灵感，把想法变成作品。',
        // ★ r886：四项统计一律走服务端（`state.social`），不再读 localStorage 里的死数字。
        stats: socialStats(),
      };
    }
    // Published models now live on the server (models.json) so the community "模型分享" tab and the
    // personal center stay in sync. localStorage is only a synchronous render cache; legacy
    // cache-only entries (ids "published-*") are migrated to the server on the first refresh.
    function readPublishedModels() {
      try {
        const saved = JSON.parse(localStorage.getItem('canvasflow-published-models') || '[]');
        return Array.isArray(saved) ? saved : [];
      } catch { return []; }
    }
    function writePublishedModels(models) {
      try { localStorage.setItem('canvasflow-published-models', JSON.stringify(models)); } catch { /* private browsing */ }
    }
    /**
     * ★★★ r889（用户需求：「这个应该是分享内容和社区分享里我的分享同步内容」）：
     *   「已发布模型」**只能列我自己的**。
     *   以前这里直接摊开 `/api/models` 的全部内容 —— 而 `/api/models` 是**全站**模型表
     *   （含演示数据 `user-canvasflow` / `user-mori` 的），于是别人的模型被当成"我发布的"显示；
     *   社区「我的分享」却是按 `ownerId === 我` 过滤的 → 两个入口对不上。
     *   现在两边同一个口径：`ownerId === currentUser().id`。
     *   ★ 注意：`readPublishedModels()` 这个缓存里**仍然存全量**（社区离线兜底要用全量），
     *     只在「已发布模型」这个入口过滤。
     */
    function myPublishedModels() {
      const me = currentUser();
      return readPublishedModels().filter(model => model?.ownerId === me.id);
    }
    function updateModelShareCount(count = myPublishedModels().length) {
      const badge = $('#modelShareCount');
      if (badge) badge.textContent = String(Math.max(0, Number(count) || 0));
    }
    async function refreshPublishedModels() {

    }
    function publishModel() { return openCommunityEditor('models'); }

    async function openPublicProfile(profileId) {
      if (!profileId) return;
      closeCommunityPreview();
      const epoch = ++navigationEpoch;
      const result = await api(`/api/profiles/${encodeURIComponent(profileId)}`);
      if (epoch !== navigationEpoch) return;
      const profile = result?.profile || { id: profileId, name: '创作者', avatar: '创', bio: '在 CanvasFlow 分享创作灵感。', stats: { works: 0, music: 0, likes: 0 } };
      const [fetchedCommunity, fetchedAssets] = await Promise.all([
        api('/api/community'), api('/api/assets?scope=community'),
      ]);
      if (epoch !== navigationEpoch) return;
      const community = fetchedCommunity && (Array.isArray(fetchedCommunity.projects) || Array.isArray(fetchedCommunity.music)) ? fetchedCommunity : (state.communityData || {});
      if (fetchedCommunity) state.communityData = community;
      const projects = (community.projects || []).filter(item => item.ownerId === profileId);
      const music = (community.music || []).filter(item => item.ownerId === profileId);
      const models = (community.models || readPublishedModels()).filter(item => item.ownerId === profileId);
      // ★ r884：「关注」按钮的初始态（已关注则直接显示 ✓ 已关注），以及关注者计数的基线。
      // ★ r886：关注态与四项统计一律取服务端真值（`profile.following` / `profile.stats`）。
      const isFollowing = Boolean(profile.following) || isFollowingCreator(profileId);
      const stats = profile.stats || {};
      const followers = Number(stats.followers) || 0;
      const view = $('#contentView'); if (!view) return;
      view.innerHTML = `<div class="public-profile-view" data-public-profile-id="${escapeHtml(profileId)}"><button class="back-to-community" data-view-action="community" type="button">← 返回社区分享</button><div class="public-profile-head"><div class="public-profile-avatar">${escapeHtml(profile.avatar || profile.name.slice(0, 1))}</div><div><span class="eyebrow">CREATOR PROFILE</span><h1>${escapeHtml(profile.name)}</h1><p>${escapeHtml(profile.bio || '在 CanvasFlow 分享创作灵感。')}</p></div><button class="view-action${isFollowing ? ' is-following' : ''}" data-profile-action="follow" type="button" aria-pressed="${isFollowing ? 'true' : 'false'}" title="${isFollowing ? '点击取消关注' : '关注这位创作者'}">${isFollowing ? '✓ 已关注' : '＋ 关注'}</button></div><div class="public-profile-stats"><div><strong>${Number(stats.works) || 0}</strong><span>作品</span></div><div><strong>${Number(stats.likes) || 0}</strong><span>获赞</span></div><div><strong>${Number(stats.following) || 0}</strong><span>关注</span></div><div><strong data-profile-followers>${followers}</strong><span>粉丝</span></div></div><div class="public-profile-section"><div class="profile-section-heading"><div><span class="eyebrow">SHARED WORKS</span><h2>${escapeHtml(profile.name)} 的分享</h2></div></div><div class="public-profile-grid">${projects.map((project, index) => `<article class="public-work-card"><div class="community-cover community-cover-${index % 5}"><span>✦</span></div><strong>${escapeHtml(project.projectName || '未命名项目')}</strong><small>${Number(project.nodeCount) || 0} 个节点 · ${escapeHtml(formatUpdatedAt(project.updatedAt))}</small><div class="public-work-actions"><button class="community-preview-button" type="button" data-community-preview-project="${escapeHtml(project.id)}">查看详情 →</button>${likeButtonMarkup('project', project)}<button class="public-work-action" data-community-open-project="${escapeHtml(project.id)}" type="button">打开项目 →</button></div></article>`).join('')}${music.map((track, index) => `<article class="public-work-card"><div class="community-music-cover music-cover-${index % 4}"><span>♫</span></div><strong>${escapeHtml(track.name || '未命名音乐')}</strong><small>音乐分享 · ${escapeHtml(track.duration || '—')}</small><div class="public-work-actions"><button class="community-preview-button" type="button" data-community-preview-music="${escapeHtml(track.id)}">查看详情 →</button>${likeButtonMarkup('music', track)}</div></article>`).join('')}${models.map((model, index) => `<article class="public-work-card"><div class="community-cover community-cover-${(index + 2) % 5}">${model.thumbnail?`<img src="${escapeHtml(model.thumbnail)}" alt="${escapeHtml(model.name)}">`:'<span>◎</span>'}</div><strong>${escapeHtml(model.name || '未命名模型')}</strong><small>模型分享 · ${Number(model.uses) || 0} 次使用</small><div class="public-work-actions"><button class="community-preview-button" type="button" data-community-preview-model="${escapeHtml(model.id)}">查看详情 →</button>${likeButtonMarkup('model', model)}${modelFavoriteButton(model)}</div></article>`).join('') || '<div class="public-profile-empty">这个创作者还没有公开分享内容。</div>'}</div></div></div>`;
      const assets = (fetchedAssets?.assets || []).filter(item => item.ownerId === profileId && item.shared !== false);
      if (assets.length) {
        view.querySelector('.public-profile-empty')?.remove();
        view.querySelector('.public-profile-grid')?.insertAdjacentHTML('beforeend', communityCardsFor({assets}).html);
      }
      const portfolio = document.createElement('section');
      portfolio.className = 'public-profile-portfolio';
      view.querySelector('.public-profile-view')?.append(portfolio);
      window.CanvasFlowPortfolio?.mount(portfolio, {ownerId:profileId});
      $('#canvasWrap')?.classList.add('view-hidden'); $('.composer-bar')?.classList.add('view-hidden'); inspector.classList.add('view-hidden'); setHeaderContext(false); setActiveNav('');
    }

    /**
     * 「分享的内容」页（r891，用户需求）。
     *
     * 用户原话：「这个已发布模型不应该叫已发布模型，应该叫分享的内容，
     *   社区分享里我的分享里的内容在这里也要显示」。
     * → 与社区「我的分享」**同真源、同卡片**：
     *   数据 = `/api/community`（项目 / 音乐 / 模型）+ `/api/assets?scope=community`（图片 / 视频）；
     *   卡片 = `communityCardsFor(data, 'mine')` —— 与社区页**同一份实现**，杜绝两处漂移。
     * ★ 不再用 `myPublishedModels()`（那只有模型）：模型也改由社区真源提供，两个入口口径一致。
     * ★ 不再自己写删除逻辑：卡片上的「删除分享 / 取消分享」走社区的 `[data-community-delete]`
     *   → `deleteCommunityShare()`，与社区页完全同一条链路（原先那条「只删模型」的旧实现已删）。
     */
    async function loadMyShares() {
      const [community, assets] = await Promise.all([
        api('/api/community').catch(() => null),
        api('/api/assets?scope=community').catch(() => null),
      ]);
      return {
        projects: Array.isArray(community?.projects) ? community.projects : [],
        music: Array.isArray(community?.music) ? community.music : [],
        models: Array.isArray(community?.models) ? community.models : [],
        assets: (assets?.assets || []).filter(item => item.shared !== false),
        templates: [],
      };
    }

    /** 画「分享的内容」：先出同步占位，拿到服务端真值后重画（与「我的账户 / 我的素材」同套路）。 */
    function renderProfileShares(body) {
      const stillMine = () => $('#profileCenterBody') === body
        && $('.profile-center-tab[data-profile-tab="shares"]')?.classList.contains('active');
      const paint = data => {
        if (!stillMine()) return;
        const { html, counts } = communityCardsFor(data, 'mine');
        const total = counts.projects + counts.images + counts.videos + counts.music + counts.models;
        const chips = [['项目', counts.projects], ['图片', counts.images], ['视频', counts.videos], ['音乐', counts.music], ['模型', counts.models]]
          .filter(([, count]) => count > 0)
          .map(([label, count]) => `<span class="profile-share-count">${label} <b>${count}</b></span>`).join('');
        const actions = communityShareActions.filter(item => item.kind !== 'mine' && item.kind !== 'templates');
        const actionButtons = actions.map(item => `<button class="community-share-action" data-community-action="${item.kind}" type="button"><span>${item.icon}</span><span><strong>${item.title}</strong><small>${item.detail}</small></span></button>`).join('');
        body.innerHTML = `<div class="profile-section-heading"><div><span class="eyebrow">MY SHARES</span><h2>分享的内容</h2><p>你分享到社区的项目、图片、视频、音乐和模型都会显示在这里；在这里删除也会同步从社区移除。</p></div></div><div class="profile-share-actions">${actionButtons}</div>${total ? `<div class="profile-share-summary">共 ${total} 项${chips}</div><div class="community-grid">${html}</div>` : `<div class="profile-empty-card"><div class="profile-empty-icon">◈</div><h3>还没有分享内容</h3><p>在社区里分享项目、图片、视频、音乐或模型，都会同步出现在这里。</p><button class="profile-empty-primary" data-community-action="projects" type="button">分享当前项目</button></div>`}</div>`;
      };
      body.innerHTML = `<div class="profile-section-heading"><div><span class="eyebrow">MY SHARES</span><h2>分享的内容</h2><p>正在从社区同步你分享的内容…</p></div></div><div class="profile-empty-card compact"><div class="profile-empty-icon">◈</div><h3>正在同步…</h3><p>数据与「社区分享 → 我的分享」同源。</p></div>`;
      loadMyShares().then(paint).catch(() => paint({}));
    }

    function renderProfileCenter(activeTab = 'shares', { refreshModels = true } = {}) {

    }
    // 充值档位。★ r880：计费口径 = **1 积分 = 1 元人民币**（价格与积分数额恒等）。
    // ★ 固定档位与自定义金额共用 `rechargeCredits()`，不存在"同一个包两个价"。
    const CREDIT_PACKAGES = [
      { amount: 10, price: 10, note: '入门包' },
      { amount: 50, price: 50, note: '常用', popular: true },
      { amount: 100, price: 100, note: '最划算' },
    ];
    // 自定义充值金额区间（元 = 积分），与服务端 `/api/credits/recharge` 的 1..100000 对齐
    const CREDIT_CUSTOM_MIN = 1;
    const CREDIT_CUSTOM_MAX = 100000;
    // ★ 订阅套餐（r908）：数据源 = 管理后台维护的 `server-data/subscription-plans.json`
    //   （GET /api/subscription-plans 拉取；管理后台增删改后这里同步刷新）。
    //   拉取失败 / 还没拉到时回退到这份默认值，保证弹窗永远有内容。
    const SUBSCRIPTION_PLANS = [
      {
        id: 'free', note: '免费版', price: 0,
        features: ['注册赠 500 积分', '基础视频模型', '标准清晰度导出', '社区分享与素材库'],
      },
      {
        id: 'pro', note: '专业版', price: 39, popular: true,
        features: ['每月发放 600 积分', '全部视频模型', '高清无水印导出', '生成优先队列'],
      },
      {
        id: 'max', note: '旗舰版', price: 99,
        features: ['每月发放 1800 积分', '含专业版全部权益', '4K 导出与批量生成', '专属客服支持'],
      },
    ];
    let subscriptionPlansCache = null;   // 服务端套餐缓存；[] = 服务端就是空（合法状态），null = 还没拉到
    function subscriptionPlansData() {
      // ★ 服务端拉到过就**用服务端的，空表也不回退** —— 管理后台把套餐删光后，
      //   这里若回退到内置默认，订阅弹窗就会永远显示三个写死的套餐（看起来就是「不同步」）。
      //   只有「还没拉到过」（null：未登录 / 离线）才用内置默认兜底渲染。
      if (Array.isArray(subscriptionPlansCache)) return subscriptionPlansCache;
      return SUBSCRIPTION_PLANS;
    }
    function loadSubscriptionPlans() {
      return authRequest('/api/subscription-plans').then(result => {
        // 空列表也要写进缓存：那是管理后台删光套餐后的真实状态，不能当作「没拉到」。
        if (Array.isArray(result?.plans)) subscriptionPlansCache = result.plans;
        return subscriptionPlansData();
      }).catch(() => subscriptionPlansData());
    }
    function creditPriceLabel(price) {
      const value = Number(price) || 0;
      return `¥${value % 1 === 0 ? value : value.toFixed(1)}`;
    }
    /**
     * 拉「我的账户」的真值（余额 + 积分流水）。
     *
     * ★★★ 真源是服务端 `/api/credits`，**不是** `identity.bonusCredits` ——
     *   本地那个只是**同步渲染缓存**（画布上的额度提示不能等网络）。进账户页必须重新拉，
     *   否则管理员在后台调过余额之后，这里会一直显示旧值。
     * ★ 顺手把本地缓存对齐服务端，让画布额度提示与账户页不打架。
     */
    async function loadCreditsLedger() {
      const result = await api('/api/credits').catch(() => null);
      const credits = result?.credits;
      if (!credits) return null;
      state.credits = credits;
      const balance = Number(credits.creditBalance);
      if (Number.isFinite(balance)) {
        const saved = identity.read();
        if (Number(saved.bonusCredits) !== balance) identity.write({ ...saved, bonusCredits: balance });
        if (authenticatedUser) authenticatedUser.creditBalance = balance;
      }
      return credits;
    }
    /** 「我的账户」页：余额卡 + 充值入口（固定档位 + 自定义金额）+ 积分流水。 */
    // 「积分流水」里的生成类条目（r884）—— 服务端把 tokens / 预扣 / 实际 都写进了 `meta`。
    // ★★★ 用户需求原文：「按 token 计费要能**准确扣费**，并且能和上游同步 token 数」——
    //   那就必须让用户在流水里**看得见上游回来的 token 数**，否则「准确」只是一句无法核对的话。
    const LEDGER_KIND_LABEL = { precharge: '预扣', settle: '结算', charge: '扣费' };

    function creditMoney(value) { return (Number(value) || 0).toFixed(2); }

    function formatTokens(value) {
      return Number(value || 0).toLocaleString('zh-CN');
    }

    /** 调用时间要能**对账** → 用绝对时间（本地时区），不用「3 分钟前」。
     *  ★ 服务端 `created_at` 是带时区的 UTC ISO（`auth_iso()`），`Date.parse` 能吃，
     *    `getFullYear/getHours` 出来就是用户本地的墙上时间。 */
    function formatLedgerTime(value) {
      const raw = String(value ?? '').trim();
      if (!raw) return '';
      const stamp = Date.parse(raw);
      if (Number.isNaN(stamp)) return raw;
      const date = new Date(stamp);
      const pad = number => String(number).padStart(2, '0');
      return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} `
        + `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
    }

    // ★★★ r888：积分流水按「模型调用的真实情况」显示。用户需求原文：
    //   「我的账户里的积分流水要根据模型调用真实显示，内容包含模型名称，调用时间，金额，
    //     按次就显示按次，按 token 就显示 token 数，按秒就显示多少秒」。
    //   ★ 口径与单价都取自服务端写进 `meta` 的**快照** —— 前端不重算、也不回头查当前定价，
    //     否则管理员改一次价，历史流水会集体"变价"（对账就废了）。
    const LEDGER_BILLING_LABEL = { 'per-call': '按次', 'per-token': '按 Token', 'per-second': '按秒' };

    /** 单价快照 → 「0.5 积分/千输入 · 2 积分/千输出」这样的可核对文案。 */
    function pricingUnitLabel(billing, pricing) {
      const value = pricing && typeof pricing === 'object' ? pricing : null;
      if (!value) return '';
      if (billing === 'per-token') {
        const parts = [];
        if (Number(value.inputPer1k) > 0) parts.push(`${Number(value.inputPer1k)} 积分/千输入`);
        if (Number(value.outputPer1k) > 0) parts.push(`${Number(value.outputPer1k)} 积分/千输出`);
        return parts.join(' · ');
      }
      if (billing === 'per-second') return Number(value.perSecond) > 0 ? `${Number(value.perSecond)} 积分/秒` : '';
      return Number(value.perCall) > 0 ? `${Number(value.perCall)} 积分/次` : '';
    }

    /** 口径 + 这次的**真实用量**：按次 → 次数；按 Token → token 数；按秒 → 秒数。 */
    function ledgerUsageLabel(meta) {
      const billing = meta.billing;
      const parts = [];
      const label = LEDGER_BILLING_LABEL[billing];
      if (label) parts.push(label);
      const tokens = meta.tokens && typeof meta.tokens === 'object' ? meta.tokens : null;
      if (billing === 'per-token') {
        if (tokens && Number(tokens.total) > 0) {
          // ★ 上游没给 usage 时，meta 里存的是**我们自己的估算**（`source === 'estimated'`）——
          //   必须标出来，否则用户会把它当成上游实测值去核对（本项目「诚实标注比假装准确重要」）。
          const prefix = tokens.source === 'estimated' ? '预估 ' : '';
          parts.push(`${prefix}输入 ${formatTokens(tokens.input)} · 输出 ${formatTokens(tokens.output)} · 合计 ${formatTokens(tokens.total)} token`);
        } else {
          // 连估算都没有（老流水）→ 如实说，不编一个数出来。
          parts.push('上游未返回 token 数');
        }
      } else if (billing === 'per-second') {
        const seconds = Number(meta.seconds || 0);
        parts.push(seconds > 0 ? `${seconds} 秒` : '秒数未记录');
      } else if (billing === 'per-call') {
        parts.push(`${Number(meta.calls || 1)} 次`);
      }
      const unit = pricingUnitLabel(billing, meta.pricing);
      if (unit) parts.push(`单价 ${unit}`);
      return parts.join(' · ');
    }

    /** 把 `meta` 摊成一行可读明细；没有 meta 的老流水（充值 / 管理员调整）返回空串，不硬凑。 */
    function ledgerDetail(item) {
      const meta = item && typeof item.meta === 'object' && item.meta ? item.meta : null;
      if (!meta) return '';
      const parts = [];
      const name = String(meta.modelName || '').trim();
      if (name) parts.push(`模型 ${name}`);
      const usage = ledgerUsageLabel(meta);
      if (usage) parts.push(usage);
      if (meta.kind === 'precharge' && Number(meta.estimated) > 0) parts.push(`预扣 ${Number(meta.estimated)} 积分`);
      if (meta.kind === 'settle' && meta.actual != null) parts.push(`预扣 ${Number(meta.estimated)} → 实扣 ${Number(meta.actual)} 积分`);
      if (meta.kind === 'charge' && Number(meta.actual) > 0) parts.push(`实扣 ${Number(meta.actual)} 积分`);
      if (meta.note) parts.push(String(meta.note));
      return parts.join(' · ');
    }

    function renderProfileAccount(body) {

    }
    /**
     * 充值积分（「我的账户」页与个人菜单**共用这一条链路**）。
     * ★ 收尾必须一致：写本地缓存 → 重拉流水 → 刷新画布额度 → 重画账户页。
     */
    async function rechargeCredits(amount, price) {
      const confirmed = await askConfirm({title:'充值积分',message:'在线支付尚未开通，请联系客服核实充值金额和到账情况。',confirmText:'联系客服',icon:'↗'});
      if (confirmed) window.CanvasFlowSupport?.open?.();
    }

    function profileMyAssets() {
      const me = currentUser();
      return (state.libraryAssets || []).filter(asset => asset.ownerId === me.id);
    }
    async function loadStorageUsage(force = false) {
      if (state.storageView && !force) return state.storageView;
      const result = await api('/api/storage').catch(() => null);
      state.storageView = result?.storage || null;
      return state.storageView;
    }
    /** 字节 → `1.24 GB`（与服务端 `human_bytes` 同口径，用于「剩余」那行）。 */
    function formatStorageBytes(size) {
      const value = Number(size) || 0;
      const units = [['TB', 1024 ** 4], ['GB', 1024 ** 3], ['MB', 1024 ** 2], ['KB', 1024]];
      for (const [unit, step] of units) {
        if (value >= step) return `${Number((value / step).toFixed(2))} ${unit}`;
      }
      return `${Math.round(value)} B`;
    }
    /** 「我的素材」卡片的缩略图：与 `hydrateLibraryThumbs` 同一条链路，只是选择器不同。 */
    function hydrateProfileAssetThumbs(items) {
      items.forEach(async asset => {
        let url = libraryThumbCache.get(asset.id);
        if (url === undefined) {
          if (!asset.hasPreview) { libraryThumbCache.set(asset.id, ''); return; }
          // 带 mediaId 的直接用 /media/ 直链当 <img src>（省掉「取 JSON → 解 base64」那条慢路）
          url = asset.mediaUrl || (await fetchAssetData(asset.id).catch(() => '')) || '';
          libraryThumbCache.set(asset.id, url);
        }
        if (!url) return;
        const cover = document.querySelector(`.profile-asset-grid .lm-card[data-asset-id="${CSS.escape(asset.id)}"] .lm-cover`);
        if (cover?.isConnected && !cover.querySelector('img')) cover.insertAdjacentHTML('afterbegin', `<img src="${escapeHtml(url)}" alt="" />`);
      });
    }
    function renderProfileMyAssets(body) {
      return window.CanvasFlowStorage?.mount(body,{api,notify:showToast,openProject:item=>{
        if(item.workspaceId&&item.workspaceId!==currentWorkspaceId()){
          const workspace=readWorkspaces().find(w=>w.id===item.workspaceId);
          if(!workspace)return showToast('工作区不可用','×');
          updateProjectUrl(item.sourceId);enterWorkspace(workspace);return;
        }
        return openProject(item.sourceId);
      },openWorks:()=>renderProfileCenter('works'),openLibrary:()=>{
        state.lmTab='mine';return openLibraryManager();
      },changed:()=>{state.libraryAssets=[];state.storageView=null;libraryThumbCache.clear();}});
    }
    /** 「我的素材」里删一条：复用素材库那条删除链路，再刷新配额与当前页。 */
    async function deleteProfileAsset(assetId) {
      const asset = (state.libraryAssets || []).find(item => item.id === assetId);
      if (!asset) return;
      const confirmed = await askConfirm({
        title: '删除素材',
        message: `确定删除「${asset.name || '未命名素材'}」吗？删除后画布上对它的引用会失效，且无法找回。`,
        confirmText: '删除', danger: true, icon: '⌫',
      });
      if (!confirmed) return;
      await deleteLibraryAsset(assetId);
      await loadStorageUsage(true);      // 配额变了，重新取一次
      const el = $('#profileCenterBody');
      if (el && $('.profile-center-tab[data-profile-tab="mine"]')?.classList.contains('active')) renderProfileMyAssets(el);
    }
    function openProfileCenter() {

    }

    // 「编辑资料」弹窗：基本资料（名称/简介/手机号）+ 账户安全（密码/邮箱验证码更换）。
    // 手机号与密码改动需要当前密码确认；邮箱更换必须接收新邮箱验证码（/api/account/email/send-code）。
    let accountEditorState = { backdrop: null, codeTimer: null, codeRemaining: 0 };

    function accountEditorIdentity() {
      const saved = identity.read();
      const current = currentUser();
      return {
        name: current.name,
        bio: saved.bio || '',
        email: authenticatedUser?.email || saved.email || '',
        phone: authenticatedUser?.phone || saved.phone || '',
      };
    }

    function setAccountMessage(message = '', success = false) {
      const box = $('#accountMessage');
      if (!box) return;
      box.textContent = message;
      box.classList.toggle('success', Boolean(success));
    }

    function closeAccountEditor() {
      clearInterval(accountEditorState.codeTimer);
      accountEditorState.codeTimer = null;
      accountEditorState.backdrop?.remove();
      accountEditorState.backdrop = null;
    }

    function startAccountCodeCountdown(seconds = 60) {
      clearInterval(accountEditorState.codeTimer);
      accountEditorState.codeRemaining = seconds;
      const render = () => {
        const button = $('[data-account-action="send-code"]');
        if (!button) { clearInterval(accountEditorState.codeTimer); return; }
        button.disabled = accountEditorState.codeRemaining > 0;
        button.textContent = accountEditorState.codeRemaining > 0 ? `${accountEditorState.codeRemaining}s 后重发` : '获取验证码';
      };
      render();
      accountEditorState.codeTimer = setInterval(() => {
        accountEditorState.codeRemaining -= 1;
        if (accountEditorState.codeRemaining <= 0) clearInterval(accountEditorState.codeTimer);
        render();
      }, 1000);
    }

    function refreshProfileCenterIfVisible() {
      if ($('#profileCenterView') || ($$('#contentView .profile-center-view').length && !$('#contentView')?.hidden)) renderProfileCenter('overview');
    }

    async function saveAccountName() {
      const next = $('#accountNameInput')?.value?.trim() || '';
      if (!next) return setAccountMessage('请输入显示名称');
      identity.write({ ...identity.read(), account: next });
      applyIdentity();
      refreshProfileCenterIfVisible();
      setAccountMessage('显示名称已更新', true);
    }

    async function saveAccountBio() {
      const next = $('#accountBioInput')?.value?.trim() || '';
      identity.write({ ...identity.read(), bio: next });
      refreshProfileCenterIfVisible();
      setAccountMessage('个人简介已更新', true);
    }

    async function saveAccountPhone() {
      const phone = ($('#accountPhoneInput')?.value || '').replace(/[\s-]/g, '');
      const password = $('#accountPhonePassword')?.value || '';
      if (!/^1[3-9]\d{9}$/.test(phone)) return setAccountMessage('请输入有效的 11 位手机号');
      if (!password) return setAccountMessage('请输入当前密码确认');
      const button = $('[data-account-action="save-phone"]');
      if (button) { button.disabled = true; button.textContent = '保存中…'; }
      const result = await authRequest('/api/account/phone', { method: 'POST', body: JSON.stringify({ phone, currentPassword: password }) });
      if (button) { button.disabled = false; button.textContent = '保存手机号'; }
      if (result?.error === 'network_error') return setAccountMessage(result.message);
      if (result?.error === 'unauthenticated') return setAccountMessage('请先登录后再修改手机号');
      if (result?.error) return setAccountMessage(result.message || '手机号保存失败');
      authenticatedUser && (authenticatedUser.phone = result.phone);
      identity.write({ ...identity.read(), phone: result.phone });
      const label = $('#accountPhoneCurrent');
      if (label) label.textContent = `当前：${result.phone}`;
      $('#accountPhonePassword').value = '';
      setAccountMessage(result.message || '手机号已更新', true);
    }

    async function sendAccountEmailCode() {
      const email = ($('#accountEmailInput')?.value || '').trim().toLowerCase();
      if (!email) return setAccountMessage('请输入新邮箱地址');
      const currentPassword=$('#accountEmailPassword')?.value||'';
      if(!currentPassword)return setAccountMessage('请输入当前密码确认更换邮箱');
      const button = $('[data-account-action="send-code"]');
      if (button) { button.disabled = true; button.textContent = '发送中…'; }
      const result = await authRequest('/api/account/email/send-code', { method: 'POST', body: JSON.stringify({ email,currentPassword }) });
      if (button && accountEditorState.codeRemaining <= 0) { button.disabled = false; button.textContent = '获取验证码'; }
      if (result?.error) return setAccountMessage(result.message || '验证码发送失败，请稍后重试');
      const dev = $('#accountDevCode');
      if (dev) { dev.hidden = !result.devCode; dev.textContent = result.devCode ? `开发环境验证码：${result.devCode}` : ''; }
      if (result.devCode) $('#accountEmailCode').value = result.devCode;
      startAccountCodeCountdown(60);
      setAccountMessage(result.delivery === 'development' ? '本地开发模式：验证码已显示在上方。' : '验证码已发送，请到新邮箱查收（注意垃圾邮件）。', true);
    }

    async function saveAccountEmail() {
      const email = ($('#accountEmailInput')?.value || '').trim().toLowerCase();
      const code = ($('#accountEmailCode')?.value || '').replace(/\D/g, '').slice(0, 6);
      if (!email) return setAccountMessage('请输入新邮箱地址');
      if (code.length !== 6) return setAccountMessage('请输入六位邮箱验证码');
      const button = $('[data-account-action="save-email"]');
      if (button) { button.disabled = true; button.textContent = '保存中…'; }
      const result = await authRequest('/api/account/email', { method: 'POST', body: JSON.stringify({ email, code }) });
      if (button) { button.disabled = false; button.textContent = '确认更换邮箱'; }
      if (result?.error) return setAccountMessage(result.message || '邮箱更换失败');
      applyAuthenticatedUser(result.user);
      const label = $('#accountEmailCurrent');
      if (label) label.textContent = `当前：${result.user.email}`;
      $('#accountEmailInput').value = '';
      $('#accountEmailCode').value = '';
      const dev = $('#accountDevCode');
      if (dev) { dev.hidden = true; dev.textContent = ''; }
      clearInterval(accountEditorState.codeTimer);
      accountEditorState.codeRemaining = 0;
      const sendButton = $('[data-account-action="send-code"]');
      if (sendButton) { sendButton.disabled = false; sendButton.textContent = '获取验证码'; }
      setAccountMessage(result.message || '邮箱已更新', true);
    }

    async function saveAccountPassword() {
      const currentPassword = $('#accountPasswordCurrent')?.value || '';
      const newPassword = $('#accountPasswordNext')?.value || '';
      const confirmPassword = $('#accountPasswordConfirm')?.value || '';
      if (!currentPassword) return setAccountMessage('请输入当前密码');
      if (newPassword.length < 8 || !/[A-Za-z]/.test(newPassword) || !/\d/.test(newPassword)) return setAccountMessage('新密码至少 8 位，并且需要包含字母和数字');
      if (newPassword !== confirmPassword) return setAccountMessage('两次输入的新密码不一致');
      const button = $('[data-account-action="save-password"]');
      if (button) { button.disabled = true; button.textContent = '保存中…'; }
      const result = await authRequest('/api/account/password', { method: 'POST', body: JSON.stringify({ currentPassword, newPassword }) });
      if (button) { button.disabled = false; button.textContent = '更新密码'; }
      if (result?.error) return setAccountMessage(result.message || '密码更新失败');
      ['#accountPasswordCurrent', '#accountPasswordNext', '#accountPasswordConfirm'].forEach(selector => { const field = $(selector); if (field) field.value = ''; });
      setAccountMessage(result.message || '密码已更新', true);
    }

