      const min = parseDurationSeconds(params.minDuration);
      const max = parseDurationSeconds(params.maxDuration);
      if (min === null && max === null) return DURATION_OPTIONS;
      const kept = DURATION_OPTIONS.filter(option => {
        const seconds = parseDurationSeconds(option.value);
        if (seconds === null) return true;
        if (min !== null && seconds < min) return false;
        if (max !== null && seconds > max) return false;
        return true;
      });
      return kept.length ? kept : DURATION_OPTIONS;
