      const additions = LIBTV_ROLES.map(normalizeCharacter)
        .filter(role => role && !ids.has(role.id))
        .filter(role => !isPresetRoleHidden(role.id));

      const next = additions.length ? [...additions, ...list] : list;
      try {
        localStorage.setItem('canvasflow-characters', JSON.stringify(next.map(normalizeCharacter).filter(Boolean)));
        localStorage.setItem(LIBTV_ROLES_MERGED_KEY, '1');
      } catch { /* private mode：读时合并依然生效 */ }
      return next;
