    const DOCK_TOKEN_TYPES = { marker: '标记', effect: '特效', character: '角色', camera: '运镜' };
    const DOCK_TOKEN_TO_TOOL = { '标记': 'marker', '特效': 'effect', '角色': 'character', '运镜': 'camera' };
    function appendDockToken(tool, label) {
      promptInput = $('#promptInput') || promptInput;
      const type = DOCK_TOKEN_TYPES[tool];
      const cleanLabel = String(label || '').trim();
      if (!promptInput || !type || !cleanLabel) return;
      const token = `${type}:${cleanLabel}`;
      const wrappedToken = `[[${token}]]`;
      const current = promptInput.value.trim();
      if (current.includes(wrappedToken)) return showToast(`已添加过「${cleanLabel}」`, '⊞');
      const next = `${current}${current ? ' ' : ''}${wrappedToken}`;
      promptInput.value = next;
      dispatchPromptInput(true);
      // preventScroll：提示词 Dock 贴在选中卡片下方，可能有一截在视口外。默认 focus 会把画布容器
      // 滚动一段去「露出」它，而画布的平移/缩放完全靠 transform 记账（panX/panY），
      // 容器一旦被滚动，所有节点在屏幕上的位置就和记账值错位，适配 / 自动落点都会算歪。
      promptInput.focus({ preventScroll: true });
      showToast(`已添加${type}标记：${cleanLabel}`, '✦');
    }








    function emotionTokenText(type, label) {
      const raw = String(label);
      if (type === '表情变化') {
        const parts = raw.split('|');
        if (parts.length < 4) return `@表情变化：${parts[0]}`;
        const [startRaw, endRaw] = parts[1].split('~');
        const keyframes = parts[3].split(',').map((item, index) => {
          const [recipeLevel, timeRaw] = item.split('@');
          const [recipeId, levelRaw] = String(recipeLevel || '').split(':');
          return {
            id: `emotion-kf-${index}`,
            recipeId: recipeId || 'calm',
            level: Math.min(5, Math.max(1, parseInt(levelRaw, 10) || 1)),
            time: Number(timeRaw) || 0,
            easing: 'ease-in-out',
          };
        });
        return emotionDynamicPrompt({
          timeRange: { start: Number(startRaw) || 0, end: Number(endRaw) || 0 },
          loop: parts[2] === '1',
          keyframes,
          selectedId: '',
          playing: false,
          playTime: Number(startRaw) || 0,
        });
      }
      const [name, levelRaw] = raw.split('|');
      if (name === EMOTION_CALM.name) return emotionPromptText('calm', 1);
      const recipe = EMOTION_WHEEL.find(item => item.label === name);
      if (!recipe) return `@表情：${name}`;
      return emotionPromptText(recipe.id, Math.min(5, Math.max(1, parseInt(levelRaw, 10) || 3)));
    }
    function resolvePromptTokens(text, depth = 0) {
      const source = String(text || '');
      if (!source || depth > 4) return source;
      return source.replace(PROMPT_TOKEN_PATTERN, (full, type, label) => {
        if (type === '表情' || type === '表情变化') return emotionTokenText(type, label);
        const tool = DOCK_TOKEN_TO_TOOL[type];
        if (!tool) return full;
        if (tool === 'character') {
          const character = characterStorage.get().find(item => item.name === label);
          return character ? resolvePromptTokens(character.value, depth + 1) : label;
        }
        // ★ r832：运镜优先走「运镜广场」那张可编辑的表（管理员在「提示词编辑」里改过的正文）。
        //   以前 `[[运镜:固定镜头]]` 在 DOCK_TOOL_LIBRARY.camera.items 里查不到 → 直接落回短名，
        //   等于没有运镜提示词；现在画廊的 23 条都有正文了。
        if (tool === 'camera') {
          const text = cameraPromptText(label);
          if (text) return text;
        }
        const item = DOCK_TOOL_LIBRARY[tool]?.items?.find(entry => entry.label === label);
        return item?.value || label;
      });
    }

