    // Save actual encoded media before adding an output node. A failed upload never creates a fake result.
    window.CanvasFlowDirectorGetImageHistory = async () => {
      const currentProjectId = state.projectId;
      const readJobs = async () => {
        const jobs=[];
        for (;;) {
          const page=await api(`/api/jobs?kind=image&status=completed&limit=200&offset=${jobs.length}`,{throwOnError:true});
          if(state.projectId!==currentProjectId)throw new Error('画布已切换，请重新打开历史记录');
          jobs.push(...(page?.jobs||[]));
          if(!page?.jobs?.length||jobs.length>=page.total)return jobs;
        }
      };
      const results = await Promise.all([
        api('/api/projects', {throwOnError:true}),
        api('/api/assets', {throwOnError:true}),
        readJobs(),
      ]);
      if (state.projectId !== currentProjectId) throw new Error('画布已切换，请重新打开历史记录');
      const [projects, assets, jobs] = results;
      const workspaceAssets = (assets?.assets || []).filter(a => !a.workspaceId || a.workspaceId === assets.workspaceId);
      return {currentProjectId,items:window.DirectorHistory.collect({projects:projects?.projects||[],assets:workspaceAssets,jobs:jobs||[],currentProjectId,currentNodes:nodeSnapshot()})};
    };
