    function panoramaModelSize(model){
      const rows=specRowsFor('image',model)||[],aspect=specRowValues(specRowOf(rows,'aspectRatio'));
      const pixels=specRowValues(specRowOf(rows,'resolution')).filter(v=>/^\d+x\d+$/.test(v)&&Number(v.split('x')[0])===2*Number(v.split('x')[1]));
      if(pixels.length)return pixels.reduce((a,b)=>Math.abs(Number(a.split('x')[0])-2048)<Math.abs(Number(b.split('x')[0])-2048)?a:b);
      return aspect.includes('2:1')?'2048x1024':null;
    }
