    window.CanvasFlowDirectorBuildScene = async ({prompt,scene,referenceImage,modelId,previs,project,selectedId,feedback,feedbackImage}) => {
      const projectId=state.projectId;
      if(previs){const models=await window.CanvasFlowDirectorModels();const chosen=models.find(m=>m.id===modelId);if(!chosen)throw Error('请在预演台选择已勾选的模型');if(!chosen.enabled||!chosen.supportsScene)throw Error('该模型未启用或不支持场景调度，请选择文本模型');if(state.projectId!==projectId)throw Error('画布已切换，请重新提交');}
      let reference='';
      if(referenceImage){
        const description=await api('/api/ai/image-to-text',{method:'POST',throwOnError:true,body:JSON.stringify({image:referenceImage,modelId:modelId||textModelId()||undefined,instruction:'描述图片中人物、道具、空间位置及构图，用于搭建3D预演场景。若有画笔、箭头、框选或文字标注，请同时解释标注指向的对象、移动方向和调整意图；标注属于用户调整要求，不要把它当作场景中的实体。'})});
        reference=description?.description||description?.text||'';
      }
      if(state.projectId!==projectId)throw Error('画布已切换，请重新提交');
      if(feedbackImage){
        try{
          const view=await api('/api/ai/image-to-text',{method:'POST',throwOnError:true,body:JSON.stringify({image:feedbackImage,modelId:modelId||undefined,instruction:'这是同一3D白模预演在开始、中间、结束时刻的机位画面。只检查构图、主体出画、穿插和运动连贯性；按时间指出可观察到的问题，不猜测不可见内容。若没有问题请说明。'})});
          feedback={...feedback,visualReview:view?.description||view?.text||''};
        }catch(error){feedback||={issues:[]};feedback.visualReviewUnavailable='当前模型未完成画面检查：'+error.message;}
        if(state.projectId!==projectId)throw Error('画布已切换，请重新提交');
      }
      const instruction=window.DirectorSceneAgent?.request?window.DirectorSceneAgent.request({prompt,project:project||{objects:scene||[],sequence:{fps:24,durationFrames:240}},selectedId,reference,feedback}):'你是3D预演场景搭建助手。只返回JSON：{"message":"简短说明","objects":[{"kind":"character|camera|geometry","name":"名称","bodyType":"sam|female|muscular|slim|broad|child|teen|chibi","type":"box|sphere|cylinder|torus|cone|pyramid","position":[x,y,z],"rotation":[角度x,角度y,角度z],"scale":[1,1,1],"color":"#rrggbb","pose":"站立|思考|单膝跪|双膝跪|招手|伸手","target":[0,1.2,0],"fov":50}]}。Y为竖直向上，地面Y=0，人物身高1.83米。objects每一项必须带operation字段：新增用add；修改现有对象用update并附上现有id，kind保持不变。update只传需要改的字段，不复制现有对象。最多30个对象，不执行代码。相机应朝向人物。现有场景：'+JSON.stringify(scene).slice(0,16000)+'\n参考图：'+reference+'\n用户要求：'+prompt;
      const result=await api('/api/ai/text-generate',{method:'POST',throwOnError:true,body:JSON.stringify({modelId:modelId||textModelId()||undefined,purpose:'scene_agent',prompt:instruction})});
      if(state.projectId!==projectId)throw Error('画布已切换，生成结果没有应用到其他项目');
      return result?.text||'';
    };
    window.CanvasFlowDirectorExport = async ({blob,name,node,duration,width,height,posterDataUrl,destination}) => {
      const projectId=state.projectId;
      const media=await uploadMediaFile(new File([blob],name,{type:blob.type||'video/webm'}));
      const url=media?.url||media?.mediaUrl||(media?.mediaId?'/media/'+encodeURIComponent(media.mediaId):'');
      if(!media?.mediaId||!url)throw new Error('视频文件未能保存，请下载本地备份后重试');
      if(state.projectId!==projectId)throw new Error('画布已切换，视频未插入其他项目');
      if(!node || !document.contains(node))throw new Error('原导演台节点已移除，视频未插入画布');
      let posterUrl = '';
      if(posterDataUrl){
        const poster=await uploadMediaFile(new File([await(await fetch(posterDataUrl)).blob()],name+'.jpg',{type:'image/jpeg'}));
        posterUrl=poster?.url||'';
      }
      if(state.projectId!==projectId||!document.contains(node))throw new Error('原画布或导演台已变更，视频未插入其他项目');
      remember();
      const output=appendNode('output',{left:(parseFloat(node?.style.left)||0)+(node?.offsetWidth||320)+80,top:parseFloat(node?.style.top)||0});
      if(!output)throw new Error('创建视频节点失败');
      const label=nodeLabelEl(output);if(label)label.textContent='导演台预演视频';
      const copy=output.querySelector('.node-copy');if(copy)copy.textContent=duration.toFixed(2)+' 秒 · '+width+' × '+height+' · 机位预演';
      output.dataset.previewName=name;output.dataset.sourceDirectorId=node?.dataset.nodeId||'';
      if(posterUrl)output.dataset.previewMedia=posterUrl;
      setOutputVideoPreview(output,url);
      if(!posterUrl&&posterDataUrl){const video=output.querySelector('video');if(video)video.poster=posterDataUrl;}
      output.dataset.generated='true';output.dataset.jobStatus='completed';output.dataset.mediaRatio=String(height/width);
      const preview=output.querySelector('.output-preview');preview?.classList.add('generated');
      const status=output.querySelector('.output-state');if(status)status.textContent='预演完成 · '+duration.toFixed(2)+'s';
      const dimension=output.querySelector('.media-dimension');if(dimension)dimension.textContent=width+' × '+height;
      const badge=output.querySelector('.media-badge');if(badge)badge.textContent='导演台预演';
      const sourcePort=node.querySelector('.port-right'),targetPort=output.querySelector('.port-left');
      if(!sourcePort||!targetPort||!window.CanvasFlowConnections?.connect?.(sourcePort,targetPort)){
        output.remove();throw new Error('无法建立导演台与视频的引用连线，请下载备份后重试');
      }
      state.nodeCount=document.querySelectorAll('.flow-node').length;updateNodeCount();selectNode(output);placeNewNode(output);scheduleSave();
      if(destination==='film'){
        const projectId=state.projectId,draft=Boolean(state.projectIsDraft),headers=workspaceHeader();
        const filmCall=args=>api('/api/film/action',{method:'POST',headers,body:JSON.stringify({projectId,draft,args}),throwOnError:true});
        const synced=await filmCall({action:'sync_canvas',direction:'to-film',graph:{nodes:nodeSnapshot().filter(n=>n.id===output.dataset.nodeId),edges:[]}});
        const source=synced.media?.[output.dataset.nodeId]?.path;if(!source)throw Error('视频已保存到画布，但成片导入未完成');
        const doc=await filmCall({action:'document'});const clips=(doc.film?.tracks||[]).flatMap(t=>t.clips);
        const at=Math.max(0,...clips.map(c=>(c.at||0)+((c.time?.[1]||0)-(c.time?.[0]||0))/(c.speed||1)));
        await filmCall({action:'edit',revision:doc.revision,ops:[...(!clips.length?[{op:'stage',w:width,h:height}]:[]),{op:'insert',clip:{src:source,id:'previs-'+Date.now(),time:[0,duration]},at,newTrack:doc.film?.tracks?.length||0}]});
      }
      showToast(destination==='film'?'预演视频已加入成片时间轴':'导演台视频已加入画布','▶');return {nodeId:output.dataset.nodeId,mediaId:media.mediaId,url};
    };


    function resolveOutputNode() {
      const edges = window.CanvasFlowConnections?.getEdges?.() || [];
      const selected = $('.flow-node.selected');
      const outputs = $$('[data-node="output"]');
      if (!outputs.length) return null;
      if (selected?.dataset.node === 'output') return selected;
      if (selected) {
        const downstream = edges.find(edge => edge.source === selected.dataset.nodeId && outputs.some(node => node.dataset.nodeId === edge.target));
        if (downstream) return outputs.find(node => node.dataset.nodeId === downstream.target) || outputs[0];
      }
      const connected = outputs.find(node => edges.some(edge => edge.target === node.dataset.nodeId));
      return connected || outputs[0];
    }
    // 模型卡即生成卡：选中模型卡时视频直接生成在这张卡上；否则沿用输出卡逻辑。
    function resolveGenerationTarget() {
      const selected = $('.flow-node.selected');
      if (selected?.dataset.node === 'model') return selected;
      return resolveOutputNode();
    }

    // Upstream semantics: a video node consumes the cards DIRECTLY wired into it — prompt text,
    // reference image, soundtrack. Direct predecessors only: a prompt that feeds an intermediate
    // card (e.g. prompt -> audio) was that card's business, not this node's input.
    function collectUpstreamInputs(output, options = {}) {
      const edges = window.CanvasFlowConnections?.getEdges?.() || [];
      const byId = new Map($$('.flow-node').map(node => [node.dataset.nodeId, node]));
      const texts = [];
      const labels = [];
      const inputs = [];
      edges.filter(edge => edge.target === output?.dataset.nodeId).forEach(edge => {
        const node = byId.get(edge.source);
        if (!node) return;
        if (node.dataset.node === 'prompt') {
          // ★ 过统一清洗：上游文本节点的正文一般不会被污染，但「引用该节点生成」会把源节点的
          //   copy（可能正是结果命名）抄进新节点正文 —— 这里兜一道，别让污染顺着连线传下去。
          const copy = sanitizePromptSource(node.querySelector('.node-copy')?.textContent);
          if (copy) { texts.push(copy); labels.push('提示词'); inputs.push(`提示词：${copy.slice(0, 60)}`); }
          else { labels.push('提示词（空）'); inputs.push('提示词：（空白）'); }
        } else if (node.dataset.node === 'image') {
          const hasImage = nodeHasUsableImage(node) || Boolean(node.dataset.previewName);
          const name = node.dataset.previewName || node.querySelector('.node-title')?.textContent?.trim() || '参考图片';
          if (hasImage) { labels.push('参考图片'); inputs.push(`参考图片：${name.slice(0, 60)}`); }
          else { labels.push('参考图片（空白）'); inputs.push('参考图片：（空白，跳过）'); }
        } else if (node.dataset.node === 'audio') {
          const name = node.querySelector('.media-copy')?.textContent?.trim();
          if (node.dataset.trackId || name) { labels.push('配乐'); inputs.push(`配乐：${(name || '已选曲目').slice(0, 60)}`); }
          else { labels.push('配乐（未选择）'); inputs.push('配乐：（未选择，跳过）'); }
        } else if (node.dataset.node === 'output') {
          // Chained video nodes: a generated upstream video feeds this one (continuation / redo).
          const generated = node.dataset.generated === 'true' || node.querySelector('.output-preview')?.classList.contains('generated');
          const name = node.querySelector('.node-title')?.textContent?.trim() || '上游视频';
          if (generated) { labels.push('上游视频'); inputs.push(`上游视频：${name.slice(0, 60)}`); }
          else { labels.push('上游视频（未生成）'); inputs.push('上游视频：（未生成，跳过）'); }
        }
      });
      // `includeDock: false` 供图片生成用：图片/音频节点被选中时输入框会被 `.node-copy` 回填
      // （`syncInspectorToNode`），那不是"用户这次写的提示词"——混进来会把上游正文顶掉。
      const inspectorText = options.includeDock === false ? '' : resolvePromptTokens(promptInput?.value?.trim());
      // The dock textarea is the prompt itself, not an upstream card: it feeds generation but is
      // never listed in the card's input summary (only wired cards are).
      if (inspectorText && !texts.some(text => text === inspectorText)) texts.unshift(inspectorText);
      return { prompt: texts.join(' / '), labels, inputs };
    }
    function updateOutputInputsSummary(output = null) {
      const targets = output ? [output] : $$('[data-node="output"]');
      targets.forEach(node => {
        const meta = node.querySelector('.output-meta span:last-child');
        if (!meta) return;
        const { labels } = collectUpstreamInputs(node);
        const summary = labels.length ? labels.join(' + ') : '—';
        meta.textContent = summary;
        meta.title = labels.length ? `生成时引用上游：${labels.join('、')}` : '连接上游节点后，生成时会引用它们';
      });
    }

    function stopJobPolling() { clearInterval(state.jobTimer); state.jobTimer = null; }

    // A generation job outlives the page: bindings (jobId -> output node) are stored with the
    // project so a reload can re-attach to the still-running or finished job instead of showing
    // "等待生成" forever.
    function applyJobBindings(list) {
      state.jobBindings = (Array.isArray(list) ? list : [])
        .filter(item => item && item.jobId && item.outputId)
        .slice(0, 20)
        .map(item => ({ jobId: String(item.jobId).slice(0, 100), outputId: String(item.outputId).slice(0, 100), done: false }));
    }
    function watchPendingJobs({ silent = true } = {}) {
      stopJobPolling();
      const bindings = state.jobBindings || [];
      if (!bindings.length) return;
      const context = generationContext(null);
      // 任务记录可能被删除或被 jobs.jsonl 裁剪；不设上限轮询会让生成按钮永久禁用。
      const MAX_TICKS = 900; // 700ms × 900 ≈ 10.5 分钟
      let ticks = 0;
      let polling = false;
      const timer = state.jobTimer = setInterval(async () => {
        if (polling || !generationContextActive(context) || state.jobTimer !== timer) return;
        polling = true;
        try {
          ticks += 1;
          for (const binding of bindings) {
            if (binding.done) continue;
            const output = document.querySelector(`[data-node-id="${CSS.escape(binding.outputId)}"]`);
            if (!output || (output.dataset.node !== 'output' && output.dataset.node !== 'model')) { binding.done = true; continue; }
            const poll = await api(`/api/jobs/${encodeURIComponent(binding.jobId)}`, { headers: context.headers });
            if (!generationContextActive(context) || state.jobTimer !== timer) return;
            const job = poll?.job;
            if (!job) {
              binding.misses = (binding.misses || 0) + 1;
              if (binding.misses >= 3) {
                binding.done = true; binding.failed = true;
                renderJobProgress(output, { status: 'failed', error: '任务记录已不存在（可能被删除或清理），无法继续跟踪进度' });
              }
              continue;
            }
            binding.misses = 0;
            output.dataset.jobId = job.id || binding.jobId;
            if (renderJobProgress(output, job)) { binding.done = true; binding.failed = job.status === 'failed'; }
          }
          const timedOut = ticks >= MAX_TICKS;
          if (timedOut) bindings.forEach(item => { item.done = true; });
          if (bindings.every(item => item.done)) {
            stopJobPolling();
            state.jobBindings = [];
            const sendButton = $('#generateBtn');
            if (!state.activeVideoSubmission?.pending) {
              state.activeVideoSubmission = null;
              if (sendButton?.disabled) { sendButton.disabled = false; setSendButtonState(sendButton, 'done'); }
            }
            refreshUsage();
            scheduleSave();
            if (!silent) {
              const failed = bindings.some(item => item.failed);
              showToast(failed ? '视频模型生成失败，可右键输出卡片重试' : '视频已生成，可右键输出卡片下载', failed ? '×' : '✓');
              if (timedOut && !failed) showToast('生成等待超时，可稍后刷新画布查看最新进度', 'ⓘ');
            }
          }
        } finally { polling = false; }
      }, 700);
    }
    function resumeJobBindings() {
      if (isStandaloneFile()) return;
      watchPendingJobs({ silent: true });
    }

    // 任务已用秒数：以**服务端 createdAt** 为准 —— 刷新页面后仍然准确，
    // 不像前端计时器那样会归零（图片/视频的"已用时间"文案都用它）。
    function jobElapsedSeconds(job) {
      const created = Date.parse(String(job?.createdAt || ''));
      if (!Number.isFinite(created)) return 0;
      return Math.max(0, Math.round((Date.now() - created) / 1000));
    }

    function renderJobProgress(output, job) {
      output.dataset.jobStatus = job?.status || '';
      if (job?.error) output.dataset.jobError = String(job.error).slice(0, 500);
      else delete output.dataset.jobError;
      const progress = Number(job.progress) || 0;
      // 模型卡即生成卡：进度/成片直接呈现在模型卡的预览区（状态用独立浮层，不占用模型名徽标）。
      if (output.dataset.node === 'model') {
        const preview = output.querySelector('.media-preview');
        if (job.status === 'completed') {
          output.dataset.generated = 'true';
          preview?.classList.remove('generating');
          setModelJobState(output, null);
          if (job.videoUrl) setModelNodeVideo(output, job.videoUrl);
          else setModelJobState(output, '已完成，但供应商未返回视频地址');
          return true;
        }
        if (job.status === 'failed') {
          setModelJobState(output, '生成失败 · 可右键重试');
          preview?.classList.remove('generated', 'generating');
          output.dataset.generated = 'false';
          return true;
        }
        // 生成中等待动效层：扫描线 + 进度条。
        // ★ 上游**不返回 progress** 时不要显示「生成中 0%」（停滞假象，比不显示更糟）：
        //   改为真实阶段 + 已用时间，进度条走不确定滑动（CSS 认 data-job-progress="unknown"）。
        preview?.classList.add('generating');
        const hasProgress = Number(progress) > 0;
        if (preview) {
          if (hasProgress) {
            preview.style.setProperty('--job-progress', `${progress}%`);
            delete preview.dataset.jobProgress;
          } else {
            preview.dataset.jobProgress = 'unknown';
          }
        }
        setModelJobState(output, job.status === 'queued'
          ? '排队中'
          : (hasProgress ? `生成中 ${progress}%` : `生成中 · 已用 ${jobElapsedSeconds(job)}s`));
        return false;
      }
      const pill = output.querySelector('.status-pill');
      const time = output.querySelector('.node-time');
      const preview = output.querySelector('.output-preview');
      const previewText = preview?.querySelector('.output-state');
      if (job.status === 'completed') {
        if (pill) { pill.textContent = '已完成'; pill.className = 'status-pill ready'; }
        if (time) time.textContent = '刚刚完成';
        if (job.videoUrl) setOutputVideoPreview(output, job.videoUrl);
        if (previewText) previewText.textContent = job.videoUrl ? '生成完成 · 右键菜单可放大播放' : '已完成，但供应商未返回视频地址';
        preview?.classList.add('generated');
        preview?.classList.remove('generating');
        output.dataset.generated = 'true';
        if (job.videoUrl) output.dataset.videoUrl = job.videoUrl;
        return true;
      }
      if (job.status === 'failed') {
        if (pill) { pill.textContent = '生成失败'; pill.className = 'status-pill error'; }
        if (time) time.textContent = '可右键重试';
        if (previewText) previewText.textContent = job.error || '供应商生成失败';
        preview?.classList.remove('generated', 'generating');
        output.dataset.generated = 'false';
        return true;
      }
      // 同 model 卡：没有真实 progress 时不显示「生成中 0%」，改走「阶段 + 已用时间」+ 不确定滑动条。
      preview?.classList.add('generating');
      const outHasProgress = Number(progress) > 0;
      if (preview) {
        if (outHasProgress) {
          preview.style.setProperty('--job-progress', `${progress}%`);
          delete preview.dataset.jobProgress;
        } else {
          preview.dataset.jobProgress = 'unknown';
        }
      }
      const outElapsed = jobElapsedSeconds(job);
      if (pill) { pill.textContent = job.status === 'queued' ? '排队中' : '生成中'; pill.className = 'status-pill ready'; }
      if (time) time.textContent = job.status === 'queued' ? '已提交供应商任务' : (outHasProgress ? ('生成中 ' + progress + '%') : `生成中 · 已用 ${outElapsed}s`);
      if (previewText) previewText.textContent = outHasProgress ? ('视频模型生成中 ' + progress + '%') : `视频模型生成中 · 已用 ${outElapsed}s`;
      return false;
    }

    // The dock send button is a 34px circle, so state changes swap the glyph/title, never a text label.
    function setSendButtonState(button, mode) {
      if (!button) return;
      if (mode === 'busy') {
        button.innerHTML = '<span class="spinner"></span>';
        button.title = '正在生成…';
        button.setAttribute('aria-label', '正在生成');
        return;
      }
      button.innerHTML = '✦';
      button.title = mode === 'done' ? '再次生成（⌘/Ctrl + Enter）' : '生成视频（⌘/Ctrl + Enter）';
      button.setAttribute('aria-label', mode === 'done' ? '再次生成' : '生成视频');
    }

    function createGeneratedImageData(prompt, model) {
      const shortPrompt = String(prompt || '').slice(0, 42).replace(/[<>&"']/g, '');
      const title = String(model?.name || 'AI Image').replace(/[<>&"']/g, '');
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 960 540"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b8d9e6"/><stop offset=".52" stop-color="#efc3c3"/><stop offset="1" stop-color="#223b44"/></linearGradient></defs><rect width="960" height="540" fill="url(#g)"/><circle cx="700" cy="130" r="84" fill="#fff" opacity=".28"/><path d="M0 410 Q260 330 520 420 T960 360 V540 H0Z" fill="#16303a" opacity=".78"/><rect x="365" y="150" width="145" height="260" rx="70" fill="#fbf7f1" opacity=".94"/><ellipse cx="438" cy="165" rx="50" ry="64" fill="#26303a"/><text x="34" y="48" fill="#c4dbff" font-family="Arial" font-size="23">${title}</text><text x="34" y="500" fill="#f8fbff" opacity=".85" font-family="Arial" font-size="18">${shortPrompt}</text></svg>`;
      return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
    }




    const AUDIO_VOICE_LIBRARY = [
      { value: 'alloy', description: '平衡自然，适合通用旁白与说明内容' },
      { value: 'ash', description: '清晰沉稳，适合知识讲解与纪实表达' },
      { value: 'coral', description: '明亮亲和，适合生活方式与品牌内容' },
      { value: 'echo', description: '清楚有力，适合节奏鲜明的短内容' },
      { value: 'fable', description: '温暖舒缓，适合故事与长篇叙述' },
      { value: 'nova', description: '轻快灵动，适合年轻化与互动内容' },
      { value: 'onyx', description: '低沉厚实，适合预告与氛围旁白' },
      { value: 'sage', description: '柔和克制，适合教程与专业表达' },
      { value: 'shimmer', description: '轻盈明亮，适合轻松自然的内容' },
    ];
    const AUDIO_VOICES = AUDIO_VOICE_LIBRARY;
    const AUDIO_VOICE_FAVORITES_KEY = 'canvasflow-audio-voice-favorites';


    const AUDIO_VOICE_RECENTS_KEY = 'canvasflow-audio-voice-recents';
    const AUDIO_VOICE_PAGE_SIZE = 20;
    const AUDIO_VOICE_PREVIEW_URL = voice => `https://cdn.openai.com/API/docs/audio/${encodeURIComponent(voice)}.wav`;
    const AUDIO_VOICE_ICONS = {
      close: '<svg width="18" height="18" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M205.66 194.34a8 8 0 0 1-11.32 11.32L128 139.31l-66.34 66.35a8 8 0 0 1-11.32-11.32L116.69 128L50.34 61.66a8 8 0 0 1 11.32-11.32L128 116.69l66.34-66.35a8 8 0 0 1 11.32 11.32L139.31 128Z"/></svg>',
      search: '<svg width="17" height="17" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M229.66 218.34l-50.07-50.06a88.11 88.11 0 1 0-11.31 11.31l50.06 50.07a8 8 0 0 0 11.32-11.32ZM40 112a72 72 0 1 1 72 72 72.08 72.08 0 0 1-72-72Z"/></svg>',
      speaker: '<svg width="18" height="18" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M155.51 24.81a8 8 0 0 0-8.42.88L77.25 80H32a16 16 0 0 0-16 16v64a16 16 0 0 0 16 16h45.25l69.84 54.31A8 8 0 0 0 160 224V32a8 8 0 0 0-4.49-7.19ZM144 204.94l-59.23-46.06A8 8 0 0 0 80 157H32v-58h48a8 8 0 0 0 4.77-1.57L144 51.06Z"/><path d="M192 100a8 8 0 0 0-11.31 11.31 40 40 0 0 1 0 33.38 8 8 0 1 0 11.31 11.31 56 56 0 0 0 0-56Z"/></svg>',
      pause: '<svg width="18" height="18" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M216 48v160a16 16 0 0 1-16 16h-40a16 16 0 0 1-16-16V48a16 16 0 0 1 16-16h40a16 16 0 0 1 16 16ZM96 32H56a16 16 0 0 0-16 16v160a16 16 0 0 0 16 16h40a16 16 0 0 0 16-16V48a16 16 0 0 0-16-16Z"/></svg>',
      star: '<svg width="19" height="19" viewBox="0 0 256 256" fill="none" stroke="currentColor" stroke-width="16" aria-hidden="true"><path d="M128 30l30.6 62 68.4 9.9-49.5 48.2 11.7 68.1L128 187.1l-61.2 31.1 11.7-68.1L29 101.9l68.4-9.9Z" stroke-linejoin="round"/></svg>',
      starFilled: '<svg width="19" height="19" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M128 30l30.6 62 68.4 9.9-49.5 48.2 11.7 68.1L128 187.1l-61.2 31.1 11.7-68.1L29 101.9l68.4-9.9Z"/></svg>',
      check: '<svg width="15" height="15" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M232.49 80.49l-128 128a12 12 0 0 1-17 0l-56-56a12 12 0 1 1 17-17L96 183 215.51 63.51a12 12 0 0 1 17 17Z"/></svg>',
      prev: '<svg width="15" height="15" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M165.66 202.34a8 8 0 0 1-11.32 11.32l-80-80a8 8 0 0 1 0-11.32l80-80a8 8 0 0 1 11.32 11.32L91.31 128Z"/></svg>',
      next: '<svg width="15" height="15" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M90.34 53.66a8 8 0 0 1 11.32-11.32l80 80a8 8 0 0 1 0 11.32l-80 80a8 8 0 0 1-11.32-11.32L164.69 128Z"/></svg>',
      more: '<svg width="17" height="17" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><circle cx="128" cy="128" r="15"/><circle cx="60" cy="128" r="15"/><circle cx="196" cy="128" r="15"/></svg>',
      filter: '<svg width="16" height="16" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><path d="M40 64a8 8 0 0 1 8-8h160a8 8 0 0 1 0 16H48a8 8 0 0 1-8-8Zm24 64a8 8 0 0 1 8-8h112a8 8 0 0 1 0 16H72a8 8 0 0 1-8-8Zm32 64a8 8 0 0 1 8-8h48a8 8 0 0 1 0 16h-48a8 8 0 0 1-8-8Z"/></svg>',
    };
    function readAudioVoiceFavorites() {
      try {
        const list = JSON.parse(localStorage.getItem(AUDIO_VOICE_FAVORITES_KEY) ?? '[]');
        return Array.isArray(list) ? list.filter(item => typeof item === 'string') : [];
      } catch (error) { return []; }
    }
    function writeAudioVoiceFavorites(list) {
      try { localStorage.setItem(AUDIO_VOICE_FAVORITES_KEY, JSON.stringify(list)); } catch (error) { /* 忽略配额异常 */ }
    }
    function readAudioVoiceRecents() {
      try {
        const list = JSON.parse(localStorage.getItem(AUDIO_VOICE_RECENTS_KEY) ?? '[]');
        return Array.isArray(list) ? list.filter(item => typeof item === 'string') : [];
      } catch (error) { return []; }
    }
    /** 记一笔「用过的音色」（最多 8 条，最近的在最前）。 */
    function rememberAudioVoice(voice) {
      const value = String(voice || '').trim();
      if (!value) return;
      const next = [value, ...readAudioVoiceRecents().filter(item => item !== value)].slice(0, 8);
      try { localStorage.setItem(AUDIO_VOICE_RECENTS_KEY, JSON.stringify(next)); } catch (error) { /* 忽略配额异常 */ }
    }
    // ★★ 音色 id → 显示名（`zh_female_vv_uranus_bigtts` → `Vivi 2.0`）。
    //   底栏那颗「音色」标签以前只能显示 **id**（自由文本行没有 options，拿不到 label），
    //   而列表里的名字是从上游音色表来的。这里把拉到的映射落一份到 localStorage：
    //   底栏、规格摘要、tooltip 都能显示人看得懂的名字，且**不需要为了标签再多发一次请求**。
    const AUDIO_VOICE_NAMES_KEY = 'canvasflow-audio-voice-names';
    const AUDIO_VOICE_NAMES_MAX = 300;
    function readAudioVoiceNames() {
      try {
        const map = JSON.parse(localStorage.getItem(AUDIO_VOICE_NAMES_KEY) || '{}');
        return map && typeof map === 'object' && !Array.isArray(map) ? map : {};
      } catch (error) { return {}; }
    }
    function rememberAudioVoiceNames(voices) {
      const list = Array.isArray(voices) ? voices : [];
      if (!list.length) return;
      const map = readAudioVoiceNames();
      let added = 0;
      list.forEach(voice => {
        const id = String(voice?.id || '').trim();
        const name = String(voice?.name || '').trim();
        if (!id || !name || name === id) return;
        if (map[id] !== name) added += 1;
        delete map[id];
        map[id] = name;
      });
      if (!added) return;
      // 超出上限时丢最早写进来的那些（对象的键顺序就是插入顺序）。
      const keys = Object.keys(map);
      if (keys.length > AUDIO_VOICE_NAMES_MAX) {
        keys.slice(0, keys.length - AUDIO_VOICE_NAMES_MAX).forEach(key => delete map[key]);
      }
      try { localStorage.setItem(AUDIO_VOICE_NAMES_KEY, JSON.stringify(map)); } catch (error) { /* 忽略配额异常 */ }
    }
    /** 音色 id → 显示名；查不到就返回 id 本身。 */
    function audioVoiceDisplayName(value) {
      const text = String(value || '').trim();
      if (!text) return '';
      return readAudioVoiceNames()[text] || text;
    }

    function audioVoicePager(current, total) {
      if (total <= 5) return Array.from({ length: total }, (unused, index) => index + 1);
      const nums = [...new Set([1, total, current - 1, current, current + 1].filter(n => n >= 1 && n <= total))].sort((a, b) => a - b);
      const out = [];
      nums.forEach((n, index) => {
        const prev = nums[index - 1];
        if (prev && n - prev > 1) out.push(prev === 1 ? 'ellipsis-left' : 'ellipsis-right');
        out.push(n);
      });
      return out;
    }














    function openAudioVoiceDialog() {
      $('.audio-voice-layer')?.remove();
      const catalog = audioVoiceCatalog();
      const voiceRow = audioVoiceRow();
      const builtinOnly = catalog.source === 'builtin';
      let tab = 'library';
      let query = '';
      let page = 1;
      let pageSize = AUDIO_VOICE_PAGE_SIZE;
      let jump = '';
      let favorites = readAudioVoiceFavorites();
      let recents = readAudioVoiceRecents();
      const filters = { gender: '', language: '', scene: '', capability: '' };
      let filterOpen = false;
      let moreMenu = '';
      let previewing = null;
      let previewAudio = null;
      let refocusSearch = false;
      let remote = { loading: true, voices: [], filters: null, error: '' };
      const layer = document.createElement('div');
      layer.className = 'audio-voice-layer';
      document.body.appendChild(layer);
      const stopPreview = () => { try { previewAudio?.pause(); } catch (error) { /* noop */ } previewAudio = null; previewing = null; };
      const close = () => { stopPreview(); document.removeEventListener('keydown', onKey, true); layer.remove(); };
      const onKey = event => {
        if (event.key !== 'Escape') return;
        event.stopPropagation();
        // Esc 先收浮层（⋯ 菜单 / 筛选面板），再关弹层 —— 与其它弹层的行为一致。
        if (moreMenu || filterOpen) { moreMenu = ''; filterOpen = false; return render(); }
        close();
      };
      // 自由文本音色的保存（只在「拉不到音色表 且 登记行没有选项」时才会出现）。
      const saveFreeform = value => {
        const text = String(value || '').trim();
        if (voiceRow) setAudioSpecValue(voiceRow.key, text);
        else localStorage.setItem('canvasflow-audio-voice', text);
        updateAudioDockLabels();
        showToast(text ? `已设置音色：${text}` : '已清空音色（改用模型默认）', '♪');
        close();
      };
      /** 列表条目：远端 → 登记表 → 内置库，形状统一成 `{value,name,description,meta,demo,raw}`。 */
      const items = () => {
        if (remote.voices.length) {
          return remote.voices.map(voice => ({
            value: voice.id,
            name: voice.name || voice.id,
            description: voice.description || '',
            meta: [voice.language, voice.gender, voice.scene].filter(Boolean),
            demo: voice.demo || '',
            raw: voice,
          }));
        }
        return catalog.items.map(item => ({
          value: String(item.value),
          name: String(item.value),
          description: String(item.description || ''),
          meta: [],
          // 内置库的试听样本是 OpenAI 的 CDN 直链；登记表来源没有样本 → 不给试听按钮。
          demo: builtinOnly ? AUDIO_VOICE_PREVIEW_URL(item.value) : '',
          raw: null,
        }));
      };
      const matchesFilters = item => {
        const raw = item.raw || {};
        if (filters.gender && raw.gender !== filters.gender) return false;
        if (filters.language && raw.language !== filters.language) return false;
        if (filters.scene && raw.scene !== filters.scene) return false;
        if (filters.capability
            && !String(raw.capability || '').split(',').map(part => part.trim()).includes(filters.capability)) return false;
        return true;
      };
      const visibleItems = () => {
        const q = query.trim().toLowerCase();
        return items().filter(item => {
          if (tab === 'favorites' && !favorites.includes(item.value)) return false;
          if (tab === 'recent' && !recents.includes(item.value)) return false;
          if (!matchesFilters(item)) return false;
          if (!q) return true;
          return `${item.name} ${item.value} ${item.description} ${item.meta.join(' ')}`.toLowerCase().includes(q);
        });
      };
      const activeFilterCount = () => Object.values(filters).filter(Boolean).length;
      const emptyText = () => {
        if (remote.loading) return '正在读取该模型的音色…';
        if (tab === 'favorites') return favorites.length ? '没有符合筛选条件的收藏音色' : '还没有收藏音色';
        if (tab === 'recent') return '还没有使用记录（选过一次就会出现在这里）';
        if (query.trim() || activeFilterCount()) return '没有匹配的音色';
        return '这个模型没有可用的音色列表';
      };
      const selectVoice = value => {
        const text = String(value || '').trim();
        if (!text) return;
        if (voiceRow) setAudioSpecValue(voiceRow.key, text);
        else localStorage.setItem('canvasflow-audio-voice', text);
        rememberAudioVoice(text);
        recents = readAudioVoiceRecents();
        updateAudioDockLabels();
        const hit = items().find(item => item.value === text);
        showToast(`已选择音色：${hit ? hit.name : text}`, '♪');

        render();
      };
      const filterGroupHtml = (key, label, values) => {
        if (!values || !values.length) return '';
        return `<div class="audio-voice-filter-group"><span>${label}</span><div>${[['', '全部']]
          .concat(values.map(value => [value, value]))
          .map(([value, text]) => `<button type="button" class="${filters[key] === value ? 'is-active' : ''}" data-voice-filter="${key}" data-voice-filter-value="${escapeHtml(value)}">${escapeHtml(text)}</button>`)
          .join('')}</div></div>`;
      };
      const rowHtml = item => {
        const isCurrent = item.value === audioVoiceId();
        const isFav = favorites.includes(item.value);
        const playing = previewing === item.value;
        return `<div class="audio-voice-row${isCurrent ? ' is-selected' : ''}">
          ${item.demo
            ? `<button type="button" class="audio-voice-row__icon${playing ? ' is-playing' : ''}" title="${playing ? '停止试听' : '试听'}" aria-label="${playing ? '停止试听' : '试听'} ${escapeHtml(item.name)}" data-voice-preview="${escapeHtml(item.value)}">${playing ? AUDIO_VOICE_ICONS.pause : AUDIO_VOICE_ICONS.speaker}</button>`
            : '<span class="audio-voice-row__icon is-empty" aria-hidden="true"></span>'}
          <span class="audio-voice-row__name"><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.description || item.value)}</small></span>
          <span class="audio-voice-row__meta">${item.meta.map(text => `<i>${escapeHtml(text)}</i>`).join('')}</span>
          <button type="button" class="audio-voice-row__select" ${isCurrent ? 'disabled' : ''} data-voice-select="${escapeHtml(item.value)}">${isCurrent ? `${AUDIO_VOICE_ICONS.check} 已选` : '选择'}</button>
          <button type="button" class="audio-voice-row__favorite${isFav ? ' is-favorite' : ''}" title="${isFav ? '取消收藏' : '收藏音色'}" aria-label="${isFav ? '取消收藏' : '收藏'} ${escapeHtml(item.name)}" aria-pressed="${isFav}" data-voice-favorite="${escapeHtml(item.value)}">${isFav ? AUDIO_VOICE_ICONS.starFilled : AUDIO_VOICE_ICONS.star}</button>
          <button type="button" class="audio-voice-row__more" title="更多" aria-label="更多操作" aria-expanded="${moreMenu === item.value}" data-voice-more="${escapeHtml(item.value)}">${AUDIO_VOICE_ICONS.more}</button>
        </div>`;
      };
      /** 浮层（⋯ 菜单 / 筛选面板）**挂在 layer 上**并 `position:fixed` 定位：
       *  弹层本身是 `overflow:hidden` 的，放在里面会被裁掉（实测会被截成半截）。 */
      const mountFloaters = list => {
        if (moreMenu) {
          const anchor = layer.querySelector(`[data-voice-more="${CSS.escape(moreMenu)}"]`);
          const item = list.find(entry => entry.value === moreMenu);
          if (anchor && item) {
            const menu = document.createElement('div');
            menu.className = 'audio-voice-more-menu';
            menu.setAttribute('role', 'menu');
            menu.innerHTML = `<button type="button" role="menuitem" data-voice-copy="${escapeHtml(item.value)}">复制音色 ID</button>
              ${item.demo ? `<button type="button" role="menuitem" data-voice-preview="${escapeHtml(item.value)}">试听</button>` : ''}`;
            const rect = anchor.getBoundingClientRect();
            menu.style.left = `${Math.round(Math.max(8, Math.min(window.innerWidth - 156, rect.right - 156)))}px`;
            menu.style.top = `${Math.round(Math.min(window.innerHeight - 90, rect.bottom + 6))}px`;
            layer.appendChild(menu);
          } else {
            moreMenu = '';
          }
        }
        if (filterOpen) {
          const anchor = layer.querySelector('[data-voice-filter-toggle]');
          if (anchor) {
            const menu = document.createElement('div');
            menu.className = 'audio-voice-filter-menu';
            menu.setAttribute('role', 'dialog');
            menu.setAttribute('aria-label', '筛选音色');
            menu.innerHTML = `${filterGroupHtml('gender', '性别', remote.filters?.genders)}
              ${filterGroupHtml('language', '语种', remote.filters?.languages)}
              ${filterGroupHtml('scene', '场景', remote.filters?.scenes)}
              ${filterGroupHtml('capability', '能力', remote.filters?.capabilities)}
              ${activeFilterCount() ? '<button type="button" class="audio-voice-filter-reset" data-voice-filter-reset>重置筛选</button>' : ''}`;
            const rect = anchor.getBoundingClientRect();
            menu.style.left = `${Math.round(Math.max(8, Math.min(window.innerWidth - 320, rect.left)))}px`;
            menu.style.top = `${Math.round(Math.min(window.innerHeight - 260, rect.bottom + 6))}px`;
            layer.appendChild(menu);
          } else {
            filterOpen = false;
          }
        }
      };
      const renderFreeform = () => {
        const value = audioVoiceId();
        layer.innerHTML = `<section class="audio-voice-dialog" role="dialog" aria-modal="true" aria-label="音色">
          <header><strong>音色</strong><button type="button" class="audio-voice-close" title="关闭" aria-label="关闭">${AUDIO_VOICE_ICONS.close}</button></header>
          <div class="audio-voice-controls">
            <label class="audio-voice-search">${AUDIO_VOICE_ICONS.speaker}
              <input type="text" data-voice-freeform placeholder="填写上游要求的音色 ID（留空 = 用模型默认）" value="${escapeHtml(value)}" spellcheck="false" />
            </label>
          </div>
          <footer class="audio-voice-pagination"><span>该模型的音色是自由文本参数，请按供应商文档填写${remote.error ? `（音色表拉取失败：${escapeHtml(remote.error)}）` : ''}</span>
            <button type="button" class="spec-btn" data-voice-freeform-save>保存</button></footer>
        </section>`;
        const input = layer.querySelector('[data-voice-freeform]');
        input?.focus();
        input?.addEventListener('keydown', event => {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          saveFreeform(input.value);
        });
      };
      const render = () => {
        // 自由文本 + 拉不到音色表 → 保持输入框（r860 的行为）；一旦拿到音色表就升级成列表。
        if (!remote.loading && !remote.voices.length && catalog.freeform) return renderFreeform();
        const list = visibleItems();
        const totalPages = Math.max(1, Math.ceil(list.length / pageSize));
        if (page > totalPages) page = totalPages;
        const rows = list.slice((page - 1) * pageSize, page * pageSize);
        const chips = remote.filters || null;
        const hasChips = chips && (chips.genders.length || chips.languages.length || chips.scenes.length || chips.capabilities.length);
        layer.innerHTML = `<section class="audio-voice-dialog" role="dialog" aria-modal="true" aria-label="音色选择">
          <header><strong>音色选择</strong><button type="button" class="audio-voice-close" title="关闭" aria-label="关闭音色选择">${AUDIO_VOICE_ICONS.close}</button></header>
          <div class="audio-voice-controls">
            <div class="audio-voice-tabs" role="tablist" aria-label="音色分类">
              <button type="button" role="tab" aria-selected="${tab === 'library'}" class="${tab === 'library' ? 'is-active' : ''}" data-voice-tab="library">音色库</button>
              <button type="button" role="tab" aria-selected="${tab === 'recent'}" class="${tab === 'recent' ? 'is-active' : ''}" data-voice-tab="recent">最近使用 <span>${recents.length}</span></button>
              <button type="button" role="tab" aria-selected="${tab === 'favorites'}" class="${tab === 'favorites' ? 'is-active' : ''}" data-voice-tab="favorites">收藏音色 <span>${favorites.length}</span></button>
            </div>
            <label class="audio-voice-search">${AUDIO_VOICE_ICONS.search}<input type="search" placeholder="搜索音色库" value="${escapeHtml(query)}" /></label>
            ${hasChips ? `<button type="button" class="audio-voice-filter${activeFilterCount() ? ' is-active' : ''}" data-voice-filter-toggle aria-haspopup="dialog" aria-expanded="${filterOpen}">${AUDIO_VOICE_ICONS.filter}<span>筛选</span>${activeFilterCount() ? `<i>${activeFilterCount()}</i>` : ''}</button>` : ''}
          </div>
          <div class="audio-voice-list">${rows.length ? rows.map(rowHtml).join('') : `<div class="audio-voice-empty">${emptyText()}</div>`}</div>
          <footer class="audio-voice-pagination">
            <nav class="audio-voice-pager" aria-label="音色分页">
              <button type="button" aria-label="上一页" ${page === 1 ? 'disabled' : ''} data-voice-page="prev">${AUDIO_VOICE_ICONS.prev}</button>
              ${audioVoicePager(page, totalPages).map(n => typeof n === 'number'
                ? `<button type="button" class="${n === page ? 'is-active' : ''}" data-voice-page="${n}">${n}</button>`
                : '<span>…</span>').join('')}
              <button type="button" aria-label="下一页" ${page === totalPages ? 'disabled' : ''} data-voice-page="next">${AUDIO_VOICE_ICONS.next}</button>
            </nav>
            <div class="audio-voice-pagesize">
              <select data-voice-pagesize aria-label="每页条数">${[20, 50, 100].map(n => `<option value="${n}"${n === pageSize ? ' selected' : ''}>${n}条/页</option>`).join('')}</select>
              <span>跳至</span><input type="number" min="1" max="${totalPages}" value="${escapeHtml(jump)}" data-voice-jump aria-label="跳至第几页" placeholder="${page}" /><span>页</span>
            </div>
            <span class="audio-voice-total">共 ${list.length} 条${remote.loading ? '（正在读取…）' : ''}</span>
          </footer>
        </section>`;
        mountFloaters(list);
        if (refocusSearch) {
          const input = layer.querySelector('.audio-voice-search input');
          if (input) { input.focus(); input.setSelectionRange(input.value.length, input.value.length); }
          refocusSearch = false;
        }
      };
      const togglePreview = item => {
        const url = typeof item === 'string' ? item : (item && item.demo) || '';
        const key = typeof item === 'string' ? item : (item && item.value) || '';
        if (!url) return showToast('这个音色没有试听样本', '×');
        if (previewing === key) { stopPreview(); render(); return; }
        stopPreview();
        const audio = new Audio(url);
        previewAudio = audio;
        previewing = key;
        audio.onended = () => { if (previewing === key) { previewing = null; previewAudio = null; render(); } };
        audio.onerror = () => { if (previewing === key) { previewing = null; previewAudio = null; showToast('试听样本加载失败（需要联网）', '×'); render(); } };
        audio.play().catch(() => { if (previewing === key) { previewing = null; previewAudio = null; showToast('试听样本加载失败（需要联网）', '×'); render(); } });
        render();
      };
      const previewOf = value => items().find(item => item.value === value);
      layer.addEventListener('click', event => {
        if (event.target === layer || event.target.closest('.audio-voice-close')) return close();
        if (event.target.closest('[data-voice-freeform-save]')) {
          return saveFreeform(layer.querySelector('[data-voice-freeform]')?.value || '');
        }
        const filterToggle = event.target.closest('[data-voice-filter-toggle]');
        if (filterToggle) { moreMenu = ''; filterOpen = !filterOpen; return render(); }
        const filterBtn = event.target.closest('[data-voice-filter]');
        if (filterBtn) {
          const key = filterBtn.dataset.voiceFilter;
          filters[key] = filters[key] === filterBtn.dataset.voiceFilterValue ? '' : filterBtn.dataset.voiceFilterValue;
          page = 1;
          return render();
        }
        if (event.target.closest('[data-voice-filter-reset]')) {
          Object.keys(filters).forEach(key => { filters[key] = ''; });
          page = 1;
          return render();
        }
        const moreBtn = event.target.closest('[data-voice-more]');
        if (moreBtn) {
          filterOpen = false;
          moreMenu = moreMenu === moreBtn.dataset.voiceMore ? '' : moreBtn.dataset.voiceMore;
          return render();
        }
        const copyBtn = event.target.closest('[data-voice-copy]');
        if (copyBtn) {
          const value = copyBtn.dataset.voiceCopy;
          moreMenu = '';
          navigator.clipboard?.writeText(value)
            .then(() => showToast(`已复制音色 ID：${value}`, '✓'))
            .catch(() => showToast('复制失败，请手动选择复制', '×'));
          return render();
        }
        const tabBtn = event.target.closest('[data-voice-tab]');
        if (tabBtn) { stopPreview(); moreMenu = ''; tab = tabBtn.dataset.voiceTab; page = 1; return render(); }
        const favBtn = event.target.closest('[data-voice-favorite]');
        if (favBtn) {
          const voice = favBtn.dataset.voiceFavorite;
          favorites = favorites.includes(voice) ? favorites.filter(item => item !== voice) : [...favorites, voice];
          writeAudioVoiceFavorites(favorites);
          return render();
        }
        const selectBtn = event.target.closest('[data-voice-select]');
        if (selectBtn && !selectBtn.disabled) return selectVoice(selectBtn.dataset.voiceSelect);
        const previewBtn = event.target.closest('[data-voice-preview]');
        if (previewBtn) return togglePreview(previewOf(previewBtn.dataset.voicePreview) || previewBtn.dataset.voicePreview);
        const pageBtn = event.target.closest('[data-voice-page]');
        if (pageBtn && !pageBtn.disabled) {
          stopPreview();
          const value = pageBtn.dataset.voicePage;
          if (value === 'prev') page = Math.max(1, page - 1);
          else if (value === 'next') page += 1;
          else page = Number(value) || 1;
          jump = '';
          return render();
        }
      });
      layer.addEventListener('input', event => {
        if (event.target.matches('.audio-voice-search input')) {
          stopPreview();
          query = event.target.value;
          page = 1;
          refocusSearch = true;
          render();
        }
        if (event.target.matches('[data-voice-jump]')) jump = event.target.value;
      });
      layer.addEventListener('change', event => {
        if (event.target.matches('[data-voice-pagesize]')) {
          pageSize = Number(event.target.value) || AUDIO_VOICE_PAGE_SIZE;
          page = 1;
          return render();
        }
        if (event.target.matches('[data-voice-jump]')) {
          const target = Math.max(1, Number(event.target.value) || 1);
          page = target;
          jump = '';
          return render();
        }
      });
      document.addEventListener('keydown', onKey, true);
      render();
      // ★ 音色表**异步**拉：先把本地兜底渲染出来，拿到再重绘 —— 打开弹层不等网络。
      (async () => {
        const model = currentAudioModel();
        if (!model?.id || isStandaloneFile()) { remote.loading = false; if (layer.isConnected) render(); return; }
        const result = await api(`/api/ai/voices?modelId=${encodeURIComponent(model.id)}`).catch(() => null);
        remote.loading = false;
        remote.voices = Array.isArray(result?.voices) ? result.voices : [];
        remote.filters = result?.filters || null;
        remote.error = result?.error || '';
        // 音色 id → 名字落一份，底栏标签 / 摘要 / tooltip 就不用再发请求也能显示人话。
        rememberAudioVoiceNames(remote.voices);
        if (layer.isConnected) { render(); updateAudioDockLabels(); }
      })();
    }

