    const AUDIO_SPEC_FALLBACK = [];









    function audioSpecSchema() {
      const model = currentAudioModel();
      const upstream = String(model?.model || '').trim();
      const byName = String(model?.name || '').trim();
      const remote = state.modelSpecs?.audio;
      if (remote && typeof remote === 'object') {
        for (const key of [upstream, byName]) {
          if (key && Object.prototype.hasOwnProperty.call(remote, key)) {
            return Array.isArray(remote[key]) ? remote[key] : [];
          }
        }
        return [];   // 登记表已加载但没有这个模型 → 空面板（诚实，别硬塞一份上游不认的参数）
      }
      if (upstream && Object.prototype.hasOwnProperty.call(AUDIO_SPEC_SCHEMAS, upstream)) return AUDIO_SPEC_SCHEMAS[upstream];
      // 上游名对不上时再用展示名兜一次（后台可能只填了「suno-v4.5」这种名字）。
      if (byName && Object.prototype.hasOwnProperty.call(AUDIO_SPEC_SCHEMAS, byName)) return AUDIO_SPEC_SCHEMAS[byName];
      return AUDIO_SPEC_FALLBACK;
    }
    function readAudioSpecRaw() {
      try {
        const parsed = JSON.parse(localStorage.getItem('canvasflow-audio-spec') || '{}');
        return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
      } catch { return {}; }
    }
    // ★★★ 白名单重建式归一化（同 normalizeImageGenerationSettings）：只带出 schema 里声明的行，
    //   且值必须命中该行的 options，否则回落 default。防止旧值/脏值悄悄发往上游。
    // ★★ r860 补上**自由文本行**（`options` 为空 = 上游声明成 input，如 doubao 的 `voice_id`）：
    //   以前这类行会被 `hit ? … : row.default` 直接压成 `null`（它没有 default）→
    //   用户在音色里填的值被整个丢掉，且不报错（「填了不生效」那一类坑）。
    function normalizeAudioSpec() {
      const raw = readAudioSpecRaw();
      const out = {};
      audioSpecSchema().forEach(row => {
        const options = row.options || [];
        if (!options.length) {
          const value = raw[row.key];
          if (typeof value === 'string' && value.trim()) out[row.key] = value.trim();
          else if (typeof value === 'number') out[row.key] = value;
          return;
        }
        const hit = options.find(option => String(option.value) === String(raw[row.key]));
        out[row.key] = hit ? hit.value : row.default;
      });
      return out;
    }
    function setAudioSpecValue(key, value) {
      const next = { ...normalizeAudioSpec(), [key]: value };
      localStorage.setItem('canvasflow-audio-spec', JSON.stringify(next));
      updateAudioDockLabels();
    }





    function audioSpecPayload() {
      const spec = normalizeAudioSpec();
      const out = {};
      audioSpecSchema().forEach(row => { out[row.field || row.key] = spec[row.key]; });
      return out;
    }

    // ==================== 音频节点的「情绪」→ 提交参数（r860）====================
    // ★★★ 为什么音频**不能**像图片/视频那样把 `[[表情:…]]` 写进提示词：
    //   TTS 的 prompt 就是**要朗读的正文**，展开出来的「@表情：喜悦」会跟正文一起被念出来。
    //   而上游 TTS（doubao-tts-2.0 / speech-2.8 …）自己声明了 `emotion` + `emotion_scale`
    //   两个参数 —— 模型是**读参数**知道该用什么情绪的，所以这里直接写参数。
    // ★ 分工：`EMOTION_TTS_VALUES` 只负责「我们的 10 种情绪 → 上游枚举」的**语义映射**；
    //   真正能发什么值仍由**登记表里该模型声明的 options** 决定（挑不中就不发）。
    //   所以给某个模型加情绪支持 = 在「模型管理 · 音频规格」里登记 emotion / emotion_scale 两行，
    //   不需要改这里的代码。
    const EMOTION_TTS_VALUES = {
      calm: 'calm', joy: 'happy', surprise: 'surprised', fear: 'fearful', anxiety: 'fearful',
      sadness: 'sad', pain: 'sad', suppression: 'calm', disgust: 'angry', anger: 'angry', contempt: 'angry',
    };
    // 上游对这两个参数的命名各家略有出入，按**字段名**认行（key 与 field 都看）。
    const AUDIO_EMOTION_FIELD_RE = /^(emotion|emotion_type|emotion_name|emotion_category|emotion_tag)$/;
    const AUDIO_EMOTION_SCALE_FIELD_RE = /^(emotion_scale|emotion_intensity|emotion_level|emotion_degree|emotion_strength)$/;
    function audioEmotionRows() {
      const rows = audioSpecSchema();
      const name = row => String(row.field || row.key || '').trim().toLowerCase();
      return {
        emotion: rows.find(row => AUDIO_EMOTION_FIELD_RE.test(name(row))) || null,
        scale: rows.find(row => AUDIO_EMOTION_SCALE_FIELD_RE.test(name(row))) || null,
      };
    }
    /** 该模型能不能用表情编辑器 = 登记表里声明了情绪参数（否则点了只能空转，要给出可执行的原因）。 */
    function audioEmotionSupported() { return Boolean(audioEmotionRows().emotion); }
    /** 就近取一个合法值：上游强度档位数与我们的 5 档不一定一致（如 1/2/3 档）。 */
    function nearestSpecOptionValue(row, wanted) {
      const values = (row?.options || []).map(option => option.value);
      if (!values.length) return null;
      const exact = values.find(value => String(value) === String(wanted));
      if (exact !== undefined) return exact;
      const numeric = values.map(value => Number(value)).filter(value => Number.isFinite(value));
      if (!numeric.length) return values[0];
      const target = Number(wanted);
      return numeric.reduce((best, value) => Math.abs(value - target) < Math.abs(best - target) ? value : best, numeric[0]);
    }
    /**
     * 表情编辑器（音频上下文）点「确定」时调用：把情绪 / 强度写进该模型的提交规格。
     * 返回 false = 当前模型没有情绪参数（调用方负责给提示）。
     */
    function applyAudioEmotion(recipeId, level) {
      const { emotion, scale } = audioEmotionRows();
      if (!emotion) return false;
      const mapped = EMOTION_TTS_VALUES[recipeId] || '';
      const emotionValue = (emotion.options || []).some(option => String(option.value) === mapped) ? mapped : emotion.default;
      if (emotionValue !== null && emotionValue !== undefined && emotionValue !== '') setAudioSpecValue(emotion.key, emotionValue);
      if (scale) {
        const scaleValue = nearestSpecOptionValue(scale, level);
        if (scaleValue !== null && scaleValue !== undefined && scaleValue !== '') setAudioSpecValue(scale.key, scaleValue);
      }
      return true;
    }
    /** 当前规格里的情绪 → 表情轮上该选中的点（打开编辑器时回填，避免"打开永远是默认值"）。 */
    function currentAudioEmotionSelection() {
      const { emotion, scale } = audioEmotionRows();
      if (!emotion) return null;
      const spec = normalizeAudioSpec();
      const value = String(spec[emotion.key] ?? '');
      const recipeIds = EMOTION_WHEEL.map(item => item.id).concat(['calm']);
      const recipeId = recipeIds.includes(value)
        ? value
        : (Object.keys(EMOTION_TTS_VALUES).find(key => EMOTION_TTS_VALUES[key] === value) || 'calm');
      const level = scale ? Math.max(1, Math.min(5, Number(spec[scale.key]) || 1)) : 1;
      return { recipeId, level };
    }
    /** 音频上下文下，底部那块「提示词」预览要改成显示**将要提交的参数**（那才是真正发出去的东西）。 */
    function audioEmotionPreviewText(recipeId, level) {
      const { emotion, scale } = audioEmotionRows();
      if (!emotion) return '';
      const mapped = EMOTION_TTS_VALUES[recipeId] || '';
      const emotionValue = (emotion.options || []).some(option => String(option.value) === mapped) ? mapped : emotion.default;
      const parts = [`${emotion.field || emotion.key} = ${emotionValue ?? ''}`];
      if (scale) parts.push(`${scale.field || scale.key} = ${nearestSpecOptionValue(scale, level) ?? ''}`);
      return parts.join(' · ');
    }
    /** 情绪枚举值 → 中文名（`happy` → `喜悦`）。用我们自己那套情绪轮的 label，底栏才不会中英混排。 */
    function emotionValueLabel(value) {
      const text = String(value || '').trim();
      if (!text) return '';
      const recipeId = Object.keys(EMOTION_TTS_VALUES).find(key => EMOTION_TTS_VALUES[key] === text);
      const wheel = EMOTION_WHEEL.find(item => item.id === recipeId);
      return wheel ? wheel.label : text;
    }
    /** 底栏「☺ 情绪」按钮上显示的当前值（`喜悦 3`）；`auto` / 未设置 → 空串。 */
    function currentAudioEmotionLabel() {
      const { emotion, scale } = audioEmotionRows();
      if (!emotion) return '';
      const spec = normalizeAudioSpec();
      const value = String(spec[emotion.key] ?? '').trim();
      // `auto` = 交给模型自己决定，不算"已选情绪"（显示出来反而像用户设过）。
      if (!value || ['auto', 'none', 'neutral', 'default'].includes(value.toLowerCase())) return '';
      const level = scale ? String(spec[scale.key] ?? '').trim() : '';
      const name = emotionValueLabel(value);
      return level ? `${name} ${level}` : name;
    }











    function audioSpecRowHasDedicatedControl(row) {
      const name = String(row?.field || row?.key || '').trim().toLowerCase();
      return [AUDIO_VOICE_FIELD_RE, AUDIO_EMOTION_FIELD_RE, AUDIO_EMOTION_SCALE_FIELD_RE].some(re => re.test(name));
    }
    /** 「规格」面板/摘要该显示的行 = 登记行去掉那些有专门控件的。 */
    function audioSpecVisibleRows() {
      return audioSpecSchema().filter(row => !audioSpecRowHasDedicatedControl(row));
    }

    // ==================== 音色：登记表接管（r860）====================
    // ★★★ 修的是什么：底栏「音色」以前写死 OpenAI 的 9 个音色（alloy / ash / …），
    //   而当前配置的音频模型（doubao-tts-2.0 / suno-v4.5 …）走 `POST /v1/media/generate`，
    //   服务端 `build_media_audio_params()` 只发**模型自己声明过**的键 —— 于是
    //   `voice='alloy'` 连"模型没声明 voice"这一关都过不去，**静默丢弃**：
    //   面板上选了音色、请求体里一个字都没有（与 r844 表情 token 那条是同一类坑）。
    // ★ 修法：音色改成**登记表里的一行**（字段名 voice_id / voice / speaker…），
