      const rows = audioSpecVisibleRows();
      if (!rows.length) return '';
      const picked = rows.map(row => {
        const options = row.options || [];
        if (!options.length) {
          // 自由文本行：摘要有值就显示，没值跳过（别显示一串空白）。
          const value = spec[row.key];
          return value === undefined || value === '' ? null : { label: String(value).slice(0, 12) };
        }
        return options.find(option => String(option.value) === String(spec[row.key])) || options[0];
      }).filter(Boolean);
