    function positionMarquee(x1, y1, x2, y2) {
      if (!marqueeBox) return;
      const bounds = wrap.getBoundingClientRect();
      marqueeBox.style.left = `${Math.min(x1, x2) - bounds.left}px`;
      marqueeBox.style.top = `${Math.min(y1, y2) - bounds.top}px`;
      marqueeBox.style.width = `${Math.abs(x2 - x1)}px`;
      marqueeBox.style.height = `${Math.abs(y2 - y1)}px`;
    }
    function finishMarqueeSelect(event, moved) {
      const d = state.drag; state.drag = null;
      marqueeBox?.remove(); marqueeBox = null;
      if (!moved) { clearNodeSelection(); return; }
      // 节点 getBoundingClientRect 是客户端坐标，框也必须用客户端坐标，否则漏选。
      const box = {
        l: Math.min(d.startX, event.clientX),
        t: Math.min(d.startY, event.clientY),
        r: Math.max(d.startX, event.clientX),
        b: Math.max(d.startY, event.clientY),
      };
      const hits = $$('.flow-node').filter(n => {
        const r = n.getBoundingClientRect();
        return !(r.right < box.l || r.left > box.r || r.bottom < box.t || r.top > box.b);
      });
      hits.length ? setMultiSelection(hits) : clearNodeSelection();
    }
